import { optimizeCMap } from "../../../../external/cmapscompress/optimize.mjs";

function makeData(body) {
  return { type: 1, wmode: 0, body };
}

describe("optimizeCMap", () => {
  test("returns undefined and leaves an empty body unchanged", () => {
    const data = makeData([]);

    expect(optimizeCMap(data)).toBeUndefined();
    expect(data).toEqual({ type: 1, wmode: 0, body: [] });
  });

  test("merges adjacent items with the same type", () => {
    const data = makeData([
      { type: 2, items: [{ char: "0000", code: 1 }] },
      { type: 2, items: [{ char: "0004", code: 2 }] },
      { type: 4, items: [{ char: "0008", code: "0009" }] },
      { type: 2, items: [{ char: "000c", code: 3 }] },
    ]);

    optimizeCMap(data);

    expect(data.body).toEqual([
      {
        type: 2,
        items: [
          { char: "0000", code: 1 },
          { char: "0004", code: 2 },
        ],
      },
      { type: 4, items: [{ char: "0008", code: "0009" }] },
      { type: 2, items: [{ char: "000c", code: 3 }] },
    ]);
  });

  test("splits items when the length of any string field changes", () => {
    const data = makeData([
      {
        type: 0,
        items: [
          { start: "0000", end: "0" },
          { start: "0001", end: "1" },
          { start: "0002", end: "20" },
          { start: "0003", end: "30" },
        ],
      },
    ]);

    optimizeCMap(data);

    expect(data.body).toEqual([
      {
        type: 0,
        items: [
          { start: "0000", end: "0" },
          { start: "0001", end: "1" },
        ],
      },
      {
        type: 0,
        items: [
          { start: "0002", end: "20" },
          { start: "0003", end: "30" },
        ],
      },
    ]);
  });

  test("does not split when only numeric fields differ", () => {
    const items = [
      { char: "0000", code: 1 },
      { char: "0002", code: 500 },
      { char: "0004", code: 9000 },
    ];
    const data = makeData([{ type: 2, items: items.map(item => ({ ...item })) }]);

    optimizeCMap(data);

    expect(data.body).toEqual([{ type: 2, items }]);
  });

  test("converts exactly nine single-character type-5 ranges in place", () => {
    const codePoints = Array.from({ length: 9 }, (_, index) => 65 + index);
    const data = makeData([
      {
        type: 5,
        items: codePoints.map(code => ({
          start: "0041",
          end: "0041",
          code,
        })),
      },
    ]);

    optimizeCMap(data);

    expect(data.body).toEqual([
      {
        type: 4,
        items: codePoints.map(code => ({ char: "0041", code })),
      },
    ]);
  });

  test("does not convert a run of only eight single-character ranges", () => {
    const items = Array.from({ length: 8 }, (_, index) => ({
      start: "0041",
      end: "0041",
      code: 65 + index,
    }));
    const data = makeData([{ type: 5, items: items.map(item => ({ ...item })) }]);

    optimizeCMap(data);

    expect(data.body).toEqual([{ type: 5, items }]);
  });

  test("splits a single-character type-3 run from surrounding ranges", () => {
    const data = makeData([
      {
        type: 3,
        items: [
          { start: "0030", end: "0031", code: 10 },
          { start: "0032", end: "0033", code: 11 },
          ...Array.from({ length: 9 }, (_, index) => ({
            start: "0041",
            end: "0041",
            code: 65 + index,
          })),
          { start: "0100", end: "0101", code: 100 },
        ],
      },
    ]);

    optimizeCMap(data);

    expect(data.body).toEqual([
      {
        type: 3,
        items: [
          { start: "0030", end: "0031", code: 10 },
          { start: "0032", end: "0033", code: 11 },
        ],
      },
      {
        type: 2,
        items: Array.from({ length: 9 }, (_, index) => ({
          char: "0041",
          code: 65 + index,
        })),
      },
      { type: 3, items: [{ start: "0100", end: "0101", code: 100 }] },
    ]);
  });

  test("marks exactly nine increasing ranges as a sequence", () => {
    const items = Array.from({ length: 9 }, (_, index) => ({
      char: String(100 + index),
      code: 200 + index,
    }));
    const data = makeData([{ type: 2, items: items.map(item => ({ ...item })) }]);

    optimizeCMap(data);

    expect(data.body).toEqual([{ type: 2, items, sequence: true }]);
  });

  test("does not mark a run of only eight increasing ranges as a sequence", () => {
