          })),
          { char: "0500", code: "0030" },
          { char: "0501", code: "0031" },
        ],
      },
    ]);

    optimizeCMap(data);

    expect(data.body).toEqual([
      {
        type: 4,
        items: [
          { char: "0200", code: "0001" },
          { char: "0300", code: "0002" },
        ],
      },
      {
        type: 4,
        items: Array.from({ length: 9 }, (_, index) => ({
          char: `040${index}`,
