        })),
        sequence: true,
      },
      {
        type: 4,
        items: [
          { char: "0500", code: "0030" },
          { char: "0501", code: "0031" },
        ],
      },
    ]);
  });

  test("splits a non-sequence type-2 item into code buckets", () => {
    const data = makeData([
      {
        type: 2,
        items: [
          { char: "1000", code: 3000 },
          { char: "0000", code: 0 },
          { char: "2000", code: 1005 },
          { char: "0002", code: 1 },
          { char: "1002", code: 3001 },
          { char: "2002", code: 1006 },
          { char: "0004", code: 2 },
          { char: "1004", code: 3002 },
          { char: "2004", code: 1007 },
          { char: "0006", code: 3 },
          { char: "1006", code: 3003 },
          { char: "2006", code: 1008 },
        ],
      },
    ]);

    optimizeCMap(data);

    expect(data.body).toEqual([
      {
        type: 2,
        items: [
          { char: "0000", code: 0 },
          { char: "0002", code: 1 },
          { char: "0004", code: 2 },
          { char: "0006", code: 3 },
        ],
      },
      {
        type: 2,
        items: [
          { char: "2000", code: 1005 },
          { char: "2002", code: 1006 },
          { char: "2004", code: 1007 },
          { char: "2006", code: 1008 },
        ],
      },
      {
        type: 2,
        items: [
          { char: "1000", code: 3000 },
          { char: "1002", code: 3001 },
          { char: "1004", code: 3002 },
          { char: "1006", code: 3003 },
        ],
      },
    ]);
  });

  test("does not bucket a non-sequence item with exactly ten subitems", () => {
    const items = Array.from({ length: 10 }, (_, index) => ({
      char: `00${index * 2}`,
      code: index * 1000,
    }));
    const data = makeData([{ type: 2, items: items.map(item => ({ ...item })) }]);

    optimizeCMap(data);

    expect(data.body).toEqual([{ type: 2, items }]);
  });

  test("does not bucket when only one code gap reaches the maximum", () => {
    const items = Array.from({ length: 12 }, (_, index) => ({
