function writeTempFile(name, content) {
  const filePath = path.join(tempDir, name);
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, content);
  return filePath;
}

function tempOutputPath() {
  return path.join(tempDir, `output-${++fileCounter}.txt`);
}

function fixture(name) {
  return path.join(fixturesDir, name);
}

function expectedFixtureFor(name) {
  return path.join(fixturesDir, name.replace(/(\.\w+)$/, "-expected$1"));
}

// Runs `preprocess` with a line-collecting callback. Note that, in that mode,
// `writeLine` is the callback itself, so no blank-line collapsing happens.
function collectLines(inputPath, defines = DEFINES) {
  const lines = [];
  preprocess(inputPath, line => lines.push(line), defines);
  return lines;
}

function preprocessToString(inputPath, defines = DEFINES) {
  return collectLines(inputPath, defines).join("\n");
}

// Runs `preprocess` with an output *file name*, which activates the default
// `writeLine` implementation (blank-line collapsing included).
function preprocessToFile(inputPath, defines = DEFINES) {
  const outputPath = tempOutputPath();
  preprocess(inputPath, outputPath, defines);
  return fs.readFileSync(outputPath, "utf8");
}

function captureError(inputPath, defines = DEFINES) {
  let error;
  try {
    preprocess(inputPath, () => {}, defines);
  } catch (e) {
    error = e;
  }
  return error;
}

