{"command": "cd /testbed; cat > test/core/bidi/bidi.test.js <<'EOF'
import { bidi } from "../../../src/core/bidi.js";
import {
  getVerbosityLevel,
  setVerbosityLevel,
  VerbosityLevel,
} from "../../../src/shared/util.js";

const HEBREW_ALEF = "\u05d0";
const HEBREW_BET = "\u05d1";
const HEBREW_GIMEL = "\u05d2";

describe("bidi", () => {
  afterEach(() => {
    jest.restoreAllMocks();
  });

  describe("direction detection", () => {
    it("returns an empty string with ltr direction", () => {
      expect(bidi("")).toEqual({ str: "", dir: "ltr" });
    });

    it("leaves LTR-only text unchanged", () => {
      expect(bidi("Hello, world! 123")).toEqual({
        str: "Hello, world! 123",
        dir: "ltr",
      });
    });

    it("does not strip angle brackets when no bidi processing is needed", () => {
      expect(bidi("<b>plain</b>")).toEqual({
        str: "<b>plain</b>",
        dir: "ltr",
      });
    });

    it("marks a single Hebrew character as rtl", () => {
      expect(bidi(HEBREW_ALEF)).toEqual({ str: HEBREW_ALEF, dir: "rtl" });
    });

    it("reverses a purely Hebrew string and marks it rtl", () => {
      expect(bidi(`${HEBREW_ALEF}${HEBREW_BET}${HEBREW_GIMEL}`)).toEqual({
        str: `${HEBREW_GIMEL}${HEBREW_BET}${HEBREW_ALEF}`,
        dir: "rtl",
      });
    });

    it("reverses a purely Arabic string and marks it rtl", () => {
      expect(bidi("\u0627\u0628\u062c")).toEqual({
        str: "\u062c\u0628\u0627",
        dir: "rtl",
      });
    });

    it("reorders a primarily RTL mixed string", () => {
      expect(bidi(`abc ${HEBREW_ALEF}${HEBREW_BET}`)).toEqual({
        str: `${HEBREW_BET}${HEBREW_ALEF} abc`,
        dir: "rtl",
      });
    });

    it("keeps a long predominantly LTR string free of reordering", () => {
      expect(bidi(`abcdefg ${HEBREW_ALEF}`)).toEqual({
        str: `abcdefg ${HEBREW_ALEF}`,
        dir: "ltr",
      });
    });

    it("treats exactly 30% RTL characters as primarily RTL", () => {
      expect(
        bidi(
          `abcdefg${HEBREW_ALEF}${HEBREW_BET}${HEBREW_GIMEL}`
        )
      ).toEqual({
        str: `${HEBREW_GIMEL}${HEBREW_BET}${HEBREW_ALEF}abcdefg`,
        dir: "rtl",
      });
    });

    it("treats short strings containing RTL characters as primarily RTL", () => {
      expect(bidi(`abc${HEBREW_ALEF}`)).toEqual({
        str: `${HEBREW_ALEF}abc`,
        dir: "rtl",
      });
    });
  });

  describe("vertical text", () => {
    it("returns ttb direction and leaves the content untouched", () => {
      expect(bidi(`${HEBREW_ALEF}${HEBREW_BET}`, -1, true)).toEqual({
        str: `${HEBREW_ALEF}${HEBREW_BET}`,
        dir: "ttb",
      });
    });

    it("returns ttb direction for an empty string", () => {
      expect(bidi("", -1, true)).toEqual({ str: "", dir: "ttb" });
    });
  });

  describe("numbers, marks and neutrals", () => {
    it("keeps Arabic-Indic digits in logical order", () => {
      expect(bidi("\u0661\u0662\u0663")).toEqual({
        str: "\u0661\u0662\u0663",
        dir: "rtl",
      });
    });

    it("places a European digit to the left of surrounding RTL text", () => {
      expect(bidi(`${HEBREW_ALEF} 1`)).toEqual({
        str: `1 ${HEBREW_ALEF}`,
        dir: "rtl",
      });
      expect(bidi(`1${HEBREW_ALEF}`)).toEqual({
        str: `${HEBREW_ALEF}1`,
        dir: "rtl",
      });
    });

    it("keeps a combining mark adjacent to its base character", () => {
      expect(bidi(`${HEBREW_ALEF}\u05b0${HEBREW_BET}`)).toEqual({
        str: `${HEBREW_BET}\u05b0${HEBREW_ALEF}`,
        dir: "rtl",
      });
    });

    it("reorders neutral punctuation together with RTL text", () => {
      expect(bidi(`${HEBREW_ALEF}"${HEBREW_BET}`)).toEqual({
        str: `${HEBREW_BET}"${HEBREW_ALEF}`,
        dir: "rtl",
      });
    });
  });

  describe("explicit start level", () => {
    it("keeps LTR text first when an even start level is requested", () => {
      expect(bidi(`abc${HEBREW_ALEF}`, 0)).toEqual({
        str: `abc${HEBREW_ALEF}`,
        dir: "ltr",
      });
    });

    it("puts RTL text first when an odd start level is requested", () => {
      expect(bidi(`abc${HEBREW_ALEF}`, 1)).toEqual({
        str: `${HEBREW_ALEF}abc`,
        dir: "ltr",
      });
    });

    it("reports ltr when the start level is set explicitly", () => {
      expect(bidi(`${HEBREW_ALEF}${HEBREW_BET}`, 0).dir).toBe("ltr");
      expect(bidi(`${HEBREW_ALEF}${HEBREW_BET}`, 1).dir).toBe("ltr");
    });
  });

  describe("angle bracket sanitizing", () => {
    it("removes angle brackets from bidi-processed text", () => {
      expect(bidi(`${HEBREW_ALEF}<${HEBREW_BET}>`)).toEqual({
        str: `${HEBREW_BET}${HEBREW_ALEF}`,
        dir: "rtl",
      });
    });

    it("removes all angle brackets wherever they occur", () => {
      expect(bidi(`${HEBREW_ALEF}>a<${HEBREW_BET}`)).toEqual({
        str: `${HEBREW_BET}a${HEBREW_ALEF}`,
        dir: "rtl",
      });
    });

    it("removes angle brackets even when they are the only neutral text", () => {
      expect(bidi(`${HEBREW_ALEF}<>`)).toEqual({
        str: HEBREW_ALEF,
        dir: "rtl",
      });
    });

    it("leaves other punctuation untouched", () => {
      expect(bidi(`${HEBREW_ALEF}&${HEBREW_BET}`)).toEqual({
        str: `${HEBREW_BET}&${HEBREW_ALEF}`,
        dir: "rtl",
      });
    });
  });

  describe("state isolation", () => {
    it("produces correct results across consecutive calls", () => {
      expect(bidi(`${HEBREW_ALEF}${HEBREW_BET}${HEBREW_GIMEL}\u05d3\u05d4\u05d5`)).toEqual({
        str: `\u05d5\u05d4\u05d3${HEBREW_GIMEL}${HEBREW_BET}${HEBREW_ALEF}`,
        dir: "rtl",
      });
      expect(bidi(`${HEBREW_ALEF}${HEBREW_BET}`)).toEqual({
        str: `${HEBREW_BET}${HEBREW_ALEF}`,
        dir: "rtl",
      });
      expect(bidi("abc")).toEqual({ str: "abc", dir: "ltr" });
    });
  });

  describe("invalid Unicode characters", () => {
    it("warns about characters missing from the Arabic type table", () => {
      const previousVerbosity = getVerbosityLevel();
      const warnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});

      setVerbosityLevel(VerbosityLevel.WARNINGS);
      try {
        expect(bidi(`${HEBREW_ALEF}\u061d`)).toEqual({
          str: `\u061d${HEBREW_ALEF}`,
          dir: "rtl",
        });
        expect(warnSpy).toHaveBeenCalledTimes(1);
        expect(warnSpy).toHaveBeenCalledWith(
          "Warning: Bidi: invalid Unicode character 61d"
        );
      } finally {
        setVerbosityLevel(previousVerbosity);
      }
    });
  });
});
EOF
