/**
 * Encodes a number the way `BinaryCMapStream.readNumber` expects it:
 * big-endian groups of 7 bits, all but the last group flagged with 0x80.
 */
function num(value) {
  const out = [value % 128];
  let v = Math.floor(value / 128);
  while (v > 0) {
    out.unshift((v % 128) | 0x80);
    v = Math.floor(v / 128);
  }
  return out;
}

/**
 * Encodes a raw big-endian byte sequence of `size + 1` bytes, as read by
 * `BinaryCMapStream.readHex`.
 */
function hex(value, size) {
  const out = new Array(size + 1).fill(0);
  let v = value;
  for (let i = size; i >= 0 && v > 0; i--) {
    out[i] = v % 256;
    v = Math.floor(v / 256);
  }
  return out;
}

/** A 7-bit encoded string, as read by `BinaryCMapStream.readString`. */
function str(value) {
