/**
 * Encodes a number the way `BinaryCMapStream.readNumber` expects it: big-endian
 * groups of 7 bits, with all but the last group flagged with 0x80.
 */
function num(value) {
  const out = [value % 128];
  let v = Math.floor(value / 128);
  while (v > 0) {
    out.unshift((v % 128) | 0x80);
    v = Math.floor(v / 128);
  }
  return out;
}

/**
 * Encodes the raw big-endian byte sequence of `size + 1` bytes that
 * `BinaryCMapStream.readHex` consumes.
 */
function hex(value, size) {
  const out = new Array(size + 1).fill(0);
  let v = value;
  for (let i = size; i >= 0 && v > 0; i--) {
    out[i] = v % 256;
    v = Math.floor(v / 256);
  }
  return out;
}

/** Encodes the length-prefixed string that `BinaryCMapStream.readString` reads. */
function str(value) {
  return [
    ...num(value.length),
    ...Array.from(value, c => c.charCodeAt(0)).flatMap(c => num(c)),
  ];
}

function build(...parts) {
  return new Uint8Array(parts.flat());
}

/** Minimal CMap stub that records every call made by `process`. */
function createRecordingCMap() {
  return {
    vertical: null,
    calls: [],
    addCodespaceRange(bytes, low, high) {
      this.calls.push(["codespace", bytes, low, high]);
