const HEADER = [1, 0, 4, 1];

function u16(value) { return Uint8Array.from([(value >> 8) & 0xff, value & 0xff]); }

function operand(value) {
  const bytes = new Uint8Array(5);
  bytes[0] = 29;
  new DataView(bytes.buffer).setInt32(1, value);
  return bytes;
}

function concatBytes(...parts) {
  const total = parts.reduce((sum, p) => sum + p.length, 0);
  const out = new Uint8Array(total);
  let offset = 0;
  for (const p of parts) { out.set(p, offset); offset += p.length; }
  return out;
}

function buildIndex(objects) {
  const count = objects.length;
  if (count === 0) return Uint8Array.from([0, 0]);
  const dataLength = objects.reduce((s, o) => s + o.length, 0);
  const offsetSize = dataLength + 1 <= 0xff ? 1 : dataLength + 1 <= 0xffff ? 2 : 4;
  const header = [ (count >> 8) & 0xff, count & 0xff, offsetSize ];
  const offsets = [];
  let off = 1;
  for (const obj of objects) { offsets.push(off); off += obj.length; }
  offsets.push(off);
  const pieces = [Uint8Array.from(header)];
  for (const o of offsets) {
    const buf = new Uint8Array(offsetSize);
    let v = o;
    for (let i = offsetSize - 1; i >= 0; i--) { buf[i] = v & 0xff; v >>= 8; }
    pieces.push(buf);
  }
  return concatBytes(...pieces, ...objects);
}
```
