    : null;
  const fdArrayIndex = fdArrayEntries ? buildIndex(fdArrayEntries) : null;

  const makeTopDict = offsets => {
    const parts = [];
    if (fontBBox) {
      for (const value of fontBBox) {
        parts.push(operand(value));
      }
      parts.push(Uint8Array.from([5 /* FontBBox */]));
    }
    if (fontMatrix) {
      for (const value of fontMatrix) {
        parts.push(operand(value));
      }
      parts.push(Uint8Array.from([12, 7 /* FontMatrix */]));
    }
    parts.push(operand(offsets.charStrings), Uint8Array.from([17]));
    parts.push(operand(offsets.charset), Uint8Array.from([15]));
    if (!isCID) {
      parts.push(operand(offsets.encoding), Uint8Array.from([16]));
    }
    if (privateDictBytes) {
      parts.push(
        operand(privateDictBytes.length),
        operand(offsets.private),
        Uint8Array.from([18 /* Private */])
      );
    }
    if (isCID) {
      // ROS: registry SID, ordering SID, supplement.
      parts.push(
        operand(391),
        operand(392),
        operand(0),
        Uint8Array.from([12, 30 /* ROS */])
      );
      parts.push(operand(offsets.fdArray), Uint8Array.from([12, 36]));
      parts.push(operand(offsets.fdSelect), Uint8Array.from([12, 37]));
    }
    return concatBytes(...parts);
  };

  const placeholder = {
    charStrings: 0,
    charset: 0,
    encoding: 0,
    private: 0,
    fdArray: 0,
    fdSelect: 0,
  };
  const topDictSize = makeTopDict(placeholder).length;
  const topDictIndexSize = buildIndex([new Uint8Array(topDictSize)]).length;

  const nameOffset = headerBytes.length;
  const topDictOffset = nameOffset + nameIndex.length;
  const stringOffset = topDictOffset + topDictIndexSize;
  const globalSubrOffset = stringOffset + stringIndex.length;
  const charStringsOffset = globalSubrOffset + globalSubrIndex.length;
  const charsetOffset = charStringsOffset + charStringsIndex.length;

  let cursor = charsetOffset + charsetBytes.length;
  let encodingOffset = 0;
  let privateOffset = 0;
  let fdArrayOffset = 0;
  let fdSelectOffset = 0;

  if (!isCID) {
    encodingOffset = cursor;
    cursor += encodingBytes.length;
  }
  if (privateDictBytes) {
    privateOffset = cursor;
    cursor += privateDictBytes.length;
  }
  if (isCID) {
    fdArrayOffset = cursor;
    cursor += fdArrayIndex.length;
    fdSelectOffset = cursor;
    cursor += fdSelectBytes.length;
  }

  const topDict = makeTopDict({
    charStrings: charStringsOffset,
    charset: charsetOffset,
    encoding: encodingOffset,
    private: privateOffset,
    fdArray: fdArrayOffset,
    fdSelect: fdSelectOffset,
  });
  const topDictIndex = buildIndex([topDict]);
  if (topDictIndex.length !== topDictIndexSize) {
    throw new Error("Test helper: unstable top DICT size");
  }

  const parts = [
    headerBytes,
    nameIndex,
    topDictIndex,
    stringIndex,
    globalSubrIndex,
    charStringsIndex,
    charsetBytes,
  ];
  if (!isCID) {
    parts.push(encodingBytes);
  }
  if (privateDictBytes) {
    parts.push(privateDictBytes);
  }
  if (isCID) {
    parts.push(fdArrayIndex, fdSelectBytes);
  }
  const body = concatBytes(...parts);
  const bytes = prefix ? concatBytes(prefix, body) : body;

  return {
    bytes,
    charStringsOffset,
    charsetOffset,
    encodingOffset,
    privateOffset,
    file: { getBytes: () => bytes },
  };
}

function parse(bytesOrOptions, properties = {}, seacAnalysisEnabled = false) {
  const built =
    bytesOrOptions instanceof Uint8Array
      ? { bytes: bytesOrOptions, file: { getBytes: () => bytesOrOptions } }
      : buildCff(bytesOrOptions);
  const parser = new CFFParser(
    built.file,
    properties,
    seacAnalysisEnabled
  );
  const cff = parser.parse();
  return { parser, cff, properties, built };
}

let warnSpy;

beforeEach(() => {
  setVerbosityLevel(VerbosityLevel.WARNINGS);
  warnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});
});

afterEach(() => {
