describe("CFFParser.parse", () => {
  describe("basic (non-CID) fonts", () => {
    it("returns a CFF instance and assigns it to the parser", () => {
      const { parser, cff } = parse({});

      expect(cff).toBeInstanceOf(CFF);
      expect(parser.cff).toBe(cff);
    });

    it("parses the header", () => {
      const { cff, built } = parse({});

      expect(cff.header).toBeInstanceOf(CFFHeader);
      expect(cff.header).toEqual({
        major: 1,
        minor: 0,
        hdrSize: 4,
        offSize: 1,
      });
      expect(cff.rawFileLength).toBe(built.bytes.length);
    });

    it("parses the name, string and global subroutine indexes", () => {
      const { cff } = parse({
        names: ["TestFont"],
        strings: ["Foo", "Bar"],
      });

      expect(cff.names).toEqual(["TestFont"]);
      expect(cff.strings).toBeInstanceOf(CFFStrings);
      expect(cff.strings.count).toBe(2);
      expect(cff.strings.get(391)).toBe("Foo");
      expect(cff.strings.get(392)).toBe("Bar");
      expect(cff.globalSubrIndex).toBeInstanceOf(CFFIndex);
      expect(cff.globalSubrIndex.count).toBe(0);
    });

    it("parses the top DICT and exposes its offsets", () => {
      const { cff, built } = parse({});

      expect(cff.topDict).toBeInstanceOf(CFFTopDict);
      expect(cff.topDict.getByName("CharStrings")).toBe(
        built.charStringsOffset
      );
      expect(cff.topDict.getByName("charset")).toBe(built.charsetOffset);
      expect(cff.topDict.getByName("Encoding")).toBe(built.encodingOffset);
    });

    it("parses the charstring index and exposes count/charStrings/seacs/widths", () => {
      const { cff } = parse({
        charStrings: [Uint8Array.from([14]), Uint8Array.from([14])],
      });

      expect(cff.isCIDFont).toBe(false);
      expect(cff.charStringCount).toBe(2);
      expect(cff.charStrings).toBeInstanceOf(CFFIndex);
      expect(cff.charStrings.count).toBe(2);
      expect(cff.charStrings.get(0)).toEqual(Uint8Array.from([14]));
      expect(cff.seacs).toBeInstanceOf(Map);
      expect(cff.seacs.size).toBe(0);
      expect(cff.widths).toEqual([0, 0]);
    });

    it("resolves charset names through the string index", () => {
      const { cff } = parse({
        strings: ["Foo"],
        charStrings: [Uint8Array.from([14]), Uint8Array.from([14])],
        charsetSids: [391],
      });

      expect(cff.charset).toBeInstanceOf(CFFCharset);
      expect(cff.charset.predefined).toBe(false);
      expect(cff.charset.format).toBe(0);
      expect(cff.charset.charset).toEqual([".notdef", "Foo"]);
    });

    it("parses the encoding", () => {
      const { cff } = parse({
        encodingBytes: Uint8Array.from([0 /* format 0 */, 1, 0x41]),
      });

      expect(cff.encoding).toBeInstanceOf(CFFEncoding);
      expect(cff.encoding.predefined).toBe(false);
      expect(cff.encoding.format).toBe(0);
      expect(cff.encoding.encoding[0x41]).toBe(1);
      expect(cff.encoding.raw).toEqual(Uint8Array.from([0, 1, 0x41]));
    });

    it("parses the private DICT and uses defaultWidthX for widths", () => {
      const { cff, built } = parse({
        privateDictBytes: concatBytes(
          operand(500),
          Uint8Array.from([20 /* defaultWidthX */])
        ),
      });

      expect(cff.topDict.privateDict).toBeInstanceOf(CFFPrivateDict);
      expect(cff.topDict.privateDict.getByName("defaultWidthX")).toBe(500);
      expect(cff.topDict.getByName("Private")).toEqual([
        6,
        built.privateOffset,
      ]);
      expect(cff.widths).toEqual([500, 500]);
    });

    it("replaces an invalid charstring with a plain endchar", () => {
      const { cff } = parse({
        // 139 => number 0, 10 => callsubr, but there are no local subrs.
        charStrings: [Uint8Array.from([14]), Uint8Array.from([139, 10])],
      });

      expect(cff.charStrings.get(1)).toEqual(Uint8Array.from([14]));
      expect(warnSpy).toHaveBeenCalled();
    });

    it("does not touch the encoding for CID fonts (see separate suite)", () => {
      // Sanity check that a non-CID font always produces an encoding object.
      const { cff } = parse({});
      expect(cff.encoding).not.toBeNull();
    });
  });

  describe("properties updates", () => {
    it("copies the FontMatrix onto the properties", () => {
      const properties = { fontMatrix: [1, 2, 3, 4, 5, 6] };
      parse({ fontMatrix: [1, 0, 0, 1, 0, 0] }, properties);

      expect(properties.fontMatrix).toEqual([1, 0, 0, 1, 0, 0]);
    });

    it("uses the default FontMatrix when the top DICT does not define one", () => {
      const properties = {};
      parse({}, properties);

      expect(properties.fontMatrix).toEqual([0.001, 0, 0, 0.001, 0, 0]);
    });

    it("leaves ascent/descent untouched when there is no usable FontBBox", () => {
      const properties = { ascent: 111, descent: -222 };
      parse({ fontBBox: [0, 0, 0, 0] }, properties);

      expect(properties.ascent).toBe(111);
      expect(properties.descent).toBe(-222);
      expect(properties.ascentScaled).toBeUndefined();
    });
  });

  describe("FontBBox handling", () => {
    it("falls back to the (normalized) FontDescriptor bbox when the CFF one is empty", () => {
      const properties = { bbox: [500, 700, -10, -20] };
      const { cff } = parse({ fontBBox: [0, 0, 0, 0] }, properties);

      expect(cff.topDict.getByName("FontBBox")).toEqual([
        -10, -20, 500, 700,
      ]);
      expect(properties.ascent).toBe(700);
      expect(properties.descent).toBe(-20);
      expect(properties.ascentScaled).toBe(true);
    });

    it("recovers unsigned 16-bit lower-left coordinates (Ghostscript quirk)", () => {
      const properties = {};
      const { cff } = parse(
        { fontBBox: [65526, 65516, 1000, 2000] },
        properties
      );

      expect(cff.topDict.getByName("FontBBox")).toEqual([
        -10, -20, 1000, 2000,
      ]);
      expect(properties.ascent).toBe(2000);
      expect(properties.descent).toBe(-20);
      expect(properties.ascentScaled).toBe(true);
    });

    it("repairs every unsigned coordinate when the descriptor corroborates it", () => {
      const properties = { bbox: [-10, -20, -10, 5000] };
      const { cff } = parse(
        { fontBBox: [65526, 65516, 65526, 5000] },
        properties
      );

      expect(cff.topDict.getByName("FontBBox")).toEqual([
        -10, -20, -10, 5000,
      ]);
      expect(properties.ascent).toBe(5000);
      expect(properties.descent).toBe(-20);
    });

    it("preserves large unsigned upper-right coordinates without corroboration", () => {
      const properties = { bbox: [0, 0, 10, 10] };
      const { cff } = parse(
        { fontBBox: [0, 0, 65526, 1000] },
        properties
      );

      // Untouched in the top DICT, i.e. no repair was applied.
      expect(cff.topDict.getByName("FontBBox")).toEqual([
        0, 0, 65526, 1000,
      ]);
      expect(properties.ascent).toBe(1000);
      expect(properties.descent).toBe(0);
      expect(properties.ascentScaled).toBe(true);
    });

    it("preserves unsigned upper-right coordinates when there is no descriptor bbox", () => {
      const properties = {};
      const { cff } = parse(
        { fontBBox: [0, 0, 65526, 1000] },
        properties
      );

      expect(cff.topDict.getByName("FontBBox")).toEqual([
        0, 0, 65526, 1000,
      ]);
      expect(properties.ascent).toBe(1000);
      expect(properties.descent).toBe(0);
    });
  });

  describe("CID fonts", () => {
    it("populates fdArray/fdSelect, uses a CID charset and skips the encoding", () => {
      const { cff } = parse({
        isCID: true,
        charStrings: [Uint8Array.from([14]), Uint8Array.from([14])],
        fdArrayEntries: [new Uint8Array(0), new Uint8Array(0)],
        fdSelectCodes: [0, 1],
      });

      expect(cff.isCIDFont).toBe(true);
      expect(cff.encoding).toBeNull();
      expect(cff.charset.charset).toEqual([0, 1]);
      expect(cff.fdArray).toHaveLength(2);
      for (const fontDict of cff.fdArray) {
        expect(fontDict).toBeInstanceOf(CFFTopDict);
        expect(fontDict.privateDict).toBeInstanceOf(CFFPrivateDict);
      }
      expect(cff.fdSelect).toBeInstanceOf(CFFFDSelect);
      expect(cff.fdSelect.format).toBe(0);
      expect(cff.fdSelect.fdSelect).toEqual([0, 1]);
      expect(cff.charStrings.count).toBe(2);
    });

    it("clamps the FDArray count to the maximum addressable amount", () => {
      const entries = Array.from({ length: 300 }, () => new Uint8Array(0));
      const { cff } = parse({
        isCID: true,
        fdArrayEntries: entries,
        fdSelectCodes: [0, 0],
      });

      expect(cff.fdArray).toHaveLength(256);
      expect(warnSpy).toHaveBeenCalledWith(
        expect.stringContaining("too many FDArray entries (300)")
      );
    });
  });

  describe("shifted and invalid data", () => {
    it("skips leading garbage before the CFF header", () => {
      const prefix = Uint8Array.from([0xff, 0x00, 0x42]);
      const { cff, built } = parse({ prefix });

      expect(cff.header.major).toBe(1);
      expect(cff.names).toEqual(["TestFont"]);
      expect(cff.charStringCount).toBe(2);
      // rawFileLength is captured before the data is shifted.
      expect(cff.rawFileLength).toBe(built.bytes.length);
      expect(built.bytes.length).toBe(prefix.length + cff.rawFileLength - prefix.length);
    });

    it("throws a FormatError when the header is missing", () => {
      expect(() => parse(Uint8Array.from([0, 0, 0, 0]))).toThrow(FormatError);
      expect(() => parse(Uint8Array.from([0, 0, 0, 0]))).toThrow(
        "Invalid CFF header"
      );
    });

    it("throws a FormatError for empty data", () => {
      expect(() => parse(new Uint8Array(0))).toThrow("Invalid CFF header");
    });

    it("throws a FormatError when an INDEX has an invalid offset size", () => {
      // header + INDEX header with count=1 and offset size 0.
      const bytes = Uint8Array.from([1, 0, 4, 1, 0, 1, 0]);

      expect(() => parse(bytes)).toThrow(FormatError);
      expect(() => parse(bytes)).toThrow(
        "Invalid CFF INDEX offset size: 0"
      );
    });
  });
});
