describe("CFFParser.parse", () => {
  describe("basic (non-CID) fonts", () => {
    it("returns a CFF instance and assigns it to the parser", () => {
      const { parser, cff } = parse({});

      expect(cff).toBeInstanceOf(CFF);
      expect(parser.cff).toBe(cff);
    });

    it("parses the header", () => {
      const { cff, built } = parse({});

      expect(cff.header).toBeInstanceOf(CFFHeader);
      expect(cff.header).toEqual({
        major: 1,
        minor: 0,
        hdrSize: 4,
        offSize: 1,
      });
      expect(cff.rawFileLength).toBe(built.bytes.length);
    });

    it("parses the name, string and global subroutine indexes", () => {
      const { cff } = parse({
        names: ["TestFont"],
        strings: ["Foo", "Bar"],
      });

      expect(cff.names).toEqual(["TestFont"]);
      expect(cff.strings).toBeInstanceOf(CFFStrings);
      expect(cff.strings.count).toBe(2);
      expect(cff.strings.get(391)).toBe("Foo");
      expect(cff.strings.get(392)).toBe("Bar");
      expect(cff.globalSubrIndex).toBeInstanceOf(CFFIndex);
      expect(cff.globalSubrIndex.count).toBe(0);
    });

    it("parses the top DICT and exposes its offsets", () => {
      const { cff, built } = parse({});

      expect(cff.topDict).toBeInstanceOf(CFFTopDict);
      expect(cff.topDict.getByName("CharStrings")).toBe(
        built.charStringsOffset
      );
      expect(cff.topDict.getByName("charset")).toBe(built.charsetOffset);
      expect(cff.topDict.getByName("Encoding")).toBe(built.encodingOffset);
    });

    it("parses the charstring index and exposes count/charStrings/seacs/widths", () => {
      const { cff } = parse({
        charStrings: [Uint8Array.from([14]), Uint8Array.from([14])],
      });

      expect(cff.isCIDFont).toBe(false);
      expect(cff.charStringCount).toBe(2);
      expect(cff.charStrings).toBeInstanceOf(CFFIndex);
      expect(cff.charStrings.count).toBe(2);
      expect(cff.charStrings.get(0)).toEqual(Uint8Array.from([14]));
      expect(cff.seacs).toBeInstanceOf(Map);
      expect(cff.seacs.size).toBe(0);
      expect(cff.widths).toEqual([0, 0]);
    });

    it("resolves charset names through the string index", () => {
      const { cff } = parse({
        strings: ["Foo"],
        charStrings: [Uint8Array.from([14]), Uint8Array.from([14])],
        charsetSids: [391],
      });

      expect(cff.charset).toBeInstanceOf(CFFCharset);
      expect(cff.charset.predefined).toBe(false);
      expect(cff.charset.format).toBe(0);
      expect(cff.charset.charset).toEqual([".notdef", "Foo"]);
    });

    it("parses the encoding", () => {
      const { cff } = parse({
        encodingBytes: Uint8Array.from([0 /* format 0 */, 1, 0x41]),
      });

      expect(cff.encoding).toBeDefined();
      expect(cff.encoding.predefined).toBe(false);
      expect(cff.encoding.format).toBe(0);
      expect(cff.encoding.encoding[0x41]).toBe(1);
      expect(cff.encoding.raw).toEqual(Uint8Array.from([0, 1, 0x41]));
    });

    it("parses the private DICT and uses defaultWidthX for widths", () => {
      const { cff, built } = parse({
        privateDictBytes: concatBytes(
