import { CFFParser } from "../../../src/core/cff_parser.js";

const MAX_SUBR_NESTING = 10;

function createParser(seacAnalysisEnabled = false) {
  return new CFFParser(
    { getBytes: () => new Uint8Array(0) },
    {},
    seacAnalysisEnabled
  );
}

function createState(overrides = {}) {
  return {
    stack: [],
    stackSize: 0,
    callDepth: 0,
    hints: 0,
    firstStackClearing: false,
    width: 0,
    hasVStems: false,
    seac: null,
    ...overrides,
  };
}

function createSubrIndex(count, getter) {
  const calls = [];
  return {
    count,
    calls,
    get(index) {
      calls.push(index);
      return getter(index);
    },
  };
}

function stackValues(state) {
  return state.stack.slice(0, state.stackSize);
}

function hasWarning(warnings, text) {
  return warnings.some(message => message.includes(text));
}

describe("CFFParser.parseCharString", () => {
  let originalWarn;
  let warnings;

