import { PDFDocument } from './src/core/document.js';
import { Dict, Name, Ref } from './src/core/primitives.js';
import { Stream } from './src/core/stream.js';
const toJSObject = PDFDocument.prototype.toJSObject;
const xref = {
  trailer: null,
  fetch(ref) { return this.map?.get(ref.toString()); },
  fetchIfRef(v) { return v instanceof Ref ? this.fetch(v) : v; },
  map: new Map(),
};
const ctx = { xref, catalog: {}, toJSObject };
const show = async (label, value, firstCall) => {
  try { console.log(label, await toJSObject.call(ctx, value, firstCall)); }
  catch(e) { console.log(label, 'ERR', e.name, e.message); }
};
await show('num', 42);
await show('str', 'abc');
await show('bool', false);
await show('undef', undefined);
await show('null false', null, false);
await show('name', Name.get('Foo'));
const d = new Dict(); d.set('A', 1); d.set('B', [true, null, new Ref('3R0', 3, 0)]); d.set('N', new Dict());
await show('dict', d);
const page = new Dict(); page.set('Type', Name.get('Page')); page.set('Contents', new Stream(new Uint8Array([49,32,50,32,97,100,100]), 0, 7, null));
xref.fetchIfRef = v => v;
await show('page direct stream', page);
// Ref firstcall
const ref = new Ref('5R0',5,0); xref.map.set('5R0', d);
xref.fetch = r => xref.map.get(r.toString());
await show('ref first', ref);
await show('ref false', ref, false);
// regular stream dict
const sd = new Dict(); sd.set('Subtype', Name.get('Other')); sd.set('Length', 3);
const s = new Stream(new Uint8Array([97,98,99]),0,3,sd);
await show('regular stream', s);
// form
const fd = new Dict(); fd.set('Subtype', Name.get('Form')); fd.set('Length', 7);
const fs = new Stream(new Uint8Array([49,32,50,32,97,100,100]),0,7,fd);
await show('form', fs);
// ps
const pd = new Dict(); pd.set('FunctionType', 4); pd.set('Domain', [0,1]); pd.set('Range', [0,10]); pd.set('Length', 7);
const ps = new Stream(new Uint8Array([50,32,109,117,108,32,0].slice(0,7)),0,7,pd);
// string '2 mul' is 5 bytes
const ps2 = new Stream(new Uint8Array([50,32,109,117,108]),0,5,pd);
await show('ps', ps2);
// image fallback mask
const id = new Dict(); id.set('Subtype', Name.get('Image')); id.set('ImageMask', true); id.set('Length', 3);
const im = new Stream(new Uint8Array([1,2,3]),0,3,id);
await show('image fallback', im);
console.log('mask state', id.get('ImageMask'), id.get('IM'), im.numComps, im.bitsPerComponent, im.pos);
EOF"}

