  } else if (mask) {
    if (mask instanceof BaseStream || Array.isArray(mask)) {
      maskData = mask;
    } else {
      warn("Unsupported /Mask format.");
    }
  }

  return new PDFImage({
    xref,
    res,
    image: imageData,
    isInline,
    smask: smaskData,
    mask: maskData,
    pdfFunctionFactory,
    globalColorSpaceCache,
    localColorSpaceCache,
  });
}

