import { describe, expect, it, jest } from "@jest/globals";

import { PDFDocument } from "../../../src/core/document.js";
import { LocalColorSpaceCache } from "../../../src/core/image_utils.js";
import { Dict, Name, Ref } from "../../../src/core/primitives.js";
import { Stream } from "../../../src/core/stream.js";
import { ImageKind } from "../../../src/shared/util.js";

const toJSObject = PDFDocument.prototype.toJSObject;
const encoder = new TextEncoder();

function makeXref({ trailer = null, entries = [] } = {}) {
  const objects = new Map(entries);
  const xref = {
    trailer,
    objects,
    fetch: jest.fn(ref => {
      if (!objects.has(ref.toString())) {
        throw new Error(`Missing object: ${ref}`);
      }
      return objects.get(ref.toString());
    }),
    fetchIfRef(value) {
      return value instanceof Ref ? xref.fetch(value) : value;
    },
  };
  return xref;
}

function makeContext(xref = makeXref()) {
  return {
    xref,
    catalog: { globalColorSpaceCache: new LocalColorSpaceCache() },
    toJSObject,
  };
}

function makeStream(text, dict = new Dict()) {
  const bytes = encoder.encode(text);
  if (!dict.has("Length")) {
    dict.set("Length", bytes.length);
  }
  return new Stream(bytes, 0, bytes.length, dict);
}

function convert(context, value, firstCall) {
  return firstCall === undefined
    ? toJSObject.call(context, value)
    : toJSObject.call(context, value, firstCall);
}

const CONTENT = "q 1 0 0 1 10 20 cm Q";

describe("PDFDocument.toJSObject", () => {
  it("returns primitive values and Names unchanged", async () => {
    const context = makeContext();
    const name = Name.get("SomeName");

    for (const value of [0, -3, 2.5, "text", "", true, false, undefined, name]) {
      await expect(convert(context, value)).resolves.toBe(value);
    }
    await expect(convert(context, null, false)).resolves.toBeNull();
  });

  it("dereferences a null first argument to the trailer", async () => {
    const trailer = new Dict();
    trailer.set("Size", 5);
    trailer.set("Info", null);
    const xref = makeXref({ trailer });
    const context = makeContext(xref);

    const result = await convert(context, null);

    expect(result).toEqual({ Size: 5, Info: null });
    expect(Object.getPrototypeOf(result)).toBe(null);
    expect(xref.fetch).not.toHaveBeenCalled();
  });

  it("recursively converts dictionaries, arrays, and nested references", async () => {
    const nested = new Dict();
    nested.set("Leaf", 7);

    const dict = new Dict();
    dict.set("Title", "hello");
    dict.set("Nested", nested);
    dict.set("Items", [true, null, new Ref("9R0", 9, 0)]);
    const xref = makeXref();
    const context = makeContext(xref);

    const result = await convert(context, dict);

    expect(Object.getPrototypeOf(result)).toBe(null);
    expect(Object.getPrototypeOf(result.Nested)).toBe(null);
    expect(Object.getPrototypeOf(result.Items[2])).toBe(null);
    expect(result).toEqual({
      Title: "hello",
      Nested: { Leaf: 7 },
      Items: [true, null, { num: 9, gen: 0 }],
    });
    expect(xref.fetch).not.toHaveBeenCalled();
  });

  it("converts direct arrays element by element", async () => {
    const nested = new Dict();
    nested.set("Value", "inside");

    const result = await convert(makeContext(), [
      1,
      "two",
      nested,
      new Ref("4R2", 4, 2),
    ]);

    expect(Array.isArray(result)).toBe(true);
    expect(result).toEqual([1, "two", { Value: "inside" }, { num: 4, gen: 2 }]);
    expect(Object.getPrototypeOf(result[2])).toBe(null);
    expect(Object.getPrototypeOf(result[3])).toBe(null);
  });

  it("fetches a top-level Ref but serializes nested Refs by number and generation", async () => {
    const target = new Dict();
    target.set("Type", Name.get("Fetched"));
    const ref = new Ref("12R3", 12, 3);
    const xref = makeXref({ entries: [[ref, target]] });
    const context = makeContext(xref);

    const fetched = await convert(context, ref);

    expect(fetched).toEqual({ Type: Name.get("Fetched") });
    expect(xref.fetch).toHaveBeenCalledTimes(1);
    expect(xref.fetch).toHaveBeenCalledWith(ref);

    const serialized = await convert(context, ref, false);
    expect(serialized).toEqual({ num: 12, gen: 3 });
    expect(Object.getPrototypeOf(serialized)).toBe(null);
    expect(xref.fetch).toHaveBeenCalledTimes(1);
  });

  it("uses content-token conversion for a Page's Contents", async () => {
    const contentsRef = new Ref("7R0", 7, 0);
    const contentStream = makeStream(CONTENT);
    const xref = makeXref({ entries: [[contentsRef, contentStream]] });
    const page = new Dict();
    page.set("Type", Name.get("Page"));
    page.set("Contents", contentsRef);

    const result = await convert(makeContext(xref), page);

    expect(result.Contents.contentStream).toBe(true);
    expect(result.Contents.rawContents).toEqual([{ num: 7, gen: 0 }]);
    expect(result.Contents.rawBytes).toBe(CONTENT);
    expect(result.Contents.instructions.map(({ cmd }) => cmd)).toEqual([
      "q",
      "cm",
      "Q",
    ]);
    expect(result.Contents.instructions[1].args).toEqual([
      { type: "number", value: 1 },
      { type: "number", value: 0 },
      { type: "number", value: 0 },
      { type: "number", value: 1 },
      { type: "number", value: 10 },
      { type: "number", value: 20 },
    ]);
    expect(result.Contents.cmdNames).toEqual({
      q: "save",
      cm: "transform",
      Q: "restore",
    });
    expect(result.Contents.bytes).toBeUndefined();
    expect(result.Contents.dict).toBeUndefined();
  });

  it("does not special-case Contents on a non-Page dictionary", async () => {
    const contentStream = makeStream(CONTENT);
    const dict = new Dict();
    dict.set("Type", Name.get("NotPage"));
    dict.set("Contents", contentStream);

    const result = await convert(makeContext(), dict);

    expect(result.Contents).toEqual({
      dict: { Length: CONTENT.length },
      bytes: CONTENT,
    });
    expect(result.Contents.contentStream).toBeUndefined();
    expect(result.Contents.rawContents).toBeUndefined();
  });

  it("returns a byte representation for an ordinary stream", async () => {
    const streamDict = new Dict();
    streamDict.set("Subtype", Name.get("Other"));
    const stream = makeStream("ABC", streamDict);

    const result = await convert(makeContext(), stream);

    expect(result).toEqual({
      dict: { Subtype: Name.get("Other"), Length: 3 },
      bytes: "ABC",
    });
    expect(Object.getPrototypeOf(result)).toBe(null);
    expect(result.contentStream).toBeUndefined();
    expect(result.imageData).toBeUndefined();
  });

  it("decodes a Form stream into instructions and command names", async () => {
    const streamDict = new Dict();
    streamDict.set("Subtype", Name.get("Form"));
    const stream = makeStream(CONTENT, streamDict);

    const result = await convert(makeContext(), stream);

    expect(result.bytes).toBe(CONTENT);
    expect(result.contentStream).toBe(true);
    expect(result.dict.Subtype).toEqual(Name.get("Form"));
    expect(result.instructions.map(({ cmd }) => cmd)).toEqual([
      "q",
      "cm",
      "Q",
    ]);
    expect(result.cmdNames).toEqual({
      q: "save",
      cm: "transform",
      Q: "restore",
    });
  });

  it("converts a PostScript calculator function into executable JS", async () => {
    const source = "{ 2 mul }";
    const streamDict = new Dict();
    streamDict.set("FunctionType", 4);
    streamDict.set("Domain", [0, 1]);
    streamDict.set("Range", [0, 10]);
    const stream = makeStream(source, streamDict);

    const result = await convert(makeContext(), stream);

    expect(result.psFunction).toBe(true);
    expect(result.source).toBe(source);
    expect(result.dict.FunctionType).toBe(4);
    expect(result.psLines).toEqual([
      { indent: 0, tokens: [{ type: "brace", value: "{" }] },
      {
        indent: 1,
        tokens: [
          { type: "number", value: 2 },
          { type: "cmd", value: "mul" },
        ],
      },
      { indent: 0, tokens: [{ type: "brace", value: "}" }] },
    ]);

    const fn = new Function(`return ${result.jsCode};`)();
    const outputs = [];
    fn([-1], 0, outputs, 0);
    fn([2], 0, outputs, 1);
    fn([6], 0, outputs, 2);
    expect(outputs).toEqual([0, 4, 10]);
  });

  it("decodes an Image stream into imageData", async () => {
    const imageDict = new Dict();
    imageDict.set("Subtype", Name.get("Image"));
    imageDict.set("Width", 1);
    imageDict.set("Height", 1);
    imageDict.set("BitsPerComponent", 8);
    imageDict.set("ColorSpace", Name.get("DeviceRGB"));
    imageDict.set("Length", 3);
    const image = new Stream(new Uint8Array([255, 0, 0]), 0, 3, imageDict);

    const result = await convert(makeContext(), image);

    expect(result.dict.Subtype).toEqual(Name.get("Image"));
    expect(result.imageData.width).toBe(1);
    expect(result.imageData.height).toBe(1);
    expect(result.imageData.kind).toBe(ImageKind.RGBA_32BPP);
    expect(Array.from(result.imageData.data)).toEqual([255, 0, 0, 255]);
    expect(result.bytes).toBeUndefined();
  });

  it("decodes an ImageMask stream and updates its temporary mask state", async () => {
    const imageDict = new Dict();
    imageDict.set("Subtype", Name.get("Image"));
    imageDict.set("ImageMask", true);
    imageDict.set("Width", 1);
    imageDict.set("Height", 1);
    imageDict.set("Length", 1);
    const image = new Stream(new Uint8Array([128]), 0, 1, imageDict);

    const result = await convert(makeContext(), image);

    expect(result.imageData.width).toBe(1);
    expect(result.imageData.height).toBe(1);
    expect(result.imageData.kind).toBe(ImageKind.RGBA_32BPP);
    expect(imageDict.get("ImageMask")).toBe(false);
    expect(imageDict.get("IM")).toBe(false);
    expect(image.numComps).toBe(1);
    expect(image.bitsPerComponent).toBe(1);
    expect(result.bytes).toBeUndefined();
  });

  it("falls back to bytes and restores mask state when image decoding fails", async () => {
    const imageDict = new Dict();
    imageDict.set("Subtype", Name.get("Image"));
    imageDict.set("ImageMask", true);
    imageDict.set("Width", 0);
    imageDict.set("Height", 1);
    imageDict.set("Length", 3);
    const image = new Stream(new Uint8Array([1, 2, 3]), 0, 3, imageDict);

    const result = await convert(makeContext(), image);

    expect(result.imageData).toBeUndefined();
    expect(result.bytes).toBe("\x01\x02\x03");
    expect(imageDict.get("ImageMask")).toBe(true);
    expect(imageDict.get("IM")).toBe(false);
    expect(image.numComps).toBeUndefined();
    expect(image.bitsPerComponent).toBeUndefined();
  });

  it("throws when PDFJSDev excludes the internal-viewer implementation", async () => {
    const previous = Object.getOwnPropertyDescriptor(globalThis, "PDFJSDev");
    Object.defineProperty(globalThis, "PDFJSDev", {
      configurable: true,
      value: { test: () => false },
    });
    try {
      await expect(convert(makeContext(), 1)).rejects.toThrow(
        "Not implemented: toJSObject"
      );
    } finally {
      if (previous) {
        Object.defineProperty(globalThis, "PDFJSDev", previous);
      } else {
        delete globalThis.PDFJSDev;
      }
    }
  });
});
