  };
  const globalImageCache = makeGlobalImageCache();

  const evaluator = new PartialEvaluator({
    xref: { fake: "xref" },
    handler,
    pageIndex,
    pageProxyId,
    idFactory,
    fontCache: new Map(),
    builtInCMapCache: new Map(),
    standardFontDataCache: new Map(),
    globalColorSpaceCache: { fake: "globalColorSpaceCache" },
    globalImageCache,
    systemFontCache: new Map(),
    options: {
      maxImageSize: -1,
      ignoreErrors: false,
      isOffscreenCanvasSupported: false,
      ...options,
    },
  });

  return { evaluator, handler, idFactory, globalImageCache };
}

function makeImageData(overrides = {}) {
  return {
    data: new Uint8Array([1, 2, 3, 4]),
    width: 2,
    height: 2,
    interpolate: false,
    ...overrides,
  };
}

async function flushAsync() {
  await new Promise(resolve => setTimeout(resolve, 0));
}

