      expect(MockPDFImage.buildImage).toHaveBeenCalledTimes(1);
    });

    it("records a failed decode and sends a null image", async () => {
      const warnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});
      const { evaluator, globalImageCache, handler } = makeEvaluator();
      const operatorList = makeOperatorList();
      MockPDFImage.buildImage.mockRejectedValue(new Error("decode error"));

      await evaluator.buildPaintImageXObject({
