      expect(localImageCache.getByName("img-key")).toEqual({
        objId: "img_41",
        fn: OPS.paintImageXObject,
        args: ["img_41", 12, 34],
        optionalContent: undefined,
        hasMask: false,
      });
    });

    it("does not populate any cache when no cache key is provided", async () => {
      const { evaluator, globalImageCache } = makeEvaluator();
      const operatorList = makeOperatorList();
      const localImageCache = new LocalImageCache();
      const imageRef = Ref.get(13, 0);
      const image = makeImage({ width: 12, height: 34, objId: imageRef });
      MockPDFImage.buildImage.mockReturnValue(new Promise(() => {}));

