        resources: new Dict(),
        image,
        operatorList,
        localImageCache,
      });

      expect(globalImageCache.shouldCache).not.toHaveBeenCalled();
      expect(localImageCache.getByRef(imageRef)).toBeNull();
      expect(evaluator._regionalImageCache.getByRef(imageRef)).toBeNull();
    });
  });
});
