function makeImage({
  width = 10,
  height = 10,
  imageMask = false,
  hasSMask = false,
  hasMask = false,
  objId = null,
  oc,
} = {}) {
  const dict = new Dict();

  if (width !== undefined) {
    dict.set("Width", width);
  }
  if (height !== undefined) {
    dict.set("Height", height);
  }
  if (imageMask) {
    dict.set("IM", true);
  }
  if (hasSMask) {
    dict.set("SMask", {});
  }
  if (hasMask) {
    dict.set("Mask", []);
  }
  if (oc !== undefined) {
    dict.set("OC", oc);
  }
  dict.objId = objId;

  return { dict };
}

function makeOperatorList() {
  return {
    addDependency: jest.fn(),
    addImageOps: jest.fn(),
  };
}

function makeGlobalImageCache() {
  return {
    addByteSize: jest.fn(),
    addDecodeFailed: jest.fn(),
    hasDecodeFailed: jest.fn(() => false),
    setData: jest.fn(),
    setDecodedImage: jest.fn(),
    shouldCache: jest.fn(() => false),
    startDecodedImage: jest.fn(),
    takeDecodedImage: jest.fn(() => null),
  };
}

function makeEvaluator({
  options = {},
  pageIndex = 0,
  pageProxyId = "page-1",
} = {}) {
  const handler = {
    send: jest.fn(),
    sendWithPromise: jest.fn().mockResolvedValue(0),
  };
  const idFactory = {
    createObjId: jest.fn(() => 41),
    getDocId: jest.fn(() => "doc"),
  };
  const globalImageCache = makeGlobalImageCache();

  const evaluator = new PartialEvaluator({
    xref: { fake: "xref" },
    handler,
    pageIndex,
    pageProxyId,
    idFactory,
    fontCache: new Map(),
    builtInCMapCache: new Map(),
    standardFontDataCache: new Map(),
    globalColorSpaceCache: { fake: "globalColorSpaceCache" },
    globalImageCache,
    systemFontCache: new Map(),
    options: {
      maxImageSize: -1,
      ignoreErrors: false,
      isOffscreenCanvasSupported: false,
      ...options,
    },
  });

  return { evaluator, handler, idFactory, globalImageCache };
}

function makeImageData(overrides = {}) {
  return {
    data: new Uint8Array([1, 2, 3, 4]),
    width: 2,
    height: 2,
    interpolate: false,
    ...overrides,
  };
}

async function flushAsync() {
  await new Promise(resolve => setTimeout(resolve, 0));
}

describe("PartialEvaluator.buildPaintImageXObject", () => {
  describe("image dimensions", () => {
    it.each([
