      expect(operatorList.addImageOps).not.toHaveBeenCalled();
    });

    it("throws when the image exceeds maxImageSize and errors are not ignored", async () => {
      const { evaluator } = makeEvaluator({
        options: { maxImageSize: 100 },
      });
      const operatorList = makeOperatorList();

      await expect(
