          resources: new Dict(),
          image: makeImage({ width: 11, height: 10 }),
          operatorList,
        })
      ).rejects.toThrow(
        "Image exceeded maximum allowed size and was removed."
      );

      expect(MockPDFImage.buildImage).not.toHaveBeenCalled();
      expect(operatorList.addImageOps).not.toHaveBeenCalled();
    });

    it("warns and returns when the image exceeds maxImageSize and errors are ignored", async () => {
      const warnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});
      const { evaluator } = makeEvaluator({
        options: { maxImageSize: 100, ignoreErrors: true },
      });
      const operatorList = makeOperatorList();

      await evaluator.buildPaintImageXObject({
        resources: new Dict(),
        image: makeImage({ width: 11, height: 10 }),
        operatorList,
      });

      expect(warnSpy).toHaveBeenCalledWith(
        "Warning: Image exceeded maximum allowed size and was removed."
      );
      expect(MockPDFImage.buildImage).not.toHaveBeenCalled();
      expect(operatorList.addImageOps).not.toHaveBeenCalled();
    });

    it("allows an image whose area is exactly maxImageSize", async () => {
      const { evaluator, idFactory } = makeEvaluator({
        options: { maxImageSize: 100 },
      });
