import { Dict, Name, Ref } from "../../../src/core/primitives.js";
import {
  LocalColorSpaceCache,
  LocalGStateCache,
} from "../../../src/core/image_utils.js";
import {
  OPS,
  setVerbosityLevel,
  VerbosityLevel,
} from "../../../src/shared/util.js";
import { OperatorList } from "../../../src/core/operator_list.js";
import { PartialEvaluator } from "../../../src/core/evaluator.js";

const CACHE_KEY = "gState_0";

function makeGState(entries = [], { ref = null } = {}) {
  const dict = new Dict(null);
  for (const [key, value] of entries) {
    dict.set(key, value);
  }
  if (ref) {
    dict.objId = ref;
  }
  return dict;
}

/**
 * Minimal call-recording stub, so that the tests do not depend on the
 * (ESM-incompatible) `jest` global object.
 */
function createSpy(impl = null) {
  const calls = [];
  const spy = (...args) => {
    calls.push(args);
    return impl ? impl(...args) : undefined;
  };
  spy.calls = calls;
  return spy;
}

function createDeferred() {
  let resolve, reject;
  const promise = new Promise((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

function flushTasks() {
  return new Promise(resolve => {
    setTimeout(resolve, 0);
  });
}

/**
 * Collects the converted graphic state entries of every `OPS.setGState`
 * operation which has been appended to the given `OperatorList`.
 */
function setGStateOps(operatorList) {
  const ops = [];
  operatorList.fnArray.forEach((fn, index) => {
    if (fn === OPS.setGState) {
      ops.push(operatorList.argsArray[index][0]);
    }
  });
  return ops;
}

function createContext() {
  const evaluator = new PartialEvaluator({ xref: null, pageIndex: 0 });
  const operatorList = new OperatorList();
  const localGStateCache = new LocalGStateCache();
  const localColorSpaceCache = new LocalColorSpaceCache();
  const resources = new Dict(null);
  const task = { name: "fake-task" };
  const stateManager = { state: { font: "initial", kind: "gstate-state" } };
  const seenRefs = new Set();

  const handleSetFont = createSpy(async () => "g_font_1");
  evaluator.handleSetFont = handleSetFont;

  const handleSMask = createSpy(async () => {});
  evaluator.handleSMask = handleSMask;

  const context = {
    evaluator,
    handleSetFont,
    handleSMask,
    localColorSpaceCache,
    localGStateCache,
    operatorList,
    resources,
    seenRefs,
    stateManager,
    task,
  };

  context.run = (gState, overrides = {}) =>
    evaluator.setGState({
      resources: overrides.resources ?? resources,
      gState,
      operatorList: overrides.operatorList ?? operatorList,
      cacheKey: overrides.cacheKey ?? CACHE_KEY,
      task: overrides.task ?? task,
      stateManager: overrides.stateManager ?? stateManager,
      localGStateCache: overrides.localGStateCache ?? localGStateCache,
      localColorSpaceCache:
        overrides.localColorSpaceCache ?? localColorSpaceCache,
      seenRefs: overrides.seenRefs ?? seenRefs,
    });

  return context;
}

