describe("blend modes", () => {
  it.each([
    ["Normal", "source-over"],
    ["Compatible", "source-over"],
    ["Multiply", "multiply"],
    ["Screen", "screen"],
    ["ColorDodge", "color-dodge"],
    ["Luminosity", "luminosity"],
  ])("normalizes the %s blend mode to %s", async (name, expected) => {
    const context = createContext();

    await context.run(makeGState([["BM", Name.get(name)]]));

    expect(setGStateOps(context.operatorList)).toEqual([[["BM", expected]]]);
  });

  it("falls back to source-over for an unsupported blend mode name", async () => {
    const context = createContext();

    await context.run(makeGState([["BM", Name.get("UnknownMode")]]));

    expect(setGStateOps(context.operatorList)).toEqual([
      [["BM", "source-over"]],
    ]);
    expect(warnSpy.calls).toEqual([
      ["Warning: Unsupported blend mode: UnknownMode"],
    ]);
  });

  it("uses the first supported blend mode of an array", async () => {
    const context = createContext();

    await context.run(
      makeGState([["BM", [Name.get("UnknownMode"), Name.get("Multiply")]]])
    );

    expect(setGStateOps(context.operatorList)).toEqual([
      [["BM", "multiply"]],
    ]);
  });

  it("falls back to source-over for an array without supported modes", async () => {
    const context = createContext();

    await context.run(
      makeGState([["BM", [Name.get("UnknownMode"), Name.get("Bogus")]]])
    );

    expect(setGStateOps(context.operatorList)).toEqual([
      [["BM", "source-over"]],
    ]);
    const warnings = warnSpy.calls.map(([msg]) => msg);
    expect(
      warnings.some(msg => msg.includes("Unsupported blend mode Array"))
    ).toBe(true);
  });
});

describe("soft masks", () => {
  it("converts a /None soft mask to false and caches the state", async () => {
    const context = createContext();

    await context.run(makeGState([["SMask", Name.get("None")]]));

    expect(setGStateOps(context.operatorList)).toEqual([[["SMask", false]]]);
    expect(context.handleSMask.calls).toEqual([]);
    expect(context.localGStateCache.getByName(CACHE_KEY)).toEqual([
      ["SMask", false],
    ]);
  });

  it("handles a soft mask dictionary asynchronously without caching", async () => {
    const context = createContext();
    const smask = makeGState([["G", Name.get("DeviceGray")]]);

    await context.run(makeGState([["SMask", smask]]));

    expect(context.handleSMask.calls).toEqual([
      [
        smask,
        context.resources,

        context.resources,
        context.operatorList,
        context.task,
        context.stateManager,
        context.localColorSpaceCache,
        context.seenRefs,
      ],
    ]);
    expect(setGStateOps(context.operatorList)).toEqual([[["SMask", true]]]);
    expect(context.localGStateCache.getByName(CACHE_KEY)).toBeNull();
  });

  it("waits for the soft mask to be handled before adding the operator", async () => {
    const context = createContext();
    const deferred = createDeferred();
