    await flushTasks();

    expect(setGStateOps(context.operatorList)).toEqual([]);
    expect(context.operatorList.fnArray).toEqual([]);

    deferred.resolve("g_font_deferred");
    await promise;

    expect(context.operatorList.dependencies.has("g_font_deferred")).toBe(
      true
    );
    expect(setGStateOps(context.operatorList)).toEqual([
      [["Font", ["g_font_deferred", 10]]],
