  });

  it("runs the asynchronous handlers sequentially", async () => {
    const context = createContext();
    const order = [];
    const fontDeferred = createDeferred();

    context.evaluator.handleSetFont = createSpy(() => {
      order.push("font");
      return fontDeferred.promise;
    });
    context.evaluator.handleSMask = createSpy(async () => {
      order.push("smask");
    });

    const promise = context.run(
      makeGState([
        ["Font", [Ref.get(16, 0), 11]],
        ["SMask", makeGState()],
      ])
    );
    await flushTasks();

    expect(order).toEqual(["font"]);

    fontDeferred.resolve("g_font_seq");
    await promise;

    expect(order).toEqual(["font", "smask"]);
    expect(setGStateOps(context.operatorList)).toEqual([
      [
        ["SMask", true],
        ["Font", ["g_font_seq", 11]],
      ],
    ]);
  });
});

