```js
it("awaits readToUnicode and assigns buildToUnicode result", async () => {
  const dict = new Dict();
  const observed = {};
  const built = { built: true };
  const read = spy(() => Promise.resolve("raw-to-unicode"));
  const build = spy(async (props) => {
    observed.toUnicode = props.toUnicode;
    observed.differences = props.differences;
    observed.dict = props.dict;
    observed.hasEncoding = props.hasEncoding;
    return built;
  });
  const { evaluator } = createEvaluator({ readToUnicode: read, buildToUnicode: build });
  const properties = createProperties({ toUnicode: "initial" });
  const result = await extract(evaluator, dict, properties);
  expect(read.calls).toEqual([["initial"]]);
  expect(build.callCount()).toBe(1);
  expect(build.calls[0][0]).toBe(properties);
  expect(observed.toUnicode).toBe("raw-to-unicode");
  expect(observed.differences).toBe(properties.differences);
  expect(observed.dict).toBe(dict);
  expect(observed.hasEncoding).toBe(false);
  expect(result.toUnicode).toBe(built);
});
```

