function spy(implementation = () => {}) {
  const calls = [];
  const fn = (...args) => {
    calls.push(args);
    return implementation(...args);
  };
  fn.calls = calls;
  fn.callCount = () => calls.length;
  return fn;
}

const SIMSUN = "\xCB\xCE\xCC\xE5";
const SIMFANG = "\xB7\xC2\xCB\xCE";

function createProperties(overrides = {}) {
  return {
    type: "Type1",
    name: "Helvetica",
    flags: 0,
    composite: false,
    file: null,
    toUnicode: null,
    ...overrides,
  };
}

function createEvaluator({
  ignoreErrors = false,
  builtToUnicode = { kind: "built-to-unicode" },
  readToUnicodeResult = "read-to-unicode-result",
  cidToGidMapResult = { kind: "cid-to-gid-map" },
  cMapData = "endcmap",
  fetchIfRef = value => value,
  readToUnicode: readToUnicodeOverride,
  buildToUnicode: buildToUnicodeOverride,
  readCidToGidMap: readCidToGidMapOverride,
  fetchBuiltInCMap: fetchBuiltInCMapOverride,
} = {}) {
  const evaluator = {
    xref: { fetchIfRef: spy(fetchIfRef) },
    options: { ignoreErrors },
    readToUnicode:
      readToUnicodeOverride ?? spy(() => Promise.resolve(readToUnicodeResult)),
    buildToUnicode: buildToUnicodeOverride ?? spy(async () => builtToUnicode),
    readCidToGidMap: readCidToGidMapOverride ?? spy(() => cidToGidMapResult),
