        cMapData: stringToBytes(cMapData),
        isCompressed: false,
      })),
  };
  return { evaluator, builtToUnicode, cidToGidMapResult };
}

function extract(evaluator, dict, properties) {
  return PartialEvaluator.prototype.extractDataStructures.call(
    evaluator,
    dict,
    properties
  );
}

async function captureWarnings(callback) {
  const warnings = [];
  const originalWarn = console.warn;
