      expect(properties.flags).toBe(0b101);
    });

    it("falls back to the BaseFont metrics of a monospaced standard font", () => {
      const { evaluator } = createEvaluator();
      const dict = createDict(evaluator.xref, { BaseFont: new Name("Courier") });
      const descriptor = createDict(evaluator.xref, { MissingWidth: 123 });
      const properties = createProperties({
        firstChar: 0,
        flags: 0,
        differences: new Map(),
        defaultEncoding: {},
      });

      evaluator.extractWidths(dict, descriptor, properties);
      expect(properties.defaultWidth).toBe(600);
      expect(Object.keys(properties.widths)).toEqual([]);
      expect(isFixedPitch(properties)).toBe(true);
    });

    it("builds the widths from the BaseFont metrics and the encoding", () => {
