    it("ignores /Widths and /MissingWidth when there is no BaseFont", () => {
      const { evaluator } = createEvaluator();
      const dict = createDict(evaluator.xref, { Widths: "nope" });
      const descriptor = createDict(evaluator.xref, { MissingWidth: 123 });
      const properties = createProperties({ firstChar: 0 });

