import { StandardEncoding } from "../../../src/core/encodings.js";
import { Dict, Name, Ref } from "../../../src/core/primitives.js";
import { FontFlags } from "../../../src/core/fonts_utils.js";
import { PartialEvaluator } from "../../../src/core/evaluator.js";

function createXref(refValues = new Map()) {
  const fetch = jest.fn(ref => {
    if (!refValues.has(ref.num)) {
      throw new Error(`Unexpected reference: ${ref.num}`);
    }
    return refValues.get(ref.num);
  });
  const fetchIfRef = jest.fn(value =>
    value instanceof Ref ? fetch(value) : value
  );

  return { fetch, fetchIfRef };
}

function createEvaluator(refValues = new Map()) {
  const xref = createXref(refValues);
  const evaluator = new PartialEvaluator({
    xref,
    handler: null,
    pageIndex: 0,
  });

  return { evaluator, xref };
}

function createDict(xref, entries) {
  const dict = new Dict(xref);

  for (const [key, value] of Object.entries(entries)) {
    dict.set(key, value);
  }
  return dict;
}

function createProperties(overrides = {}) {
  return {
    composite: false,
    flags: 0,
    ...overrides,
  };
}

function isFixedPitch(properties) {
  return (properties.flags & FontFlags.FixedPitch) === FontFlags.FixedPitch;
}

describe("PartialEvaluator.extractWidths", () => {
  describe("composite fonts", () => {
    it("uses the default DW of 1000 when /DW is missing", () => {
      const { evaluator } = createEvaluator();
      const dict = createDict(evaluator.xref, {});
      const properties = createProperties({ composite: true });

      expect(evaluator.extractWidths(dict, new Dict(), properties)).toBe(
        undefined
      );
      expect(properties.defaultWidth).toBe(1000);
      expect(properties.widths).toEqual([]);
      expect(properties.vmetrics).toEqual([]);
      expect(properties.defaultVMetrics).toBeUndefined();
    });

    it("rounds a fractional /DW up", () => {
      const { evaluator } = createEvaluator();

      for (const [dw, expected] of [
        [500.1, 501],
        [600, 600],
        [0, 0],
        [999.0001, 1000],
      ]) {
        const dict = createDict(evaluator.xref, { DW: dw });
        const properties = createProperties({ composite: true });

        evaluator.extractWidths(dict, new Dict(), properties);
        expect(properties.defaultWidth).toBe(expected);
      }
    });

    it("falls back to 1000 when /DW isn't a number", () => {
      const { evaluator } = createEvaluator();
      const dict = createDict(evaluator.xref, { DW: "900" });
      const properties = createProperties({ composite: true });

      evaluator.extractWidths(dict, new Dict(), properties);
      expect(properties.defaultWidth).toBe(1000);
    });

    it("handles the array form of /W", () => {
      const { evaluator } = createEvaluator();
      const dict = createDict(evaluator.xref, { W: [1, [100, 200]] });
      const properties = createProperties({ composite: true });

      evaluator.extractWidths(dict, new Dict(), properties);
      expect(properties.widths.length).toBe(3);
      expect(properties.widths[0]).toBeUndefined();
      expect(properties.widths[1]).toBe(100);
      expect(properties.widths[2]).toBe(200);
    });

    it("skips non-numeric widths in the array form of /W", () => {
      const { evaluator } = createEvaluator();
      const dict = createDict(evaluator.xref, {
        W: [0, [100, "nope", 300]],
      });
      const properties = createProperties({ composite: true });

      evaluator.extractWidths(dict, new Dict(), properties);
      expect(properties.widths.length).toBe(3);
      expect(properties.widths[0]).toBe(100);
      expect(properties.widths[1]).toBeUndefined();
      expect(properties.widths[2]).toBe(300);
    });

    it("handles the range form of /W", () => {
