import { CharCodeMap } from "../../../src/core/char_code_map.js";
import { Font } from "../../../src/core/fonts.js";
import { IdentityToUnicodeMap, ToUnicodeMap } from "../../../src/core/to_unicode_map.js";
import { WinAnsiEncoding } from "../../../src/core/encodings.js";

// PDF glyph space units are one thousandth of a text space unit.
const GLYPH_SPACE_UNITS = 1000;

function buildToUnicodeMap(entries = []) {
  const cmap = new CharCodeMap();
  for (const [charCode, unicode] of entries) {
    cmap.set(charCode, unicode);
  }
  return new ToUnicodeMap(cmap);
}

/**
 * Creates a `Font`-like object without going through the (heavy) constructor,
 * so that `fallbackToSystemFont` can be exercised on its own.
 */
function createFont(overrides = {}) {
  const font = Object.create(Font.prototype);
  return Object.assign(
    font,
    {
      name: "Helvetica",
      type: "Type1",
      widths: Object.create(null),
      differences: new Map(),
      defaultEncoding: WinAnsiEncoding,
      composite: false,
      cidEncoding: "",
      ascent: NaN,
      descent: NaN,
      capHeight: NaN,
      toUnicode: buildToUnicodeMap(),
      toFontChar: new Map(),
    },
    overrides
  );
}

/**
 * Runs `fallbackToSystemFont` and returns both the (fake) font and the
 * `properties` object that was handed to the method.
 */
function runFallback(name, fontOverrides = {}, propertiesOverrides = {}) {
  const font = createFont({ name, ...fontOverrides });
  const properties = {
    widths: font.widths,
    differences: font.differences,
    toUnicode: font.toUnicode,
    ...propertiesOverrides,
  };
  font.fallbackToSystemFont(properties);
  return { font, properties };
}

describe("Font.prototype.fallbackToSystemFont", () => {
  it("flags the font as missing and derives loadedName from the standard name", () => {
    const { font } = runFallback("Helvetica");

    expect(font.missingFile).toBe(true);
    expect(font.loadedName).toBe("Helvetica");

    const { font: mapped } = runFallback("TimesNewRomanPS-BoldMT");
    // "TimesNewRomanPS-BoldMT" -> "Times-Bold", and the "-Bold" suffix is cut.
    expect(mapped.loadedName).toBe("Times");
  });

  it("normalizes separators and whitespace in the name before the lookup", () => {
    const { font } = runFallback("Arial, Bold");

    // "Arial, Bold" -> "Arial-Bold" -> "Helvetica-Bold".
    expect(font.loadedName).toBe("Helvetica");
    expect(font.bold).toBe(true);
    expect(font.ascent).toBe(718 / GLYPH_SPACE_UNITS);

    const { font: italic } = runFallback("Arial_BoldItalic");
    expect(italic.bold).toBe(true);
    expect(italic.italic).toBe(true);
  });

  it("fills in the missing basic metrics from the resolved standard font", () => {
    const { font } = runFallback("Helvetica");

    expect(font.ascent).toBe(718 / GLYPH_SPACE_UNITS);
    expect(font.descent).toBe(-207 / GLYPH_SPACE_UNITS);
    expect(font.capHeight).toBe(718 / GLYPH_SPACE_UNITS);
  });

  it("does not override metrics that are already known", () => {
    const { font } = runFallback("Helvetica", {
      ascent: 1.5,
      descent: -0.5,
      capHeight: 0.9,
    });

    expect(font.ascent).toBe(1.5);
    expect(font.descent).toBe(-0.5);
    expect(font.capHeight).toBe(0.9);
  });

  it("keeps unknown metrics unset when the font has no basic metrics", () => {
    const { font } = runFallback("SomeUnmappedFontName");

    expect(Number.isNaN(font.ascent)).toBe(true);
    expect(Number.isNaN(font.descent)).toBe(true);
    expect(Number.isNaN(font.capHeight)).toBe(true);
  });

  it("derives bold and italic from the resolved standard font name", () => {
    const { font } = runFallback("Helvetica-BoldOblique");
    expect(font.bold).toBe(true);
    expect(font.italic).toBe(true);

