// PDF glyph space units are one thousandth of a text space unit.
const GLYPH_SPACE_UNITS = 1000;

function buildToUnicodeMap(entries = []) {
  const cmap = new CharCodeMap();
  for (const [charCode, unicode] of entries) {
    cmap.set(charCode, unicode);
  }
  return new ToUnicodeMap(cmap);
}

/**
 * Creates a `Font`-like object without going through the (heavy) constructor,
 * so that `fallbackToSystemFont` can be exercised on its own.
 */
function createFont(overrides = {}) {
  const font = Object.create(Font.prototype);
  return Object.assign(
    font,
    {
      name: "Helvetica",
      type: "Type1",
      widths: Object.create(null),
      differences: new Map(),
      defaultEncoding: WinAnsiEncoding,
      composite: false,
      cidEncoding: "",
      ascent: NaN,
      descent: NaN,
      capHeight: NaN,
      toUnicode: buildToUnicodeMap(),
      toFontChar: new Map(),
