it("does not override metrics that are already known", () => {
  const { font } = runFallback("Helvetica", {
    ascent: 1.5,
    descent: -0.5,
    capHeight: 0.9,
  });

  expect(font.ascent).toBe(1.5);
  expect(font.descent).toBe(-0.5);
  expect(font.capHeight).toBe(0.9);
});

it("keeps unknown metrics unset when the font has no basic metrics", () => {
  const { font } = runFallback("SomeUnmappedFontName");

  expect(Number.isNaN(font.ascent)).toBe(true);
  expect(Number.isNaN(font.descent)).toBe(true);
  expect(Number.isNaN(font.capHeight)).toBe(true);
});

it("derives bold and italic from the resolved standard font name", () => {
  const { font } = runFallback("Helvetica-BoldOblique");
  expect(font.bold).toBe(true);
  expect(font.italic).toBe(true);

  const { font: italicOnly } = runFallback("Times-Italic");
  expect(italicOnly.bold).toBe(false);
  expect(italicOnly.italic).toBe(true);

  const { font: mappedBold } = runFallback("Arial-BoldMT");
  expect(mappedBold.bold).toBe(true);
  expect(mappedBold.italic).toBe(false);
  expect(mappedBold.loadedName).toBe("Helvetica");
});

it("detects black from the original, non-normalized name", () => {
  const { font } = runFallback("ArialBlack");

  // "ArialBlack" is rendered as Helvetica, but the flag uses the PDF name.
  expect(font.loadedName).toBe("Helvetica");
  expect(font.black).toBe(true);
  expect(font.bold).toBe(false);

  const { font: unknown } = runFallback("MyBlackFont");
  expect(unknown.black).toBe(true);
  expect(unknown.loadedName).toBe("MyBlackFont");
});

it("only requests remeasuring when it can change the glyph widths", () => {
  const { font: standard } = runFallback("Helvetica", {
    widths: { 65: 0.6 },
  });
  expect(standard.remeasure).toBe(false);

  const { font: standardNoWidths } = runFallback("Helvetica");
  expect(standardNoWidths.remeasure).toBe(false);

  const { font: nonStandard } = runFallback("SomeUnmappedFontName", {
    widths: { 65: 0.6 },
  });
  expect(nonStandard.remeasure).toBe(true);

  // A narrow standard font is substituted by a wider one, hence remeasure.
  const { font: narrow } = runFallback("ArialNarrow", {
    widths: { 65: 0.6 },
  });
  expect(narrow.remeasure).toBe(true);
  expect(narrow.loadedName).toBe("Helvetica");

  const { font: narrowNoWidths } = runFallback("ArialNarrow");
  expect(narrowNoWidths.remeasure).toBe(false);
});

it("builds toFontChar from the default encoding and the differences", () => {
  const { font } = runFallback("Helvetica", {
    differences: new Map([[65, "alpha"]]),
  });

  expect(font.toFontChar).toBeInstanceOf(Map);
  expect(font.toFontChar.get(32)).toBe(32); // space
  expect(font.toFontChar.get(66)).toBe(66); // "B"
  // The /Differences entry takes precedence over the default encoding.
  expect(font.toFontChar.get(65)).toBe(0x3b1); // GREEK SMALL LETTER ALPHA
});

it("uses the glyph name of the default encoding for non-composite Unknown fonts", () => {
  const { font } = runFallback("SomeUnmappedFontName", {
    toUnicode: buildToUnicodeMap([
      [1, "Q"],
      [65, "Q"],
    ]),
  });

  // Char code 1 has no glyph name, so the ToUnicode value is kept.
  expect(font.toFontChar.get(1)).toBe(0x51);
  // Char code 65 is "A" in WinAnsi, which wins over the ToUnicode value.
  expect(font.toFontChar.get(65)).toBe(65);
});

it("keeps the ToUnicode values for composite Unknown fonts", () => {
  const { font } = runFallback("SomeUnmappedFontName", {
    composite: true,
    toUnicode: buildToUnicodeMap([[65, "Q"]]),
  });

  expect(font.toFontChar.get(65)).toBe(0x51);
  expect(font.toFontChar.size).toBe(1);
});

it("falls back to an unmapped name when the substitute is not standard", () => {
  // "ComicSansMS" maps to "Comic Sans MS", which is not a standard font.
  const { font } = runFallback("ComicSansMS", {
    toUnicode: buildToUnicodeMap([[65, "Q"]]),
  });

  expect(font.loadedName).toBe("Comic Sans MS");
  // Unknown-font handling: the default encoding wins for non-composite.
  expect(font.toFontChar.get(65)).toBe(65);
});

it("uses the Symbol encoding for Symbol fonts", () => {
  const { font } = runFallback("Symbol");
  expect(font.toFontChar.get(65)).toBe(0x391); // GREEK CAPITAL LETTER ALPHA

  const { font: withDifferences } = runFallback("Symbol", {
    differences: new Map([[65, "alpha"]]),
  });
  expect(withDifferences.toFontChar.get(65)).toBe(0x3b1);
});

it("uses the glyph-id keyed Symbol encoding for CID-keyed Symbol fonts", () => {
  const { font } = runFallback("Symbol", {
    composite: true,
    cidEncoding: "Identity-H",
  });

  // Glyph ids 0-2 are .notdef/null/nonmarkingreturn, glyph id 3 is "space".
  expect(font.toFontChar.get(0)).toBeUndefined();
  expect(font.toFontChar.get(1)).toBeUndefined();
  expect(font.toFontChar.get(3)).toBe(32);
});

it("uses the ZapfDingbats encoding for ZapfDingbats fonts", () => {
  const { font } = runFallback("ZapfDingbats");

  expect(font.toFontChar.get(0)).toBeUndefined();
  expect(font.toFontChar.get(33)).toBe(0x2701); // "a1"

  const { font: withDifferences } = runFallback("ZapfDingbats", {
    differences: new Map([[33, "a2"]]),
  });
  expect(withDifferences.toFontChar.get(33)).toBe(0x2702);
});

it("builds a glyph map for standard fonts embedded as Identity CID fonts", () => {
  const { font } = runFallback("Helvetica", {
    type: "CIDFontType2",
    composite: true,
    cidEncoding: "Identity-H",
  });

  expect(font.toFontChar).toBeInstanceOf(Map);
  expect(font.toFontChar.get(2)).toBe(10);
  expect(font.toFontChar.get(3)).toBe(32);
  expect(font.toFontChar.get(65)).toBe(94);

  expect(font.toUnicode).toBeInstanceOf(ToUnicodeMap);
  expect(font.toUnicode.get(3)).toBe(32);
  expect(font.toUnicode.size).toBe(font.toFontChar.size);
});

it("uses the Mac-ordered glyph map for TrebuchetMS", () => {
  const { font } = runFallback("TrebuchetMS", {
    type: "CIDFontType2",
    composite: true,
    cidEncoding: "Identity-H",
  });

  // TrebuchetMS does not share the glyph ordering of the standard fonts.
  expect(font.toFontChar.get(3)).toBe(32);
  expect(font.toFontChar.get(151)).toBe(0x3bc);
  expect(font.toFontChar.get(236)).toBe(0xde);
  expect(font.toFontChar.get(307)).toBe(0x17c);
  expect(font.toFontChar.get(151)).not.toBe(
    runFallback("Helvetica", {
      type: "CIDFontType2",
      composite: true,
      cidEncoding: "Identity-H",
    }).font.toFontChar.get(151)
  );
});

