  it("applies the Arial Black supplemental glyph map", () => {
    const { font } = runFallback("Arial-Black", {
      type: "CIDFontType2",
      composite: true,
      cidEncoding: "Identity-H",
    });

    expect(font.black).toBe(true);
    expect(font.toFontChar.get(227)).toBe(322);
    expect(font.toFontChar.get(264)).toBe(261);
    expect(font.toFontChar.get(291)).toBe(346);
  });

  it("applies the Calibri supplemental glyph map", () => {
    const { font } = runFallback("Calibri", {
      type: "CIDFontType2",
      composite: true,
      cidEncoding: "Identity-H",
    });

    expect(font.loadedName).toBe("Helvetica");
    expect(font.toFontChar.get(1)).toBe(32);
    expect(font.toFontChar.get(4)).toBe(65);
    expect(font.toFontChar.get(17)).toBe(66);
  });

  it("remaps glyph ids through the CIDToGIDMap when one is given", () => {
    const { font } = runFallback(
      "Helvetica",
      { type: "CIDFontType2", composite: true, cidEncoding: "Identity-H" },
      {
        cidToGidMap: new Map([
          [32, 100],
          [33, 101],
        ]),
      }
    );

    expect(font.toFontChar.get(3)).toBe(100);
    expect(font.toFontChar.get(4)).toBe(101);
    // Entries without a CIDToGIDMap counterpart are left untouched.
    expect(font.toFontChar.get(2)).toBe(10);
    expect(font.toUnicode.get(3)).toBe(100);
  });

  it("drops unmapped entries for an incomplete CIDToGIDMap", () => {
    const { font } = runFallback(
      "Helvetica",
      {
        type: "CIDFontType2",
        composite: true,
        cidEncoding: "Identity-H",
        toUnicode: new IdentityToUnicodeMap(0, 10),
      },
      { cidToGidMap: new Map([[32, 100]]), hasIncludedToUnicodeMap: true }
    );

    // Char codes covered by the identity /ToUnicode map but absent from the
    // /CIDToGIDMap are removed, to fall back to the char code itself.
    expect(font.toFontChar.get(2)).toBeUndefined();
    expect(font.toFontChar.get(3)).toBeUndefined();
    // Char codes outside the identity map are kept.
    expect(font.toFontChar.get(65)).toBe(94);
  });

  it("keeps the entries when no /ToUnicode map was included", () => {
    const { font } = runFallback(
      "Helvetica",
      {
        type: "CIDFontType2",
        composite: true,
        cidEncoding: "Identity-H",
        toUnicode: new IdentityToUnicodeMap(0, 10),
      },
      { cidToGidMap: new Map([[32, 100]]) }
    );

    expect(font.toFontChar.get(3)).toBe(100);
  });

  it("merges ToUnicode data for standard CID fonts with a non-Identity encoding", () => {
    const toUnicode = buildToUnicodeMap([[500, "Z"]]);
    const { font, properties } = runFallback("Helvetica", {
      type: "CIDFontType2",
      cidEncoding: "Adobe-Identity-UCS",
      toUnicode,
    });

    expect(properties.toUnicode).toBe(toUnicode);
    expect(font.toUnicode).toBe(toUnicode);
    expect(font.toUnicode.size).toBe(1);
    expect(font.toUnicode.get(500)).toBe("Z");
    expect(font.toFontChar.get(65)).toBe(65);
    expect(font.toFontChar.get(500)).toBe(0x5a);
  });

  it("improves the glyph map of Tahoma/Verdana composite fonts", () => {
    const { font } = runFallback("Verdana", {
      composite: true,
      toUnicode: new IdentityToUnicodeMap(0, 3),
    });

    expect(font.toFontChar.get(0)).toBe(0);
    expect(font.toFontChar.get(3)).toBe(32);
    expect(font.toFontChar.get(65)).toBe(94);

