```js
function readComponents(bytes, entry) {
  const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const end = Math.min(entry.endOffset, bytes.byteLength);
  const comps = [];
  let p = entry.offset + GLYPH_HEADER_SIZE;
  while (p + 4 <= end) {
    const flags = dv.getUint16(p);
    const gid = dv.getUint16(p + 2);
    const size = componentSize(flags);
    comps.push({ flags, gid, offset: p - entry.offset, size, raw: bytes.slice(p, p + size) });
    p += size;
    if (!(flags & MORE_COMPONENTS)) break;
  }
  return comps;
}
```
