```js
function buildTable(glyphBytesList) {
  const parts = [];
  const entries = [];
  let pos = 0;
  for (const bytes of glyphBytesList) {
    const padding = (4 - (pos % 4)) % 4;
    if (padding) { parts.push(new Uint8Array(padding)); pos += padding; }
    entries.push({ offset: pos, endOffset: pos + bytes.length });
    parts.push(bytes);
    pos += bytes.length;
  }
  const table = new Uint8Array(pos);
  let p = 0;
  for (const part of parts) { table.set(part, p); p += part.length; }
  return { table, entries };
}
```

