import { pruneCompositeGlyphCycles } from "../../../src/core/glyf.js";

const GLYPH_HEADER_SIZE = 10;

// Simple glyph flags used by the composite records built below.
const ARG_1_AND_2_ARE_WORDS = 1 << 0;
const WE_HAVE_A_SCALE = 1 << 3;
const MORE_COMPONENTS = 1 << 5;
const WE_HAVE_AN_X_AND_Y_SCALE = 1 << 6;
const WE_HAVE_A_TWO_BY_TWO = 1 << 7;
const WE_HAVE_INSTRUCTIONS = 1 << 8;

let installedGetOrInsertComputed = false;

// The production code relies on `Map.prototype.getOrInsertComputed`, which is
// not available in every runtime used to execute the unit tests. Install a
// spec-compatible shim for the duration of the suite only.
beforeAll(() => {
  if (typeof Map.prototype.getOrInsertComputed !== "function") {
    installedGetOrInsertComputed = true;
    Object.defineProperty(Map.prototype, "getOrInsertComputed", {
      configurable: true,
      writable: true,
      value(key, callback) {
        if (this.has(key)) {
          return this.get(key);
        }
        const value = callback(key);
        this.set(key, value);
        return value;
      },
    });
  }
});

afterAll(() => {
  if (installedGetOrInsertComputed) {
    delete Map.prototype.getOrInsertComputed;
  }
});

/**
 * Size, in bytes, of a component record, depending on its flags.
 */
function componentSize(flags) {
  let size = 4 + (flags & ARG_1_AND_2_ARE_WORDS ? 4 : 2);
  if (flags & WE_HAVE_A_SCALE) {
    size += 2;
  } else if (flags & WE_HAVE_AN_X_AND_Y_SCALE) {
    size += 4;
  } else if (flags & WE_HAVE_A_TWO_BY_TWO) {
    size += 8;
  }
  return size;
}

/**
 * Build a single component record (flags, glyph id, arguments and scale).
 */
function componentRecord(flags, gid) {
  const size = componentSize(flags);
  const record = new Uint8Array(size);
  const view = new DataView(record.buffer);
  view.setUint16(0, flags);
  view.setUint16(2, gid);
  // Deterministic payload, distinct per (gid, size, position), so that
  // misplaced or truncated records are detected.
  for (let i = 4; i < size; i++) {
    record[i] = (0x40 + 7 * gid + i) & 0xff;
  }
  return record;
}

/**
 * Build a composite glyph: a 10 bytes header with a negative contour count
 * followed by the given component records.
 */
function compositeGlyph(components) {
  let length = GLYPH_HEADER_SIZE;
  for (const { flags } of components) {
    length += componentSize(flags);
  }
  const bytes = new Uint8Array(length);
  const view = new DataView(bytes.buffer);
  view.setInt16(0, -1); // numberOfContours < 0 => composite glyph
  view.setInt16(2, 11); // xMin
  view.setInt16(4, 22); // yMin
  view.setInt16(6, 33); // xMax
  view.setInt16(8, 44); // yMax
  let pos = GLYPH_HEADER_SIZE;
  for (const { flags, gid } of components) {
    const record = componentRecord(flags, gid);
    bytes.set(record, pos);
    pos += record.length;
  }
  return bytes;
}

/**
 * Build a simple glyph (numberOfContours >= 0).
 */
function simpleGlyph() {
  const bytes = new Uint8Array(GLYPH_HEADER_SIZE + 8);
  const view = new DataView(bytes.buffer);
  view.setInt16(0, 2);
  view.setInt16(2, 5);
  view.setInt16(4, 6);
  view.setInt16(6, 7);
  view.setInt16(8, 8);
  bytes.fill(0x9c, GLYPH_HEADER_SIZE);
  return bytes;
}

/**
 * Lay out the given glyphs into a `glyf` table, 4 bytes aligned, and return
 * the matching `loca` entries.
 */
function buildTable(glyphs) {
  const entries = [];
  const parts = [];
  let pos = 0;
  for (const glyph of glyphs) {
    const padding = (4 - (pos % 4)) % 4;
    if (padding > 0) {
      parts.push(new Uint8Array(padding));
      pos += padding;
    }
    entries.push({ offset: pos, endOffset: pos + glyph.length });
    parts.push(glyph);
    pos += glyph.length;
  }
  const table = new Uint8Array(pos);
  let write = 0;
  for (const part of parts) {
    table.set(part, write);
    write += part.length;
  }
  return { table, entries };
}

/**
 * Independent reader for the component list of the glyph described by `entry`.
 */
function readComponents(bytes, entry) {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const end = Math.min(entry.endOffset, bytes.byteLength);
  const components = [];
  let pos = entry.offset + GLYPH_HEADER_SIZE;
  while (pos + 4 <= end) {
    const flags = view.getUint16(pos);
    const gid = view.getUint16(pos + 2);
    const size = componentSize(flags);
    components.push({
      flags,
      gid,
      offset: pos - entry.offset,
      size,
      raw: bytes.slice(pos, pos + size),
    });
    pos += size;
    if (!(flags & MORE_COMPONENTS)) {
      break;
    }
  }
  return components;
}

function withFlags(raw, flags) {
  const copy = raw.slice();
  new DataView(copy.buffer).setUint16(0, flags);
  return copy;
}

function bytesOf(array) {
  return Array.from(array);
}

function zeros(count) {
  return new Array(count).fill(0);
}

