function buildTable(glyphs) {
  const entries = [];
  const parts = [];
  let pos = 0;
  for (const glyph of glyphs) {
    const padding = (4 - (pos % 4)) % 4;
    if (padding) { parts.push(new Uint8Array(padding)); pos += padding; }
    entries.push({ offset: pos, endOffset: pos + glyph.length });
    parts.push(glyph);
    pos += glyph.length;
  }
  const table = new Uint8Array(pos);
  let write = 0;
  for (const part of parts) { table.set(part, write); write += part.length; }
  return { table, entries };
}
