```js
function compositeGlyph(components) {
  let length = GLYPH_HEADER_SIZE;
  for (const { flags } of components) {
    length += componentSize(flags);
  }
  const bytes = new Uint8Array(length);
  const view = new DataView(bytes.buffer);
  view.setInt16(0, -1); // numberOfContours < 0 => composite
  view.setInt16(2, 11); // xMin
  view.setInt16(4, 22); // yMin
  view.setInt16(6, 33); // xMax
  view.setInt16(8, 44); // yMax
  let pos = GLYPH_HEADER_SIZE;
  for (const { flags, gid } of components) {
    const record = componentRecord(flags, gid);
    bytes.set(record, pos);
    pos += record.length;
  }
  return bytes;
}

function componentRecord(flags, gid) {
  const size = componentSize(flags);
  const record = new Uint8Array(size);
  const view = new DataView(record.buffer);
  view.setUint16(0, flags);
  view.setUint16(2, gid);
  // Distinct, deterministic payload so that moves can be detected.
  for (let i = 4; i < size; i++) {
    record[i] = (0x40 + gid * 7 + i) & 0xff;
  }
  return record;
}
