function makeImage({
  width,
  height,
  bpc = 8,
  numComps = 1,
  needsDecode = false,
  bytes = new Uint8Array(0),
  components = null,
  decodeAddends = null,
  decodeCoefficients = null,
}) {
  const calls = {
    getImageBytes: [],
    getComponents: [],
    decodeBuffer: [],
  };

  const image = Object.create(PDFImage.prototype);
  Object.assign(image, { width, height, bpc, numComps, needsDecode });

  if (decodeAddends) {
    image.decodeAddends = decodeAddends;
  }
  if (decodeCoefficients) {
    image.decodeCoefficients = decodeCoefficients;
  }

  image.getImageBytes = async (length, options) => {
    calls.getImageBytes.push({ length, options });
    return bytes;
  };

  if (components) {
    image.getComponents = input => {
      calls.getComponents.push(input);
      return components;
