function parseFont(bytes) {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const numTables = view.getUint16(4);
  const tables = new Map();
  for (let i=0; i<numTables; i++) {
    const p = 12 + i*16;
    const tag = String.fromCharCode(bytes[p], bytes[p+1], bytes[p+2], bytes[p+3]);
    const offset = view.getInt32(p+8);
    const length = view.getInt32(p+12);
    tables.set(tag, { offset, length, data: bytes.subarray(offset, offset+length) });
  }
  return { bytes, view, numTables, tables };
}
