function bytes(...parts) {
  const total = parts.reduce((sum, part) => sum + part.length, 0);
  const result = new Uint8Array(total);
  let offset = 0;
  for (const part of parts) {
    result.set(part, offset);
    offset += part.length;
  }
  return result;
}

// A sfnt file: 12-byte header, one 16-byte directory entry per table, then
// the (4-byte aligned) table data itself.
function buildFont(tables, version = [0, 1, 0, 0]) {
  const tags = Object.keys(tables).sort();
  let dataOffset = 12 + tags.length * 16;
  const offsets = Object.create(null);
  for (const tag of tags) {
    offsets[tag] = dataOffset;
    dataOffset += padTo4(tables[tag]).length;
  }

  const file = new Uint8Array(dataOffset);
  file.set(Uint8Array.from(version), 0);
  const view = new DataView(file.buffer);
  view.setUint16(4, tags.length);

  let entryOffset = 12;
  for (const tag of tags) {
    for (let i = 0; i < 4; i++) {
      file[entryOffset + i] = tag.charCodeAt(i);
    }
    view.setInt32(entryOffset + 4, 0); // checksum
    view.setInt32(entryOffset + 8, offsets[tag]);
    view.setInt32(entryOffset + 12, tables[tag].length);
    entryOffset += 16;
  }
  let offset = 12 + tags.length * 16;
  for (const tag of tags) {
    const data = padTo4(tables[tag]);
    file.set(data, offset);
    offset += data.length;
  }
  return file;
}

