/* eslint-disable no-console */
import { afterEach, beforeEach, describe, expect, jest, test } from "@jest/globals";

import { Font } from "../../../src/core/fonts.js";
import { Stream } from "../../../src/core/stream.js";

// The production code relies on this very recent proposal; keep the test
// runnable on the Node version available in this environment.
if (typeof Math.sumPrecise !== "function") {
  Math.sumPrecise = values => values.reduce((total, value) => total + value, 0);
}

const u16 = value => [(value >>> 8) & 0xff, value & 0xff];
const i32 = value => [
  (value >>> 24) & 0xff,
  (value >>> 16) & 0xff,
  (value >>> 8) & 0xff,
  value & 0xff,
];

function padTo4(bytes) {
  const padded = new Uint8Array((bytes.length + 3) & ~3);
  padded.set(bytes);
  return padded;
}

function bytes(...parts) {
  const total = parts.reduce((sum, part) => sum + part.length, 0);
  const result = new Uint8Array(total);
  let offset = 0;
  for (const part of parts) {
    result.set(part, offset);
    offset += part.length;
  }
  return result;
}

// A sfnt file: 12-byte header, one 16-byte directory entry per table, then
// the (4-byte aligned) table data itself.
function buildFont(tables, version = [0, 1, 0, 0]) {
  const tags = Object.keys(tables).sort();
  let dataOffset = 12 + tags.length * 16;
  const offsets = Object.create(null);
  for (const tag of tags) {
    offsets[tag] = dataOffset;
    dataOffset += padTo4(tables[tag]).length;
  }

  const file = new Uint8Array(dataOffset);
  file.set(Uint8Array.from(version), 0);
  const view = new DataView(file.buffer);
  view.setUint16(4, tags.length);

  let entryOffset = 12;
  for (const tag of tags) {
    for (let i = 0; i < 4; i++) {
      file[entryOffset + i] = tag.charCodeAt(i);
    }
    view.setInt32(entryOffset + 4, 0); // checksum
    view.setInt32(entryOffset + 8, offsets[tag]);
    view.setInt32(entryOffset + 12, tables[tag].length);
    entryOffset += 16;
  }
  let offset = 12 + tags.length * 16;
  for (const tag of tags) {
    const data = padTo4(tables[tag]);
    file.set(data, offset);
    offset += data.length;
  }
  return file;
}

function simpleGlyph() {
  // One contour with a single on-curve point.
  return Uint8Array.from([
    0, 1, // numberOfContours
    0, 0, 0, 0, 0, 100, 0, 100, // bbox
    0, 0, // endPtsOfContours
    0, 0, // instructionLength
    0x01, // flags: single on-curve point
    0, 50, // x coordinate
    0, 50, // y coordinate
  ]);
}
const GLYPH = simpleGlyph();
const GLYPH_PADDED_LENGTH = (GLYPH.length + 1) & ~1;

function makeCmapFormat6(charCode = 65, glyphId = 0) {
  return Uint8Array.from([
    ...u16(0), ...u16(1), // version, numTables
    ...u16(3), ...u16(1), ...i32(12), // (3, 1) encoding record
    ...u16(6), ...u16(12), ...u16(0), // format, length, language
    ...u16(charCode), ...u16(1), ...u16(glyphId),
  ]);
}

function cmapWithSubtable(platformId, encodingId, subtable) {
  return bytes(
    Uint8Array.from([
      ...u16(0), ...u16(1),
      ...u16(platformId), ...u16(encodingId), ...i32(12),
    ]),
    subtable
  );
}

function makeCmapFormat4(charCode, glyphId) {
  const delta = (glyphId - charCode) & 0xffff;
  return cmapWithSubtable(
    0, 3,
    Uint8Array.from([
      ...u16(4), ...u16(20), ...u16(0),
      ...u16(2), ...u16(0), ...u16(0), ...u16(0),
      ...u16(charCode), ...u16(0), ...u16(charCode),
      ...u16(delta), ...u16(0),
    ])
  );
}

function makeCmapFormat12(startCharCode, endCharCode, glyphCode) {
  return cmapWithSubtable(
    0, 3,
    Uint8Array.from([
      ...u16(12), ...u16(0), ...i32(28), ...u16(0), ...u16(0),
      ...i32(1), ...i32(startCharCode), ...i32(endCharCode), ...i32(glyphCode),
    ])
  );
}

function makeCmapUnsupported(format = 99) {
  return cmapWithSubtable(
    3, 1,
    Uint8Array.from([...u16(format), ...u16(10), ...u16(0), ...u16(0), ...u16(0)])
  );
}

const BASIC_CMAP = makeCmapFormat6();

function baseTables({
  numGlyphs = 1,
  maxpVersion = 0x00010000,
  maxZones = 2,
  maxFunctionDefs = 0,
  cmap = BASIC_CMAP,
} = {}) {
  const maxp = Uint8Array.from([
    ...i32(maxpVersion), ...u16(numGlyphs),
    ...u16(0), ...u16(0), ...u16(0), ...u16(0), ...u16(maxZones),
    ...u16(0), ...u16(0), ...u16(maxFunctionDefs), ...u16(0), ...u16(0),
    ...u16(0), ...u16(0), ...u16(0),
  ]);
  const head = new Uint8Array(54);
  head.set(Uint8Array.from(i32(0x00010000)), 0);
  head.set([0x5f, 0x0f, 0x3c, 0xf5], 12); // magic number
  head[18] = 0x03;
  head[19] = 0xe8; // unitsPerEm = 1000
  const hhea = new Uint8Array(36);
  hhea.set(Uint8Array.from(i32(0x00010000)), 0);
  hhea.set([0x03, 0x20, 0xff, 0x38], 4); // ascent 800, descent -200
  hhea.set([0x01, 0xf4], 10); // advanceWidthMax = 500
  hhea[35] = numGlyphs; // numberOfHMetrics
  const hmtx = new Uint8Array(numGlyphs * 4);
  for (let i = 0; i < numGlyphs; i++) {
    hmtx[4 * i] = 0x01;
    hmtx[4 * i + 1] = 0xf4; // advance width 500
  }
  const loca = new Uint8Array((numGlyphs + 1) * 2);
  if (numGlyphs === 1) {
    loca[2] = (GLYPH_PADDED_LENGTH >> 9) & 0xff;
    loca[3] = (GLYPH_PADDED_LENGTH >> 1) & 0xff;
  }
  const glyf = new Uint8Array(GLYPH_PADDED_LENGTH * numGlyphs);
  if (numGlyphs === 1) {
    glyf.set(GLYPH);
  }
  const tables = { maxp, head, hhea, hmtx, loca, glyf };
  if (cmap) {
    tables.cmap = cmap;
  }
  return tables;
}

function makeProperties(extra = {}) {
  return {
    loadedName: "test",
    composite: false,
    hasEncoding: false,
    isInternalFont: true,
    fontMatrix: [0.001, 0, 0, 0.001, 0, 0],
    bbox: [0, 0, 1000, 1000],
    ascent: 800,
    descent: -200,
    fixedPitch: false,
    italicAngle: 0,
    xHeight: 500,
    capHeight: 700,
    firstChar: 0,
    lastChar: 0,
    toUnicode: new Map(),
    differences: new Map(),
    ...extra,
  };
}

function makeContext(extra = {}) {
  return {
    name: "TestFont",
    psName: null,
    isOpenType: false,
    isSymbolicFont: false,
    differences: new Map(),
    toUnicode: new Map(),
    toFontChar: new Map(),
    cssFontInfo: undefined,
    convert: jest.fn(() => ({ converted: true })),
    ...extra,
  };
}

function run(tables, { properties, context, version } = {}) {
  const ctx = context ?? makeContext();
  const props = properties ?? makeProperties();
  const result = Font.prototype.checkAndRepair.call(
    ctx,
    "TestFont",
    new Stream(buildFont(tables, version)),
    props
  );
  return { result, context: ctx, properties: props };
}

function parseFont(data) {
  const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
  const numTables = view.getUint16(4);
  const tables = new Map();
  for (let i = 0; i < numTables; i++) {
    const entryOffset = 12 + i * 16;
    const tag = String.fromCharCode(...data.subarray(entryOffset, entryOffset + 4));
    const offset = view.getInt32(entryOffset + 8);
    const length = view.getInt32(entryOffset + 12);
    tables.set(tag, { offset, length, data: data.subarray(offset, offset + length) });
  }
  return { data, view, numTables, tables };
}

const readU16 = (data, offset) => (data[offset] << 8) | data[offset + 1];
const readI16 = (data, offset) => {
  const value = readU16(data, offset);
  return value & 0x8000 ? value - 0x10000 : value;
};

function makeMacNameTable() {
  return bytes(
    Uint8Array.from([...u16(0), ...u16(1), ...u16(18)]), // header
    Uint8Array.from([
      ...u16(1), ...u16(0), ...u16(0), // platform, encoding, language
      ...u16(6), ...u16(4), ...u16(0), // nameID, length, offset
    ]),
    Uint8Array.from([0x54, 0x65, 0x73, 0x74]) // "Test"
  );
}

function makeValidOS2Table() {
  const os2 = new Uint8Array(96);
  os2[0] = 0;
  os2[1] = 3; // version
  os2[8] = 0xab; // fsType (must be reset)
  os2[9] = 0xcd;
  os2.set([0, 1], 64); // usFirstCharIndex
  os2.set([0, 5], 66); // usLastCharIndex
  os2.set([0x01, 0xf4], 74); // usWinAscent
  return os2;
}

let warnSpy;

beforeEach(() => {
  warnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});
});

afterEach(() => {
  warnSpy.mockRestore();
});

function warnings() {
