}

describe("Font.checkAndRepair", () => {
  test("rebuilds a TrueType font and returns a serialized sfnt", () => {
    const { result, context } = run(baseTables());
    const parsed = parseFont(result);

    expect(result).toBeInstanceOf(Uint8Array);
    expect([...result.subarray(0, 4)]).toEqual([0, 1, 0, 0]);
    expect([...parsed.tables.keys()].sort()).toEqual([
