import { Lexer, Parser } from "../../../src/core/parser.js";
import { Stream } from "../../../src/core/stream.js";
import {
  setVerbosityLevel,
  VerbosityLevel,
} from "../../../src/shared/util.js";

const KNOWN_COMMANDS = {
  Q: { numArgs: 0, variableArgs: false },
  q: { numArgs: 0, variableArgs: false },
  cm: { numArgs: 6, variableArgs: false },
  TJ: { numArgs: 1, variableArgs: true },
};

/**
 * Converts strings and byte values into a `Uint8Array`.
 */
function bytesOf(...parts) {
  const bytes = [];
  for (const part of parts) {
    if (typeof part === "number") {
      bytes.push(part);
    } else {
      for (let i = 0; i < part.length; i++) {
        bytes.push(part.charCodeAt(i) & 0xff);
      }
    }
  }
  return Uint8Array.from(bytes);
}

function createParser(knownCommands) {
  // The parser is only used for its `lexer.knownCommands`, hence its input
  // stream doesn't matter.
  const lexer = new Lexer(new Stream(new Uint8Array(0)), knownCommands);

  return new Parser({ lexer });
}

function createStream(...parts) {
  return new Stream(bytesOf(...parts));
}

function remainingString(stream) {
  return String.fromCharCode(...stream.bytes.subarray(stream.pos));
}

describe("Parser.findDefaultInlineStreamEnd", () => {
  let warnCalls, originalWarn;

  function expectWarning(fragment) {
    expect(warnCalls.some(msg => msg.includes(fragment))).toBe(true);
  }

  beforeEach(() => {
    setVerbosityLevel(VerbosityLevel.WARNINGS);
    warnCalls = [];
    originalWarn = console.warn;
    console.warn = (...args) => {
      warnCalls.push(args.join(" "));
    };
  });

  afterEach(() => {
    console.warn = originalWarn;
  });

  describe("finding the end of the inline image data", () => {
    it("returns the data length when `EI` is followed by a space", () => {
      const parser = createParser(KNOWN_COMMANDS);
      const stream = createStream("abc", "EI Q\n");

      expect(parser.findDefaultInlineStreamEnd(stream)).toBe(3);
      // The stream is positioned at the start of the next operator.
      expect(stream.pos).toBe(6);
      expect(remainingString(stream)).toBe("Q\n");
      expect(warnCalls).toHaveLength(0);
    });

    it("accepts a LF after `EI`", () => {
      const parser = createParser(KNOWN_COMMANDS);
      const stream = createStream("abc", "EI\nQ\n");

      expect(parser.findDefaultInlineStreamEnd(stream)).toBe(3);
      expect(stream.pos).toBe(6);

      expect(stream.pos).toBe(6);
      expect(remainingString(stream)).toBe("Q\n");
      expect(warnCalls).toHaveLength(0);
    });

    it("accepts a CR after `EI`", () => {
      const parser = createParser(KNOWN_COMMANDS);
      const stream = createStream("abc", "EI\rQ\n");

      expect(parser.findDefaultInlineStreamEnd(stream)).toBe(3);
      expect(stream.pos).toBe(6);
      expect(remainingString(stream)).toBe("Q\n");
      expect(warnCalls).toHaveLength(0);
    });

    it("returns zero for empty inline image data", () => {
      const parser = createParser(KNOWN_COMMANDS);
      const stream = createStream("EI Q\n");

      expect(parser.findDefaultInlineStreamEnd(stream)).toBe(0);
      expect(stream.pos).toBe(3);
      expect(remainingString(stream)).toBe("Q\n");
      expect(warnCalls).toHaveLength(0);
    });

    it("returns a length relative to the current stream position", () => {
      const parser = createParser(KNOWN_COMMANDS);
      const bytes = bytesOf("XXabc", "EI Q\n");
      const stream = new Stream(bytes, 2, bytes.length - 2);

      expect(parser.findDefaultInlineStreamEnd(stream)).toBe(3);
      expect(stream.pos).toBe(8);
      expect(remainingString(stream)).toBe("Q\n");
      expect(warnCalls).toHaveLength(0);
    });

    it("does not include whitespace that precedes the `EI` marker", () => {
      const parser = createParser(KNOWN_COMMANDS);
      const stream = createStream("abc ", "EI Q\n");

      expect(parser.findDefaultInlineStreamEnd(stream)).toBe(3);
      expect(stream.pos).toBe(7);
      expect(remainingString(stream)).toBe("Q\n");
    });

    it("does not include a tab that precedes the `EI` marker", () => {
      const parser = createParser(KNOWN_COMMANDS);
      const stream = createStream("abc\t", "EI Q\n");

      expect(parser.findDefaultInlineStreamEnd(stream)).toBe(3);
      expect(stream.pos).toBe(7);
      expect(remainingString(stream)).toBe("Q\n");
    });

    it("finds a valid operator placed at the very end of the stream", () => {
      const parser = createParser(KNOWN_COMMANDS);
      const stream = createStream("abc", "EI Q");

      expect(parser.findDefaultInlineStreamEnd(stream)).toBe(3);
      expect(stream.pos).toBe(6);
      expect(remainingString(stream)).toBe("Q");
      expect(warnCalls).toHaveLength(0);
    });

    it("finds an operator with (long) decimal arguments", () => {
      const parser = createParser(KNOWN_COMMANDS);
      const stream = createStream(
        "abc",
        "EI 0.5 0.5 0.5 0.5 0.5 0.5 cm Q\n"
      );

      expect(parser.findDefaultInlineStreamEnd(stream)).toBe(3);
      expect(stream.pos).toBe(6);
      expect(remainingString(stream)).toBe(
        "0.5 0.5 0.5 0.5 0.5 0.5 cm Q\n"
      );
      expect(warnCalls).toHaveLength(0);
    });

    it("finds an operator that takes a variable number of arguments", () => {
      const parser = createParser(KNOWN_COMMANDS);
      const stream = createStream("abc", "EI (hi) TJ Q\n");

      expect(parser.findDefaultInlineStreamEnd(stream)).toBe(3);
      expect(stream.pos).toBe(6);
      expect(remainingString(stream)).toBe("(hi) TJ Q\n");
      expect(warnCalls).toHaveLength(0);
    });
  });

  describe("rejecting `EI` sequences that belong to the image data", () => {
    it("ignores `EI` followed by non-whitespace/control bytes", () => {
      const parser = createParser(KNOWN_COMMANDS);
      // "abcEI" followed by NUL, SOH and STX must not terminate the image.
      const stream = createStream("abcEI", 0x00, 0x01, 0x02, "EI Q\n");

      expect(parser.findDefaultInlineStreamEnd(stream)).toBe(8);
      expect(stream.pos).toBe(11);
      expect(remainingString(stream)).toBe("Q\n");
      expect(warnCalls).toHaveLength(0);
    });

    it("ignores `EI` followed by a non-ASCII byte", () => {
      const parser = createParser(KNOWN_COMMANDS);
      const stream = createStream("abcEI ", 0x80, "EI Q\n");

      expect(parser.findDefaultInlineStreamEnd(stream)).toBe(7);
      expect(stream.pos).toBe(10);
      expect(remainingString(stream)).toBe("Q\n");
      expect(warnCalls).toHaveLength(0);
    });

    it("accepts 0x7f as a visible ASCII byte after `EI`", () => {
      const parser = createParser(KNOWN_COMMANDS);
      const stream = createStream("abcEI ", 0x7f, "EI Q\n");

      expect(parser.findDefaultInlineStreamEnd(stream)).toBe(7);
      expect(stream.pos).toBe(10);
      expect(remainingString(stream)).toBe("Q\n");
      expect(warnCalls).toHaveLength(0);
    });

    it("accepts a single NUL byte after `EI`", () => {
      const parser = createParser(KNOWN_COMMANDS);
      const stream = createStream("abcEI ", 0x00, "Q\n");

      expect(parser.findDefaultInlineStreamEnd(stream)).toBe(3);
      expect(stream.pos).toBe(6);
      // The single NUL byte isn't consumed from the underlying stream.
      expect(remainingString(stream)).toBe("\u0000Q\n");
      expect(warnCalls).toHaveLength(0);
    });

    it("rejects a sequence of NUL bytes after `EI`", () => {
      const parser = createParser(KNOWN_COMMANDS);
      const stream = createStream("abcEI ", 0x00, 0x00, "Q\n");

      // The final (invalid) "EI" occurrence is used as a fallback, and the
      // stream position is reset accordingly.
      expect(parser.findDefaultInlineStreamEnd(stream)).toBe(3);
      expect(stream.pos).toBe(6);
      expect(remainingString(stream)).toBe(String.fromCharCode(0, 0, 81, 10));
      expectWarning("Reached the end of the stream");
      expectWarning('trying to recover by using the last "EI"');
    });

    it("rejects `EI` followed by an unknown operator", () => {
      const parser = createParser(KNOWN_COMMANDS);
      const stream = createStream("abcEI XX EI Q\n");

      expect(parser.findDefaultInlineStreamEnd(stream)).toBe(8);
      expect(stream.pos).toBe(12);
      expect(remainingString(stream)).toBe("Q\n");
      expect(warnCalls).toHaveLength(0);
    });

    it("ignores an operator with the wrong number of arguments", () => {
      const parser = createParser(KNOWN_COMMANDS);
      const stream = createStream("abcEI 1 2 Q\nEI Q\n");

      // The first candidate is rejected ("Q" got two arguments), hence the
      // second "EI" marker is used.
      expect(parser.findDefaultInlineStreamEnd(stream)).toBe(11);
