import { Lexer } from "/testbed/src/core/parser.js";
import { StringStream } from "/testbed/src/core/stream.js";
import { EOF } from "/testbed/src/core/primitives.js";

function lex(str, known = null) {
  const lexer = new Lexer(new StringStream(str), known);
  const out = [];
  for (let i = 0; i < 5; i++) {
    try {
      const r = lexer.getObj();
      if (r === EOF) { out.push("EOF"); break; }
      if (typeof r === "string") out.push(JSON.stringify(r));
      else if (r === true || r === false || r === null) out.push(String(r));
      else if (r?.cmd !== undefined) out.push(`Cmd(${JSON.stringify(r.cmd)})`);
      else if (r?.name !== undefined) out.push(`Name(${JSON.stringify(r.name)})`);
      else out.push(typeof r + ":" + String(r));
    } catch (ex) { out.push(`THROW(${ex.name}: ${ex.message})`); }
  }
  return out;
}
console.log("a*128:", JSON.stringify(lex("a".repeat(128)).map(s => s.slice(0,12))));
console.log("a*129:", JSON.stringify(lex("a".repeat(129)).map(s => s.slice(0,60))));
console.log("a*130:", JSON.stringify(lex("a".repeat(130)).map(s => s.slice(0,60))));
console.log("1\\f2:", JSON.stringify(lex("1\f2")));
console.log("1%c\\n2:", JSON.stringify(lex("1%c\n2")));
console.log("<41 42>:", JSON.stringify(lex("<41 42>")));
console.log("<41:", JSON.stringify(lex("<41")));
console.log("(abc:", JSON.stringify(lex("(abc")));
console.log("(a\\\\nb):", JSON.stringify(lex("(a\\nb)")));
console.log("/A#42#43:", JSON.stringify(lex("/A#42#43")));
console.log("x>y:", JSON.stringify(lex("x>y")));
console.log("pos after 128cmd:", (() => { const s = new StringStream("a".repeat(128)); const l = new Lexer(s); return l.getObj().cmd.length; })());
EOF
