 * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
 * See the License for the specific language governing permissions and
 * limitations under the License.
 */

import { Lexer } from "../../../src/core/parser.js";
import {
  Cmd,
  EOF,
  isCmd,
  isName,
  Name,
} from "../../../src/core/primitives.js";
import { StringStream } from "../../../src/core/stream.js";
import { FormatError } from "../../../src/shared/util.js";

function createLexer(str, knownCommands = null) {
  return new Lexer(new StringStream(str), knownCommands);
}

function expectCommand(obj, cmd) {
  expect(isCmd(obj)).toBe(true);
  expect(obj).toEqual(Cmd.get(cmd));
  expect(obj.cmd).toBe(cmd);
}

function expectName(obj, name) {
  expect(isName(obj)).toBe(true);
  expect(obj).toEqual(Name.get(name));
  expect(obj.name).toBe(name);
}

describe("Lexer.getObj", () => {
  describe("end of stream", () => {
    it("returns EOF for an empty stream", () => {
      const lexer = createLexer("");

      expect(lexer.getObj()).toBe(EOF);
      // The EOF sentinel must be stable over repeated invocations.
      expect(lexer.getObj()).toBe(EOF);
    });

    it("returns EOF for a stream containing only whitespace", () => {
      const lexer = createLexer(" \t\n\f\r\x00 ");

      expect(lexer.getObj()).toBe(EOF);
    });

    it("returns EOF after the last token has been consumed", () => {
      const lexer = createLexer("42");

      expect(lexer.getObj()).toBe(42);
      expect(lexer.getObj()).toBe(EOF);
      expect(lexer.getObj()).toBe(EOF);
    });
  });

  describe("whitespace handling", () => {
    it.each([
      ["space", " "],
      ["tab", "\t"],
      ["line-feed", "\n"],
      ["form-feed", "\f"],
      ["carriage-return", "\r"],
      ["null", "\x00"],
    ])("treats %s as a token separator", (_, ch) => {
      const lexer = createLexer(`${ch}foo${ch}`);

      expectCommand(lexer.getObj(), "foo");
      expect(lexer.getObj()).toBe(EOF);
    });

    it("skips leading whitespace before reading a token", () => {
      const lexer = createLexer("  \n\t\r\n  /Name");

      expectName(lexer.getObj(), "Name");
    });

    it("skips whitespace in between tokens", () => {
      const lexer = createLexer("1 \t\n 2\r\n");

      expect(lexer.getObj()).toBe(1);
      expect(lexer.getObj()).toBe(2);
      expect(lexer.getObj()).toBe(EOF);
    });

    it("uses the null character as a separator inside a command run", () => {
      const lexer = createLexer("abc\x00def");

      expectCommand(lexer.getObj(), "abc");
      expectCommand(lexer.getObj(), "def");
      expect(lexer.getObj()).toBe(EOF);
    });
  });

  describe("comments", () => {
    it("skips a comment terminated by a line-feed", () => {
      const lexer = createLexer("% this is a comment\n/Real");

      expectName(lexer.getObj(), "Real");
    });

    it("skips a comment terminated by a carriage-return", () => {
      const lexer = createLexer("% comment\rTrue");

      expectCommand(lexer.getObj(), "True");
    });

    it("skips several consecutive comment lines", () => {
      const lexer = createLexer("%first\n%second\r%third\n7");

      expect(lexer.getObj()).toBe(7);
    });

    it("returns EOF when the stream contains only an unterminated comment", () => {
      const lexer = createLexer("% a comment without a line-break");

      expect(lexer.getObj()).toBe(EOF);
    });

    it("ignores the remainder of the line after a token", () => {
      const lexer = createLexer("abc% trailing comment");

      expectCommand(lexer.getObj(), "abc");
      expect(lexer.getObj()).toBe(EOF);
    });

    it("skips a comment in between two numbers", () => {
      const lexer = createLexer("1%comment\n2");

      expect(lexer.getObj()).toBe(1);
      expect(lexer.getObj()).toBe(2);
      expect(lexer.getObj()).toBe(EOF);
    });
  });

  describe("numbers", () => {
    it.each([
      ["integer", "123", 123],
      ["negative integer", "-5", -5],
      ["explicitly positive integer", "+7", 7],
      ["real number", "3.14", 3.14],
      ["leading dot", ".5", 0.5],
      ["negative leading dot", "-.5", -0.5],
      ["trailing dot", "42.", 42],
      ["zero", "0", 0],
    ])("parses a %s token", (_, str, expected) => {
      const lexer = createLexer(str);

      expect(lexer.getObj()).toBe(expected);
      expect(lexer.getObj()).toBe(EOF);
    });

    it("parses a sequence of numbers, including sign characters", () => {
      const lexer = createLexer("1 -2 +3 .4");

      expect(lexer.getObj()).toBe(1);
      expect(lexer.getObj()).toBe(-2);
      expect(lexer.getObj()).toBe(3);
      expect(lexer.getObj()).toBe(0.4);
      expect(lexer.getObj()).toBe(EOF);
    });
  });

  describe("strings", () => {
    it("returns the content of a literal string", () => {
      const lexer = createLexer("(hello)");

      expect(lexer.getObj()).toBe("hello");
      expect(lexer.getObj()).toBe(EOF);
    });

    it("returns the empty string for '()'", () => {
      const lexer = createLexer("()");

      expect(lexer.getObj()).toBe("");
    });

    it("keeps balanced nested parentheses in the string", () => {
      const lexer = createLexer("(a(b)c)");

      expect(lexer.getObj()).toBe("a(b)c");
      expect(lexer.getObj()).toBe(EOF);
    });

    it("handles escaped parentheses", () => {
      const lexer = createLexer("(a\\(b)");

      expect(lexer.getObj()).toBe("a(b");
      expect(lexer.getObj()).toBe(EOF);
    });

    it("handles escaped characters", () => {
      const lexer = createLexer("(a\\nb\\tc)");

      expect(lexer.getObj()).toBe("a\nb\tc");
    });

    it("returns the collected text of an unterminated string", () => {
      const lexer = createLexer("(abc");

      expect(lexer.getObj()).toBe("abc");
      expect(lexer.getObj()).toBe(EOF);
    });

    it("reads a string that follows a number", () => {
      const lexer = createLexer("1 (Two)");

      expect(lexer.getObj()).toBe(1);
      expect(lexer.getObj()).toBe("Two");
    });
  });

  describe("names", () => {
    it("returns a Name for a simple name token", () => {
      const lexer = createLexer("/Foo");

      expectName(lexer.getObj(), "Foo");
      expect(lexer.getObj()).toBe(EOF);
    });

    it("returns a Name with an empty value for a lone slash", () => {
      const lexer = createLexer("/");

      expectName(lexer.getObj(), "");
    });

    it("decodes '#' hexadecimal escapes in names", () => {
      const lexer = createLexer("/A#20B#42");

      expectName(lexer.getObj(), "A B!");
    });

    it("reads two adjacent names", () => {
      const lexer = createLexer("/Name/Other");

      expectName(lexer.getObj(), "Name");
      expectName(lexer.getObj(), "Other");
      expect(lexer.getObj()).toBe(EOF);
    });

    it("terminates a name at a following command", () => {
      const lexer = createLexer("/Foo bar");

      expectName(lexer.getObj(), "Foo");
      expectCommand(lexer.getObj(), "bar");
    });

    it("returns a Name for the '/' token directly following a command", () => {
      const lexer = createLexer("q/Foo");

      expectCommand(lexer.getObj(), "q");
      expectName(lexer.getObj(), "Foo");
    });
  });

  describe("array and dictionary punctuation", () => {
    it.each([
      ["[", "["],
      ["]", "]"],
      ["{", "{"],
      ["}", "}"],
      ["<<", "<<"],
      [">>", ">>"],
      [">", ">"],
    ])("returns the %j command for %j", (str, cmd) => {
      const lexer = createLexer(str);

      expectCommand(lexer.getObj(), cmd);
      expect(lexer.getObj()).toBe(EOF);
    });

    it("consumes a single-character delimiter fully", () => {
      const lexer = createLexer("[]");

      expectCommand(lexer.getObj(), "[");
      expectCommand(lexer.getObj(), "]");
      expect(lexer.getObj()).toBe(EOF);
    });

    it("distinguishes '>>' from a lone '>'", () => {
      const lexer = createLexer(">>>");

      expectCommand(lexer.getObj(), ">>");
      expectCommand(lexer.getObj(), ">");
      expect(lexer.getObj()).toBe(EOF);
    });

    it("lexes a complete array of objects", () => {
      const lexer = createLexer("[/Foo 1 (bar)]");

      expectCommand(lexer.getObj(), "[");
      expectName(lexer.getObj(), "Foo");
      expect(lexer.getObj()).toBe(1);
      expect(lexer.getObj()).toBe("bar");
      expectCommand(lexer.getObj(), "]");
      expect(lexer.getObj()).toBe(EOF);
    });

    it("lexes a complete dictionary of objects", () => {
      const lexer = createLexer("<</A 1 /B true>>");

      expectCommand(lexer.getObj(), "<<");
      expectName(lexer.getObj(), "A");
      expect(lexer.getObj()).toBe(1);
      expectName(lexer.getObj(), "B");
      expect(lexer.getObj()).toBe(true);
      expectCommand(lexer.getObj(), ">>");
      expect(lexer.getObj()).toBe(EOF);
    });

    it("uses '>' as a delimiter terminating a preceding command", () => {
      const lexer = createLexer("x>y");

      expectCommand(lexer.getObj(), "x");
      expectCommand(lexer.getObj(), ">");
      expectCommand(lexer.getObj(), "y");
      expect(lexer.getObj()).toBe(EOF);
    });
  });

  describe("hexadecimal strings", () => {
    it("decodes a hexadecimal string", () => {
      const lexer = createLexer("<48656C6C6F>");

      expect(lexer.getObj()).toBe("Hello");
      expect(lexer.getObj()).toBe(EOF);
    });

    it("returns the empty string for '<>'", () => {
      const lexer = createLexer("<>");

      expect(lexer.getObj()).toBe("");
    });

    it("pads an odd number of digits with a trailing zero nibble", () => {
      const lexer = createLexer("<414>");

      expect(lexer.getObj()).toBe("A@");
    });

    it("ignores white-space characters inside a hexadecimal string", () => {
      const lexer = createLexer("<41 42>");

      expect(lexer.getObj()).toBe("AB");
    });

    it("returns the decoded data of an unterminated hexadecimal string", () => {
      const lexer = createLexer("<41");

      expect(lexer.getObj()).toBe("A");
      expect(lexer.getObj()).toBe(EOF);
    });
  });

  describe("illegal characters", () => {
    it("throws a FormatError for a stray ')'", () => {
      const lexer = createLexer(")");

      expect(() => lexer.getObj()).toThrow(FormatError);
      expect(() => lexer.getObj()).toThrow("Illegal character: 41");
    });

    it("consumes the illegal character to avoid an endless loop", () => {
      const lexer = createLexer(")");

      expect(() => lexer.getObj()).toThrow(FormatError);
      expect(lexer.getObj()).toBe(EOF);
    });

    it("continues lexing after an illegal character", () => {
      const lexer = createLexer(")\n456");

      expect(() => lexer.getObj()).toThrow(FormatError);
      expect(lexer.getObj()).toBe(456);
      expect(lexer.getObj()).toBe(EOF);
    });

    it("throws once per illegal character in a try-catch loop", () => {
      const lexer = createLexer(")))");
      let throws = 0;

      while (true) {
        try {
          const obj = lexer.getObj();
          expect(obj).toBe(EOF);
          break;
        } catch (ex) {
          expect(ex).toBeInstanceOf(FormatError);
          throws++;
        }
      }

      expect(throws).toBe(3);
    });
  });

  describe("keyword literals", () => {
    it("returns the boolean true for the 'true' command", () => {
      const lexer = createLexer("true");

      expect(lexer.getObj()).toBe(true);
      expect(lexer.getObj()).toBe(EOF);
    });

    it("returns the boolean false for the 'false' command", () => {
      const lexer = createLexer("false");

      expect(lexer.getObj()).toBe(false);
    });

    it("returns null for the 'null' command", () => {
      const lexer = createLexer("null");

      expect(lexer.getObj()).toBeNull();
    });

    it("does not treat a keyword as a literal when it is only a prefix", () => {
      const lexer = createLexer("trueX");

      expectCommand(lexer.getObj(), "trueX");
    });

    it("does not treat a keyword as a literal inside a larger token", () => {
      const lexer = createLexer("Xnull");

      expectCommand(lexer.getObj(), "Xnull");
    });

    it("returns keyword literals surrounded by whitespace", () => {
      const lexer = createLexer(" true false null ");

      expect(lexer.getObj()).toBe(true);
      expect(lexer.getObj()).toBe(false);
      expect(lexer.getObj()).toBeNull();
      expect(lexer.getObj()).toBe(EOF);
    });
  });

  describe("commands", () => {
    it("returns a Cmd for a simple command token", () => {
      const lexer = createLexer("Tj");

      expectCommand(lexer.getObj(), "Tj");
      expect(lexer.getObj()).toBe(EOF);
    });

    it("keeps digits glued to a command when no knownCommands are given", () => {
      const lexer = createLexer("q1");

      expectCommand(lexer.getObj(), "q1");
      expect(lexer.getObj()).toBe(EOF);
    });

    it("stops at a delimiter that terminates the command", () => {
      const lexer = createLexer("abc(hi)");

      expectCommand(lexer.getObj(), "abc");
      expect(lexer.getObj()).toBe("hi");
      expect(lexer.getObj()).toBe(EOF);
    });

    it("splits a glued operand off when it is a known command prefix", () => {
      const lexer = createLexer("q1", { q: 1 });

      expectCommand(lexer.getObj(), "q");
      expect(lexer.getObj()).toBe(1);
      expect(lexer.getObj()).toBe(EOF);
    });

    it("uses knownCommands prefixes to find the longest known command", () => {
      const lexer = createLexer(
        "trueX",
        { tr: 1, tru: 1, true: 1 },
      );

      expect(lexer.getObj()).toBe(true);
      expectCommand(lexer.getObj(), "X");
      expect(lexer.getObj()).toBe(EOF);
    });

    it("returns false when 'false' is part of the knownCommands table", () => {
      const lexer = createLexer("false ", {
        f: 1,
        fa: 1,
        fal: 1,
        fals: 1,
        false: 1,
      });

      expect(lexer.getObj()).toBe(false);
      expect(lexer.getObj()).toBe(EOF);
    });

    it("accepts a command token of the maximum allowed length", () => {
      const lexer = createLexer("a".repeat(128));

      const obj = lexer.getObj();

      expectCommand(obj, "a".repeat(128));
      expect(obj.cmd).toHaveLength(128);
      expect(lexer.getObj()).toBe(EOF);
    });

    it("throws a FormatError for an over-long command token", () => {
      const lexer = createLexer("a".repeat(129));

      expect(() => lexer.getObj()).toThrow(FormatError);
