const SOI = [0xff, 0xd8];
const EOI = [0xff, 0xd9];

function u16(value) {
  return [(value >> 8) & 0xff, value & 0xff];
}

function flatten(parts) {
  const bytes = [];
  for (const part of parts) {
    for (const byte of part) {
      bytes.push(byte & 0xff);
    }
  }
  return Uint8Array.from(bytes);
}

/**
 * Builds a JPEG marker segment: 0xFF, marker, 16-bit length (including the
 * length bytes themselves), then the payload.
 */
function segment(marker, payload) {
  return [0xff, marker, ...u16(payload.length + 2), ...payload];
}

function jpeg(...parts) {
  return flatten([SOI, ...parts, EOI]);
}

function quantizationTableValues(value = 1) {
  return new Array(64).fill(value);
}

function dqt8(tableId, values = quantizationTableValues()) {
  return segment(0xdb, [tableId & 0x0f, ...values]);
}

function dqt16(tableId, values = quantizationTableValues()) {
  const payload = [0x10 | (tableId & 0x0f)];
  for (const value of values) {
    payload.push(...u16(value));
  }
  return segment(0xdb, payload);
}

function sof(marker, { height, width, precision = 8, components }) {
  const payload = [precision, ...u16(height), ...u16(width), components.length];
  for (const { id, h = 1, v = 1, quantizationId = 0 } of components) {
    payload.push(id, ((h << 4) | v) & 0xff, quantizationId);
  }
  return segment(marker, payload);
}

function dht(markerClass, tableId, counts, values) {
  const codeLengths = new Array(16).fill(0);
  for (let i = 0; i < counts.length; i++) {
    codeLengths[i] = counts[i];
  }
  return segment(0xc4, [
    ((markerClass << 4) | tableId) & 0xff,
    ...codeLengths,
    ...values,
  ]);
}

function dri(interval) {
  return segment(0xdd, u16(interval));
}

function sos(components, entropy = [], options = {}) {
  const {
    spectralStart = 0,
    spectralEnd = 63,
    successiveHigh = 0,
    successiveLow = 0,
