import { JpegError, JpegImage } from "../../../src/core/jpg.js";

const SOI = [0xff, 0xd8];
const EOI = [0xff, 0xd9];

function u16(value) {
  return [(value >> 8) & 0xff, value & 0xff];
}

function flatten(parts) {
  const bytes = [];
  for (const part of parts) {
    for (const byte of part) {
      bytes.push(byte & 0xff);
    }
  }
  return Uint8Array.from(bytes);
}

/**
