  });
}

// A DC table with a single one bit code mapping to the category "1", and an AC
// table with a single one bit code mapping to EOB (0x00).
function singleCodeHuffmanTables() {
  return [dht(0, 0, [1], [1]), dht(1, 0, [1], [0x00])];
}

// "010": DC category 1 (bit 0), positive sign (bit 1), AC EOB (bit 0).
const SINGLE_BLOCK_ENTROPY = [0x40];

