  console.warn = message => warnings.push(String(message));
  try {
    return { result: callback(), warnings };
  } finally {
    console.warn = originalWarn;
  }
}

function parse(input, options) {
  const image = new JpegImage();
  const result = image.parse(input, options);
  return { image, result };
}

describe("JpegImage.parse", () => {
  it("throws a JpegError when the SOI marker is missing", () => {
    const data = flatten([
      [0xff, 0xd9],
      [0xff, 0xd8],
    ]);

    expect(() => new JpegImage().parse(data)).toThrow(JpegError);
    expect(() => new JpegImage().parse(data)).toThrow("SOI not found");
  });

  it("throws a JpegError when no frame data is present", () => {
    expect(() => new JpegImage().parse(flatten([SOI, EOI]))).toThrow(
      "JpegImage.parse - no frame data found."
    );
  });

  it("parses a baseline frame and exposes the image geometry", () => {
    const data = jpeg(
      dqt8(0),
      sof(0xffc0, {
        height: 16,
        width: 16,
        components: [
          { id: 1, h: 2, v: 2, quantizationId: 0 },
          { id: 2, h: 1, v: 1, quantizationId: 0 },
          { id: 3, h: 1, v: 1, quantizationId: 0 },
        ],
      })
    );

    const { image, result } = parse(data);

    expect(result).toBeUndefined();
    expect(image.width).toBe(16);
    expect(image.height).toBe(16);
    expect(image.numComponents).toBe(3);
    expect(image.jfif).toBeNull();
    expect(image.adobe).toBeNull();

    const [luma, chromaBlue, chromaRed] = image.components;
    expect(luma.scaleX).toBe(1);
    expect(luma.scaleY).toBe(1);
    expect(luma.blocksPerLine).toBe(2);
    expect(luma.blocksPerColumn).toBe(2);

    for (const chroma of [chromaBlue, chromaRed]) {
      expect(chroma.scaleX).toBe(0.5);
      expect(chroma.scaleY).toBe(0.5);
      expect(chroma.blocksPerLine).toBe(1);
      expect(chroma.blocksPerColumn).toBe(1);
    }

    // Zeroed DCT coefficients decode to a neutral gray (level shifted) image.
    for (const component of image.components) {
      expect(component.output).toBeInstanceOf(Int16Array);
      expect(component.output.length).toBeGreaterThan(0);
      const firstBlock = Array.from(component.output.subarray(0, 64));
      expect(new Set(firstBlock).size).toBe(1);
      expect(firstBlock[0]).toBe(128);
    }
  });

  it("supports extended (SOF1) and progressive (SOF2) frames", () => {
    for (const marker of [0xffc1, 0xffc2]) {
      const data = jpeg(
        dqt8(0),
        sof(marker, {
          height: 8,
          width: 8,
          components: [{ id: 1, h: 1, v: 1 }],
        })
      );

      const { image } = parse(data);
      expect(image.width).toBe(8);
      expect(image.height).toBe(8);
      expect(image.numComponents).toBe(1);
    }
  });

  it("throws when more than one frame is defined", () => {
    const frame = grayscaleFrame();
    const data = jpeg(dqt8(0), frame, frame);

    expect(() => new JpegImage().parse(data)).toThrow(
      "Only single frame JPEGs supported"
    );
  });

  it("throws when a component references a missing quantization table", () => {
    const data = jpeg(grayscaleFrame({ quantizationId: 1 }));

    expect(() => new JpegImage().parse(data)).toThrow(
      "missing required Quantization Table."
    );
  });

  it("applies quantization tables defined after the frame header", () => {
    const data = jpeg(grayscaleFrame(), dqt8(0));

    const { image } = parse(data);
    expect(image.width).toBe(8);
    expect(image.height).toBe(8);
    expect(image.components[0].output[0]).toBe(128);
  });

  it("parses 16 bit quantization tables", () => {
    const data = jpeg(dqt16(0, quantizationTableValues(1)), grayscaleFrame());

    const { image } = parse(data);
    expect(image.components[0].output[0]).toBe(128);
  });

  it("throws on an invalid DQT table specification", () => {
    const data = jpeg(segment(0xdb, [0x20, ...quantizationTableValues()]));

    expect(() => new JpegImage().parse(data)).toThrow(
      "DQT - invalid table spec"
    );
  });

  it("parses the JFIF APP0 marker, including the thumbnail", () => {
    const thumbData = [1, 2, 3, 4, 5, 6];
    const data = jpeg(
      jfifApp0({
        major: 2,
        minor: 1,
        densityUnits: 1,
        xDensity: 300,
        yDensity: 150,
        thumbWidth: 2,
        thumbHeight: 1,
        thumbData,
      }),
      dqt8(0),
      grayscaleFrame()
    );

    const { image } = parse(data);

    expect(image.jfif).toEqual({
      version: { major: 2, minor: 1 },
      densityUnits: 1,
      xDensity: 300,
      yDensity: 150,
      thumbWidth: 2,
      thumbHeight: 1,
      thumbData: expect.any(Uint8Array),
    });
    expect(Array.from(image.jfif.thumbData)).toEqual(thumbData);
  });

  it("ignores an APP0 marker which is not JFIF", () => {
    const data = jpeg(
      segment(0xe0, [0x4a, 0x46, 0x58, 0x58, 0x00, 1, 2, 3]),
      dqt8(0),
