import {
  XMLParserBase,
  XMLParserErrorCode,
} from "../../../src/core/xml_parser.js";

/**
 * Test double that records every callback invoked by XMLParserBase.parseXml.
 */
class RecordingXMLParser extends XMLParserBase {
  constructor() {
    super();
    this.events = [];
    this.resolvedEntities = [];
  }

  onResolveEntity(name) {
    this.resolvedEntities.push(name);
    return super.onResolveEntity(name);
  }

  onText(text) {
    this.events.push({ type: "text", text });
  }

  onCdata(text) {
    this.events.push({ type: "cdata", text });
  }

  onComment(text) {
    this.events.push({ type: "comment", text });
  }

  onPi(name, value) {
    this.events.push({ type: "pi", name, value });
  }

  onDoctype(doctypeContent) {
    this.events.push({ type: "doctype", doctypeContent });
  }

  onBeginElement(name, attributes, isEmpty) {
    this.events.push({ type: "begin", name, attributes, isEmpty });
  }

  onEndElement(name) {
    this.events.push({ type: "end", name });
  }

  onError(code) {
    this.events.push({ type: "error", code });
  }
}

function parse(input) {
  const parser = new RecordingXMLParser();
  const result = parser.parseXml(input);
  return { parser, events: parser.events, result };
}

describe("parseXml", () => {
  describe("text content", () => {
    it("does nothing for an empty document", () => {
      const { events, result } = parse("");

      expect(events).toEqual([]);
      expect(result).toBeUndefined();
    });

    it("reports plain text without any markup", () => {
      const { events } = parse("hello world");

      expect(events).toEqual([{ type: "text", text: "hello world" }]);
    });

    it("reports each text run separately around elements", () => {
      const { events } = parse("before<a/>after");

      expect(events).toEqual([
        { type: "text", text: "before" },
        { type: "begin", name: "a", attributes: [], isEmpty: true },
        { type: "text", text: "after" },
      ]);
    });

    it("preserves whitespace-only text with the base parser", () => {
      const { events } = parse("<a>  \n\t</a>");

      expect(events).toEqual([
        { type: "begin", name: "a", attributes: [], isEmpty: false },
        { type: "text", text: "  \n\t" },
        { type: "end", name: "a" },
      ]);
    });
  });

