      const { events } = parse('<a title="Tom &amp; Jerry &#x21;"/>');

      expect(events).toEqual([
        {
          type: "begin",
          name: "a",
          attributes: [{ name: "title", value: "Tom & Jerry !" }],
          isEmpty: true,
        },
      ]);
    });

    it("delegates unknown entities to onResolveEntity and keeps the default text", () => {
      const { events, parser } = parse("x&unknown;y");

      expect(events).toEqual([{ type: "text", text: "x&unknown;y" }]);
      expect(parser.resolvedEntities).toEqual(["unknown"]);
    });

    it("uses the value returned by an overridden onResolveEntity", () => {
      class EntityMappingParser extends RecordingXMLParser {
        onResolveEntity(name) {
          this.resolvedEntities.push(name);
          return name === "nbsp" ? "\u00a0" : "!";
        }
      }

      const parser = new EntityMappingParser();
      parser.parseXml("a&nbsp;b&copy;c");

      expect(parser.events).toEqual([{ type: "text", text: "a\u00a0b!c" }]);
      expect(parser.resolvedEntities).toEqual(["nbsp", "copy"]);
    });

    it("does not resolve entities inside CDATA sections", () => {
      const { events } = parse("<![CDATA[a&amp;b]]>");

      expect(events).toEqual([{ type: "cdata", text: "a&amp;b" }]);
    });
  });

  describe("elements", () => {
