      const { events } = parse("<root>text</root>");

      expect(events).toEqual([
        { type: "begin", name: "root", attributes: [], isEmpty: false },
        { type: "text", text: "text" },
        { type: "end", name: "root" },
      ]);
    });

    it("reports self-closing elements as empty", () => {
      const { events } = parse("<br/>");

      expect(events).toEqual([
        { type: "begin", name: "br", attributes: [], isEmpty: true },
      ]);
    });

    it("parses multiple attributes with single and double quotes", () => {
      const { events } = parse("<a one=\"1\" two='2'/>");

