import { Type1Parser } from "../../../src/core/type1_parser.js";
import { Stream } from "../../../src/core/stream.js";

function textBytes(text) {
  return Array.from(text, ch => ch.charCodeAt(0));
}

function toUint8Array(values) {
  return Uint8Array.from(values);
}

function pushUint(target, value, byteCount) {
  for (let i = byteCount - 1; i >= 0; i--) {
    target.push((value >>> (i * 8)) & 0xff);
  }
}

/**
 * Builds the binary block expected after "StartData": a CIDMap (optional
 * SubrMap) followed by the raw charstring/subr byte data.
 */
function buildBinary({
  glyphs,
  fdBytes = 0,
  gdBytes = 2,
  fdIndexes = null,
  subrs = null,
  sdBytes = 2,
  glyphOffsets: glyphOffsetsOverride = null,
  subrOffsets: subrOffsetsOverride = null,
}) {
  const cidCount = glyphs.length;
  const cidEntrySize = fdBytes + gdBytes;
  const mapSize = (cidCount + 1) * cidEntrySize;
  const subrMapSize = subrs ? (subrs.length + 1) * sdBytes : 0;
  let offset = mapSize + subrMapSize;

  const subrOffsets = [];
  const subrBytes = [];
  if (subrs) {
    for (const subr of subrs) {
      subrOffsets.push(offset);
      if (subr) {
        subrBytes.push(...subr);
        offset += subr.length;
      }
    }
    subrOffsets.push(offset);
  }

  const glyphOffsets = [];
  const glyphBytes = [];
  for (const glyph of glyphs) {
    glyphOffsets.push(offset);
    if (glyph) {
      glyphBytes.push(...glyph);
      offset += glyph.length;
    }
  }
  glyphOffsets.push(offset);

  const bytes = [];
  for (let cid = 0; cid <= cidCount; cid++) {
    pushUint(bytes, fdIndexes?.[cid] ?? 0, fdBytes);
    const glyphOffset = (glyphOffsetsOverride ?? glyphOffsets)[cid];
    pushUint(bytes, glyphOffset, gdBytes);
  }
  if (subrs) {
    for (const subrOffset of subrOffsetsOverride ?? subrOffsets) {
      pushUint(bytes, subrOffset, sdBytes);
    }
  }
  bytes.push(...subrBytes, ...glyphBytes);
  return toUint8Array(bytes);
}

function toHexString(bytes, lineBreakEvery = 0) {
  let hex = "";
  for (let i = 0; i < bytes.length; i++) {
    hex += bytes[i].toString(16).padStart(2, "0");
    if (lineBreakEvery && (i + 1) % lineBreakEvery === 0) {
      hex += "\n";
    }
  }
  return hex;
}

function makeParser({ header, binary, dataLength, dataType = "Binary", tail = "" }) {
  const lengthToken = dataLength ?? binary.length;
  const head = textBytes(
    `${header} ( ${dataType} ) ${lengthToken} StartData ${tail}`
  );
  const bytes = new Uint8Array(head.length + binary.length + tail.length);
  bytes.set(head, 0);
  bytes.set(binary, head.length);
  return new Type1Parser(new Stream(bytes));
}

const DEFAULT_HEADER =
