import { Type1Parser } from "../../../src/core/type1_parser.js";
import { Stream } from "../../../src/core/stream.js";

function textBytes(text) {
  return Array.from(text, ch => ch.charCodeAt(0));
}

function toUint8Array(values) {
  return Uint8Array.from(values);
}

function pushUint(target, value, byteCount) {
  for (let i = byteCount - 1; i >= 0; i--) {
    target.push((value >>> (i * 8)) & 0xff);
  }
}

/**
 * Builds the binary block expected after "StartData": a CIDMap (optional
 * SubrMap) followed by the raw charstring/subr byte data.
 */
function buildBinary({
  glyphs,
  fdBytes = 0,
  gdBytes = 2,
  fdIndexes = null,
  subrs = null,
  sdBytes = 2,
  glyphOffsets: glyphOffsetsOverride = null,
  subrOffsets: subrOffsetsOverride = null,
  mapOffset = 0,
}) {
  const cidCount = glyphs.length;
  const cidEntrySize = fdBytes + gdBytes;
  const mapSize = (cidCount + 1) * cidEntrySize;
  const subrMapSize = subrs ? (subrs.length + 1) * sdBytes : 0;
  let offset = mapOffset + mapSize + subrMapSize;

  const subrOffsets = [];
  const subrBytes = [];
  if (subrs) {
    for (const subr of subrs) {
      subrOffsets.push(offset);
      if (subr) {
        subrBytes.push(...subr);
        offset += subr.length;
      }
    }
    subrOffsets.push(offset);
  }

  const glyphOffsets = [];
  const glyphBytes = [];
  for (const glyph of glyphs) {
    glyphOffsets.push(offset);
    if (glyph) {
      glyphBytes.push(...glyph);
      offset += glyph.length;
    }
  }
