import { CanvasGraphics } from "../../../src/display/canvas.js";

// ---------------------------------------------------------------------------
// Minimal 2D canvas / DOM mocks.
//
// `beginGroup` only relies on a small, well defined subset of the canvas API,
// so a fake context is both enough and much easier to make assertions on than
// a real canvas implementation.
// ---------------------------------------------------------------------------

class MockMatrix {
  constructor(values = [1, 0, 0, 1, 0, 0]) {
    [this.a, this.b, this.c, this.d, this.e, this.f] = values;
  }

  multiply({ a, b, c, d, e, f }) {
    return new MockMatrix([
      this.a * a + this.c * b,
      this.b * a + this.d * b,
      this.a * c + this.c * d,
      this.b * c + this.d * d,
      this.a * e + this.c * f + this.e,
      this.b * e + this.d * f + this.f,
    ]);
  }

  toArray() {
    return [this.a, this.b, this.c, this.d, this.e, this.f];
  }
}

class MockPath2D {
  constructor() {
    this.rectCalls = [];
    this.addPathCalls = [];
  }

  rect(...args) {
    this.rectCalls.push(args);
  }

  addPath(path, matrix) {
    this.addPathCalls.push([path, matrix]);
  }
}

class MockDOMMatrix {
  constructor(values) {
    this.values = Array.isArray(values) ? values.slice() : [];
  }
}

class MockContext {
  constructor(width, height) {
    this.canvas = { width, height };
    this.calls = [];
    this.stack = [];
    this.matrix = new MockMatrix();
    this.lineDash = [];

    this.globalAlpha = 1;
    this.globalCompositeOperation = "source-over";
    this.filter = "none";
    this.fillStyle = "#000000";
    this.strokeStyle = "#000000";
    this.lineWidth = 1;
    this.lineCap = "butt";
    this.lineJoin = "miter";
    this.miterLimit = 10;
    this.font = "10px sans-serif";
  }

  #snapshot() {
    return {
      matrix: this.matrix,
      globalAlpha: this.globalAlpha,
      globalCompositeOperation: this.globalCompositeOperation,
      filter: this.filter,
      fillStyle: this.fillStyle,
      strokeStyle: this.strokeStyle,
      lineWidth: this.lineWidth,
      lineCap: this.lineCap,
      lineJoin: this.lineJoin,
      miterLimit: this.miterLimit,
      font: this.font,
      lineDash: this.lineDash,
    };
  }

  save() {
    this.calls.push(["save"]);
    this.stack.push(this.#snapshot());
  }

  restore() {
    this.calls.push(["restore"]);
    const state = this.stack.pop();
    if (state) {
      Object.assign(this, state);
    }
  }

  translate(x, y) {
    this.calls.push(["translate", x, y]);
    this.matrix = this.matrix.multiply(new MockMatrix([1, 0, 0, 1, x, y]));
  }

  transform(a, b, c, d, e, f) {
    this.calls.push(["transform", a, b, c, d, e, f]);
    this.matrix = this.matrix.multiply(new MockMatrix([a, b, c, d, e, f]));
  }

  setTransform(a, b, c, d, e, f) {
    this.calls.push(["setTransform", a, b, c, d, e, f]);
    this.matrix = new MockMatrix([a, b, c, d, e, f]);
  }

  clip(path) {
    this.calls.push(["clip", path]);
  }

  drawImage(...args) {
    this.calls.push(["drawImage", ...args]);
  }

  getTransform() {
    return this.matrix;
  }

  getLineDash() {
    return this.lineDash;
  }

  setLineDash(lineDash) {
    this.calls.push(["setLineDash", lineDash]);
    this.lineDash = lineDash;
  }

  _removeMirroring() {
    this.calls.push(["_removeMirroring"]);
  }
}

class MockCanvasFactory {
  constructor() {
    this.created = [];
    this.destroyed = [];
  }

  create(width, height) {
    const context = new MockContext(width, height);
    const entry = { canvas: context.canvas, context, width, height };
    this.created.push(entry);
    return entry;
  }

  destroy(entry) {
    this.destroyed.push(entry);
  }
}

// `beginGroup` uses these as globals (as it would in a browser).
globalThis.Path2D = MockPath2D;
globalThis.DOMMatrix = MockDOMMatrix;

// ---------------------------------------------------------------------------
// Helpers.
// ---------------------------------------------------------------------------

function callsNamed(ctx, name) {
  return ctx.calls.filter(call => call[0] === name);
}

function createGraphics({
  ctx = new MockContext(100, 100),
  factory = new MockCanvasFactory(),
  filterFactory = { addFilter: () => "none" },
  dependencyTracker = null,
} = {}) {
  const graphics = new CanvasGraphics(
    ctx,
    {},
    {},
    factory,
    filterFactory,
    { optionalContentConfig: null },
    null,
    null,
    dependencyTracker
  );
  return { graphics, ctx, factory, filterFactory };
}

function makeGroup(overrides = {}) {
  return {
    needsIsolation: false,
    isolated: false,
    hasSoftMask: false,
    knockout: false,
    isGray: false,
    bbox: null,
    matrix: null,
    smask: null,
    ...overrides,
  };
}

describe("CanvasGraphics.beginGroup", () => {
  describe("content visibility", () => {
    it("does nothing at all when content is not visible", () => {
      const { graphics, ctx, factory } = createGraphics();
      graphics.contentVisible = false;

      graphics.beginGroup(0, makeGroup({ bbox: [0, 0, 10, 10] }));

      expect(graphics.groupLevel).toBe(0);
      expect(graphics.groupStack).toEqual([]);
      expect(graphics.stateStack).toEqual([]);
      expect(ctx.calls).toEqual([]);
      expect(factory.created).toEqual([]);
      expect(graphics.ctx).toBe(ctx);
    });
  });

  describe("direct (no intermediate canvas) path", () => {
    it("saves, pushes a null sentinel and increments the group level", () => {
      const { graphics, ctx, factory } = createGraphics();

      graphics.beginGroup(0, makeGroup());

