import { CanvasGraphics } from "../../../src/display/canvas.js";

// ---------------------------------------------------------------------------
// Minimal 2D canvas / DOM mocks.
//
// `beginGroup` only relies on a small, well defined subset of the canvas API,
// so a fake context is both enough and much easier to make assertions on than
// a real canvas implementation.
// ---------------------------------------------------------------------------

class MockMatrix {
  constructor(values = [1, 0, 0, 1, 0, 0]) {
    [this.a, this.b, this.c, this.d, this.e, this.f] = values;
  }

  multiply({ a, b, c, d, e, f }) {
    return new MockMatrix([
      this.a * a + this.c * b,
      this.b * a + this.d * b,
      this.a * c + this.c * d,
      this.b * c + this.d * d,
      this.a * e + this.c * f + this.e,
      this.b * e + this.d * f + this.f,
    ]);
  }

  toArray() {
    return [this.a, this.b, this.c, this.d, this.e, this.f];
  }
}

class MockPath2D {
  constructor() {
    this.rectCalls = [];
    this.addPathCalls = [];
  }

  rect(...args) {
    this.rectCalls.push(args);
  }

  addPath(path, matrix) {
    this.addPathCalls.push([path, matrix]);
  }
}

class MockDOMMatrix {
  constructor(values) {
    this.values = Array.isArray(values) ? values.slice() : [];
  }
}

class MockContext {
  constructor(width, height) {
    this.canvas = { width, height };
    this.calls = [];
    this.stack = [];
    this.matrix = new MockMatrix();
    this.lineDash = [];

    this.globalAlpha = 1;
    this.globalCompositeOperation = "source-over";
    this.filter = "none";
    this.fillStyle = "#000000";
    this.strokeStyle = "#000000";
    this.lineWidth = 1;
    this.lineCap = "butt";
    this.lineJoin = "miter";
    this.miterLimit = 10;
    this.font = "10px sans-serif";
  }

  #snapshot() {
    return {
      matrix: this.matrix,
      globalAlpha: this.globalAlpha,
      globalCompositeOperation: this.globalCompositeOperation,
      filter: this.filter,
      fillStyle: this.fillStyle,
      strokeStyle: this.strokeStyle,
      lineWidth: this.lineWidth,
      lineCap: this.lineCap,
      lineJoin: this.lineJoin,
      miterLimit: this.miterLimit,
      font: this.font,
      lineDash: this.lineDash,
    };
  }

  save() {
    this.calls.push(["save"]);
    this.stack.push(this.#snapshot());
  }

  restore() {
    this.calls.push(["restore"]);
    const state = this.stack.pop();
    if (state) {
      Object.assign(this, state);
    }
  }

  translate(x, y) {
    this.calls.push(["translate", x, y]);
    this.matrix = this.matrix.multiply(new MockMatrix([1, 0, 0, 1, x, y]));
  }

  transform(a, b, c, d, e, f) {
    this.calls.push(["transform", a, b, c, d, e, f]);
    this.matrix = this.matrix.multiply(new MockMatrix([a, b, c, d, e, f]));
  }

  setTransform(a, b, c, d, e, f) {
    this.calls.push(["setTransform", a, b, c, d, e, f]);
    this.matrix = new MockMatrix([a, b, c, d, e, f]);
  }

  clip(path) {
    this.calls.push(["clip", path]);
  }

  drawImage(...args) {
    this.calls.push(["drawImage", ...args]);
  }

  getTransform() {
    return this.matrix;
  }

  getLineDash() {
    return this.lineDash;
  }

  setLineDash(lineDash) {
    this.calls.push(["setLineDash", lineDash]);
    this.lineDash = lineDash;
  }

  _removeMirroring() {
    this.calls.push(["_removeMirroring"]);
  }
}

class MockCanvasFactory {
  constructor() {
    this.created = [];
    this.destroyed = [];
  }

  create(width, height) {
    const context = new MockContext(width, height);
    const entry = { canvas: context.canvas, context, width, height };
    this.created.push(entry);
    return entry;
  }

  destroy(entry) {
    this.destroyed.push(entry);
  }
}

// `beginGroup` uses these as globals (as it would in a browser). The
// originals (if any) are restored once this suite is done.
const originalPath2D = globalThis.Path2D;
const originalDOMMatrix = globalThis.DOMMatrix;

const originalDOMMatrix = globalThis.DOMMatrix;

beforeAll(() => {
  globalThis.Path2D = MockPath2D;
  globalThis.DOMMatrix = MockDOMMatrix;
});

afterAll(() => {
  if (originalPath2D === undefined) {
    delete globalThis.Path2D;
  } else {
    globalThis.Path2D = originalPath2D;
  }
  if (originalDOMMatrix === undefined) {
    delete globalThis.DOMMatrix;
  } else {
    globalThis.DOMMatrix = originalDOMMatrix;
  }
});

// ---------------------------------------------------------------------------
// Helpers.
// ---------------------------------------------------------------------------

function callsNamed(ctx, name) {
  return ctx.calls.filter(call => call[0] === name);
}

function createGraphics({
  ctx = new MockContext(100, 100),
  factory = new MockCanvasFactory(),
  filterFactory = { addFilter: () => "none" },
  dependencyTracker = null,
} = {}) {
  const graphics = new CanvasGraphics(
    ctx,
    {},
    {},
    factory,
    filterFactory,
    { optionalContentConfig: null },
    null,
    null,
    dependencyTracker
  );
  return { graphics, ctx, factory, filterFactory };
}

function makeGroup(overrides = {}) {
  return {
    needsIsolation: false,
    isolated: false,
    hasSoftMask: false,
    knockout: false,
    isGray: false,
    bbox: null,
    matrix: null,
    smask: null,
    ...overrides,
  };
}

describe("CanvasGraphics.beginGroup", () => {
  describe("content visibility", () => {
    it("does nothing at all when content is not visible", () => {
      const { graphics, ctx, factory } = createGraphics();
      graphics.contentVisible = false;

      graphics.beginGroup(0, makeGroup({ bbox: [0, 0, 10, 10] }));

      expect(graphics.groupLevel).toBe(0);
      expect(graphics.groupStack).toEqual([]);
      expect(graphics.stateStack).toEqual([]);
      expect(ctx.calls).toEqual([]);
      expect(factory.created).toEqual([]);
      expect(graphics.ctx).toBe(ctx);
    });
  });

  describe("direct (no intermediate canvas) path", () => {
    it("saves, pushes a null sentinel and increments the group level", () => {
      const { graphics, ctx, factory } = createGraphics();

      graphics.beginGroup(0, makeGroup());

      expect(graphics.groupLevel).toBe(1);
      expect(graphics.groupStack).toEqual([null]);
      expect(graphics.stateStack).toHaveLength(1);
      expect(factory.created).toEqual([]);
      expect(graphics.ctx).toBe(ctx);
      expect(ctx.calls).toEqual([["save"]]);
      expect(callsNamed(ctx, "setTransform")).toHaveLength(0);
      expect(callsNamed(ctx, "translate")).toHaveLength(0);
    });

    it("clips the group bbox directly onto the parent context", () => {
      const { graphics, ctx, factory } = createGraphics();

      graphics.beginGroup(0, makeGroup({ bbox: [10, 20, 60, 80] }));

      const clips = callsNamed(ctx, "clip");
      expect(clips).toHaveLength(1);
      const path = clips[0][1];
      expect(path).toBeInstanceOf(MockPath2D);
      expect(path.rectCalls).toEqual([[10, 20, 50, 60]]);
      expect(path.addPathCalls).toEqual([]);

      expect(graphics.groupStack).toEqual([null]);
      expect(factory.created).toEqual([]);
    });

    it("applies the group matrix to the bbox clip", () => {
      const { graphics, ctx } = createGraphics();

      graphics.beginGroup(
        0,
        makeGroup({ bbox: [10, 20, 60, 80], matrix: [2, 0, 0, 3, 5, 7] })
      );

      const clips = callsNamed(ctx, "clip");
      expect(clips).toHaveLength(1);
      const path = clips[0][1];
      expect(path.rectCalls).toEqual([]);
      expect(path.addPathCalls).toHaveLength(1);
      const [clipPath, matrix] = path.addPathCalls[0];
      // The original rectangle path is embedded, transformed, into a new path.
      expect(clipPath).toBeInstanceOf(MockPath2D);
      expect(clipPath).not.toBe(path);
      expect(clipPath.rectCalls).toEqual([[10, 20, 50, 60]]);
      expect(matrix).toBeInstanceOf(MockDOMMatrix);
      expect(matrix.values).toEqual([2, 0, 0, 3, 5, 7]);

      // The matrix only affects the clip path, not the parent context.
      expect(callsNamed(ctx, "transform")).toHaveLength(0);
      expect(graphics.groupStack).toEqual([null]);
    });

    it("uses the direct path for a non-isolated group needing isolation without a soft mask", () => {
      const { graphics, factory } = createGraphics();

      graphics.beginGroup(
        0,
        makeGroup({ needsIsolation: true, isolated: false, hasSoftMask: false })
      );

      expect(graphics.groupStack).toEqual([null]);
      expect(graphics.groupLevel).toBe(1);
      expect(factory.created).toEqual([]);
    });

    it("supports several direct-path groups stacked on the same context", () => {
      const { graphics, ctx, factory } = createGraphics();

      graphics.beginGroup(0, makeGroup());
      graphics.beginGroup(1, makeGroup());

      expect(graphics.groupStack).toEqual([null, null]);
      expect(graphics.groupLevel).toBe(2);
      expect(graphics.stateStack).toHaveLength(2);
      expect(factory.created).toEqual([]);
      expect(callsNamed(ctx, "save")).toHaveLength(2);
    });

    describe("falls back to an intermediate canvas when", () => {
      const cases = [
        [
          "the group is isolated (needsIsolation)",
          { needsIsolation: true, isolated: true },
          {},
        ],
        [
          "the non-isolated group has a soft mask",
          { needsIsolation: true, isolated: false, hasSoftMask: true },
          {},
        ],
        ["the group is a knockout group", { knockout: true }, {}],
        ["the group is gray", { isGray: true }, {}],
        ["the parent context is translucent", {}, { globalAlpha: 0.5 }],
        [
          "the parent context has a non-default blend mode",
          {},
          { globalCompositeOperation: "multiply" },
        ],
      ];

      for (const [label, groupOverrides, ctxOverrides] of cases) {
        it(label, () => {
          const ctx = new MockContext(100, 100);
          Object.assign(ctx, ctxOverrides);
          const { graphics, factory } = createGraphics({ ctx });

          graphics.beginGroup(0, makeGroup(groupOverrides));

          expect(graphics.groupLevel).toBe(1);
          expect(factory.created.length).toBeGreaterThanOrEqual(1);
          expect(graphics.groupStack).toHaveLength(1);
          expect(graphics.groupStack[0]).not.toBeNull();
          expect(graphics.groupStack[0]).toBe(ctx);
          expect(graphics.ctx).not.toBe(ctx);
        });
      }
    });
  });

  describe("intermediate canvas geometry", () => {
    it("sizes the canvas from the bbox and translates both contexts", () => {
      const { graphics, ctx, factory } = createGraphics();

      graphics.beginGroup(
        0,
        makeGroup({
          needsIsolation: true,
          isolated: true,
          bbox: [10, 20, 60, 80],
        })
      );

      expect(factory.created).toHaveLength(1);
      const entry = factory.created[0];
      expect(entry.width).toBe(50);
      expect(entry.height).toBe(60);
      expect(entry.canvas.width).toBe(50);
      expect(entry.canvas.height).toBe(60);

      // The new group context renders into the scratch canvas, translated by
      // the bbox offset and with the current transform applied.
      const groupCtx = entry.context;
      expect(graphics.ctx).toBe(groupCtx);
      expect(callsNamed(groupCtx, "translate")).toEqual([
        ["translate", -10, -20],
      ]);
      expect(callsNamed(groupCtx, "transform")).toEqual([
        ["transform", 1, 0, 0, 1, 0, 0],
      ]);
      expect(groupCtx.matrix.toArray()).toEqual([1, 0, 0, 1, -10, -20]);

      // The bbox is also clipped on the group context.
      const groupClips = callsNamed(groupCtx, "clip");
      expect(groupClips).toHaveLength(1);
      expect(groupClips[0][1].rectCalls).toEqual([[10, 20, 50, 60]]);

      // The parent context is positioned at the group offset so that the
      // group can be composited back at endGroup time.
      expect(callsNamed(ctx, "setTransform")).toEqual([
        ["setTransform", 1, 0, 0, 1, 0, 0],
      ]);
      expect(callsNamed(ctx, "translate")).toEqual([["translate", 10, 20]]);
      // One save from CanvasGraphics.save, one while positioning the parent.
      expect(callsNamed(ctx, "save")).toHaveLength(2);
      expect(ctx.matrix.toArray()).toEqual([1, 0, 0, 1, 10, 20]);

      expect(Array.from(graphics.current.clipBox)).toEqual([0, 0, 50, 60]);
      expect(graphics.groupStack).toEqual([ctx]);
      expect(graphics.groupLevel).toBe(1);
    });

    it("uses the whole current canvas when there is no bbox", () => {
      const { graphics, factory } = createGraphics({
        ctx: new MockContext(120, 90),
      });

      graphics.beginGroup(
        0,
        makeGroup({ needsIsolation: true, isolated: true })
      );

      expect(factory.created).toHaveLength(1);
      expect(factory.created[0].width).toBe(120);
      expect(factory.created[0].height).toBe(90);
      expect(callsNamed(factory.created[0].context, "clip")).toHaveLength(0);
      expect(Array.from(graphics.current.clipBox)).toEqual([0, 0, 120, 90]);
    });

    it("floors offsets and ceils dimensions", () => {
      const { graphics, factory } = createGraphics();

      graphics.beginGroup(
        0,
        makeGroup({
          needsIsolation: true,
          isolated: true,
          bbox: [10.5, 20.2, 60.7, 80.9],
        })
      );

