      expect(factory.created).toHaveLength(1);
      expect(factory.created[0].width).toBe(51);
      expect(factory.created[0].height).toBe(61);
      expect(callsNamed(factory.created[0].context, "translate")).toEqual([
        ["translate", -10, -20],

      ["translate", -10, -20],
    ]);
  });

  it("clamps the bbox to the canvas", () => {
    const { graphics, factory } = createGraphics();

    graphics.beginGroup(
      0,
      makeGroup({
        needsIsolation: true,
        isolated: true,
        bbox: [0, 0, 300, 50],
      })
    );

    expect(factory.created[0].width).toBe(100);
    expect(factory.created[0].height).toBe(50);
  });

  it("clamps a bbox with negative coordinates", () => {
    const { graphics, factory } = createGraphics();

    graphics.beginGroup(
      0,
      makeGroup({
        needsIsolation: true,
        isolated: true,
        bbox: [-20.5, -10.5, 40.2, 30.9],
      })
    );

    // Intersection with the canvas is [0,0,40.2,30.9].
    expect(factory.created[0].width).toBe(41);
    expect(factory.created[0].height).toBe(31);
    const [[, tx, ty]] = callsNamed(factory.created[0].context, "translate");
    expect(Math.abs(tx)).toBe(0);
    expect(Math.abs(ty)).toBe(0);
  });

  it("falls back to a 1x1 canvas for an empty bbox", () => {
    const { graphics, factory } = createGraphics();

    graphics.beginGroup(
      0,
      makeGroup({
        needsIsolation: true,
        isolated: true,
        bbox: [0, 0, 0, 0],
      })
    );

    expect(factory.created[0].width).toBe(1);
    expect(factory.created[0].height).toBe(1);
  });

  it("falls back to a 1x1 canvas when the bbox is outside the canvas", () => {
    const { graphics, factory } = createGraphics();

    graphics.beginGroup(
      0,
      makeGroup({
        needsIsolation: true,
        isolated: true,
        bbox: [200, 200, 300, 300],
      })
    );

    expect(factory.created[0].width).toBe(1);
    expect(factory.created[0].height).toBe(1);
  });

  it("applies the group matrix before computing the bbox size", () => {
    const { graphics, ctx, factory } = createGraphics();

    graphics.beginGroup(
      0,
      makeGroup({
        needsIsolation: true,
        isolated: true,
        bbox: [10, 20, 60, 80],
        matrix: [2, 0, 0, 3, 0, 0],
      })
    );

    // Device-space bbox: [20,60,120,240] intersected with [0,0,100,100].
    expect(callsNamed(ctx, "transform")).toEqual([
      ["transform", 2, 0, 0, 3, 0, 0],
    ]);
    expect(factory.created[0].width).toBe(80);
    expect(factory.created[0].height).toBe(40);
    expect(callsNamed(factory.created[0].context, "translate")).toEqual([
      ["translate", -20, -60],
    ]);
    // `currentTransform` was captured before the group matrix was applied.
    expect(callsNamed(factory.created[0].context, "transform")).toEqual([
      ["transform", 1, 0, 0, 1, 0, 0],
    ]);
  });
});

describe("graphics state of the group context", () => {
  it("inherits the parent state but resets blend mode, alpha and filters", () => {
    const ctx = new MockContext(100, 100);
    ctx.fillStyle = "#123456";
    ctx.strokeStyle = "#654321";
    ctx.lineWidth = 4;
    ctx.globalAlpha = 0.5;
    ctx.globalCompositeOperation = "multiply";
    const addFilterCalls = [];
    const { graphics, factory } = createGraphics({
      ctx,
      filterFactory: {
        addFilter(value) {
          addFilterCalls.push(value);
          return "none";
        },
      },
    });

    graphics.beginGroup(
      0,
      makeGroup({ needsIsolation: true, isolated: true })
    );

    const groupCtx = factory.created[0].context;
    expect(groupCtx.fillStyle).toBe("#123456");
    expect(groupCtx.strokeStyle).toBe("#654321");
    expect(groupCtx.lineWidth).toBe(4);

    // Only the blend mode, alpha constants and transfer function are reset.
    expect(groupCtx.globalAlpha).toBe(1);
    expect(groupCtx.globalCompositeOperation).toBe("source-over");
    expect(groupCtx.filter).toBe("none");
    expect(addFilterCalls).toEqual([null]);

    expect(graphics.current.fillAlpha).toBe(1);
    expect(graphics.current.strokeAlpha).toBe(1);
    expect(graphics.current.transferMaps).toBe("none");

    // The parent state itself is left untouched.
    expect(ctx.globalAlpha).toBe(0.5);
    expect(ctx.globalCompositeOperation).toBe("multiply");
  });
});

