      expect(Array.from(unrotated.box)).toEqual([0.25, 0.25, 0.5, 0.5]);
      expect(Array.from(rotated.box)).toEqual([0.25, 0.25, 0.5, 0.5]);

      const rotatedBox = deserialize({
        points: [[25, 50, 75, 150]],
        rotation: 180,
