      expect(points).toHaveLength(1);
      expectClose(Array.from(lines[0]), [25, 50, NaN, NaN], 3);
      expectClose(Array.from(points[0]), [40, 60], 3);
    });

    test("match the lines that would be built from the points", () => {
      const fromPoints = deserialize({ points: [[25, 50, 75, 150]] });
      const fromLines = deserialize({
