          new Float32Array([
            NaN,
            NaN,
            NaN,
            NaN,
            25,
            50,
            NaN,
            NaN,
            NaN,
            NaN,
            75,
            150,
          ]),
        ],
        points: [[25, 50, 75, 150]],
      });

      expect(fromLines.toSVGPath()).toBe(fromPoints.toSVGPath());
    });

    test("null coordinates are treated as NaN", () => {
      const outline = deserialize({
        lines: [[null, null, null, null, null, null]],
        points: [[10, 10]],
      });

      expect(outline.toSVGPath()).toBe("MNaN NaNZ");
    });

    test("an empty lines list produces no path", () => {
      const outline = deserialize({ lines: [], points: [] });

      expect(outline.toSVGPath()).toBe("");
