import { InkDrawOutline } from "../../../../../src/display/editor/drawers/inkdraw.js";
import { Outline } from "../../../../../src/display/editor/drawers/outline.js";

/**
 * Call `InkDrawOutline.deserialize` with the given (page and path) options.
 * The page is 100x200 at the origin and the transforms are identity-ish when
 * nothing is overridden, which makes the expected coordinates easy to read.
 */
function deserialize({
  pageX = 0,
  pageY = 0,
  pageWidth = 100,
  pageHeight = 200,
  innerMargin = 0,
  lines,
  points,
  rotation = 0,
  thickness = 0,
} = {}) {
  return InkDrawOutline.deserialize(
    pageX,
    pageY,
    pageWidth,
    pageHeight,
    innerMargin,
    { paths: { lines, points }, rotation, thickness }
  );
}

function expectClose(actual, expected, digits = 5) {
  expect(actual).toHaveLength(expected.length);
  expected.forEach((value, i) => {
    expect(actual[i]).toBeCloseTo(value, digits);
  });
}

describe("InkDrawOutline.deserialize", () => {
  describe("returned outline", () => {
    it("is a new InkDrawOutline instance", () => {
      const outline = deserialize({ points: [] });
      const other = deserialize({ points: [] });

      expect(outline).toBeInstanceOf(InkDrawOutline);
      expect(outline.constructor).toBe(InkDrawOutline);
      expect(other).not.toBe(outline);
      expect(typeof outline.toSVGPath()).toBe("string");
      expect(outline.toSVGPath()).toBe("");
    });

    it("is an instance of the class the static method is called on", () => {
      class CustomOutline extends InkDrawOutline {}

      const outline = CustomOutline.deserialize(0, 0, 100, 200, 0, {
        paths: { lines: [], points: [] },
        rotation: 0,
        thickness: 0,
      });

      expect(outline).toBeInstanceOf(CustomOutline);
      expect(outline).toBeInstanceOf(InkDrawOutline);
      expect(outline.constructor).toBe(CustomOutline);
    });

    it("exposes the bounding box based svg properties", () => {
      const outline = deserialize({ points: [[25, 50]] });
      const { root, path, rootClass, bbox } = outline.defaultSVGProperties;

      expect(root.viewBox).toBe("2500 7500 0 0");
      expect(rootClass).toEqual({ draw: true });
      expect(path.d).toBe("M2500 7500Z");
      expect(Array.from(bbox)).toEqual([0.25, 0.75, 0, 0]);
    });

    it("stores the given thickness", () => {
      expect(
        deserialize({ points: [[50, 100]], thickness: 7.5 }).thickness
      ).toBe(7.5);
    });
  });

  describe("paths built from points", () => {
    it("a single point becomes a closed dot", () => {
      const outline = deserialize({ points: [[25, 50]] });

      expect(outline.toSVGPath()).toBe("M2500 7500Z");
      expect(Array.from(outline.box)).toEqual([0.25, 0.75, 0, 0]);
    });

    it("two points become a straight segment", () => {
      const outline = deserialize({ points: [[25, 50, 75, 150]] });

      expect(outline.toSVGPath()).toBe("M2500 7500L7500 2500");
      expect(Array.from(outline.box)).toEqual([0.25, 0.25, 0.5, 0.5]);
    });

    it("three points become a single bezier curve", () => {
      const points = [new Float32Array([25, 50, 50, 100, 75, 150])];

      const outline = deserialize({ points });

      // Control points are the (1,5,5,1)/6 smoothing of the input points and
      // the curve ends on the midpoint of the last two points.
      expect(outline.toSVGPath()).toBe(
        "M2500 7500C4583 5417 5417 4583 6250 3750"
      );

    );
  });

  it("more than three points produce one bezier per extra point", () => {
    const points = [new Float32Array([25, 50, 50, 100, 75, 150, 25, 190])];

    const outline = deserialize({ points });

    expect(outline.toSVGPath()).toBe(
      "M2500 7500C4583 5417 5417 4583 6250 3750" +
        "C7083 2917 6667 2167 5000 1500"
    );
  });

  it("a float64 point list is accepted", () => {
    const points = [new Float64Array([25, 50, 50, 100, 75, 150])];

    expect(deserialize({ points }).toSVGPath()).toBe(
      "M2500 7500C4583 5417 5417 4583 6250 3750"
    );
  });

  it("each entry of points becomes its own subpath", () => {
    const outline = deserialize({
      points: [
        [25, 50, 75, 150],
        [50, 100],
      ],
    });

    expect(outline.toSVGPath()).toBe("M2500 7500L7500 2500M5000 5000Z");
    expect(Array.from(outline.box)).toEqual([0.25, 0.25, 0.5, 0.5]);
  });

  it("an empty points list produces no path", () => {
    const outline = deserialize({ points: [] });

    expect(outline.toSVGPath()).toBe("");
  });
});

describe("rotation", () => {
  it.each([
    [0, "M2500 7500Z"],
    [90, "M2500 2500Z"],
    [180, "M7500 2500Z"],
