    [270, "M9000 9000L8000 7000", [0.8, 0.7, 0.1, 0.2]],
  ])(
    "rotates the geometry and its bounding box at rotation %i",
    (rotation, path, box) => {
      const outline = deserialize({
        points: [[10, 20, 30, 40]],
        rotation,
      });

      expect(outline.toSVGPath()).toBe(path);
      expectClose(Array.from(outline.box), box);
    }
  );
});

