import { CanvasGraphics } from "../../../src/display/canvas.js";
import { FeatureTest } from "../../../src/shared/util.js";

// ---------------------------------------------------------------------------
// Minimal Path2D stand-in: `endGroup` builds a clip path for groups that
// replace their backdrop. The real DOM class is not available in Node.
// ---------------------------------------------------------------------------
class FakePath2D {
  constructor() {
    this.operations = [];
  }

  rect(x, y, width, height) {
    this.operations.push(["rect", x, y, width, height]);
  }

  addPath(path, matrix) {
    this.operations.push(["addPath", path, matrix]);
  }
}

const originalPath2D = globalThis.Path2D;
if (typeof originalPath2D === "undefined") {
  globalThis.Path2D = FakePath2D;
}

// ---------------------------------------------------------------------------
// Fake 2D context. It records every call and keeps a real save/restore stack
// together with a simple affine matrix, so that the effects of `endGroup` on
// the parent canvas can be asserted.
// ---------------------------------------------------------------------------
const MATRIX_PROPS = ["a", "b", "c", "d", "e", "f"];

class FakeCtx {
  constructor(canvas) {
    this.canvas = canvas ?? { width: 10, height: 10 };
    this.calls = [];
    this.stack = [];
    this.matrix = [1, 0, 0, 1, 0, 0];
    this.pixels = null;

    this.strokeStyle = "#000000";
    this.fillStyle = "#000000";
    this.fillRule = "nonzero";
    this.globalAlpha = 1;
    this.lineWidth = 1;
    this.lineCap = "butt";
    this.lineJoin = "miter";
    this.miterLimit = 10;
    this.globalCompositeOperation = "source-over";
    this.font = "10px sans-serif";
    this.filter = "none";
    this.lineDashOffset = 0;
    this.imageSmoothingEnabled = true;
    this.lineDash = [];
  }

  #snapshot() {
    return {
      matrix: this.matrix.slice(),
      strokeStyle: this.strokeStyle,
      fillStyle: this.fillStyle,
      fillRule: this.fillRule,
      globalAlpha: this.globalAlpha,
      lineWidth: this.lineWidth,
      lineCap: this.lineCap,
      lineJoin: this.lineJoin,
      miterLimit: this.miterLimit,
      globalCompositeOperation: this.globalCompositeOperation,
      font: this.font,
      filter: this.filter,
      lineDashOffset: this.lineDashOffset,
      imageSmoothingEnabled: this.imageSmoothingEnabled,
      lineDash: this.lineDash.slice(),
    };
  }

  save() {
    this.calls.push({ op: "save" });
    this.stack.push(this.#snapshot());
  }

  restore() {
    this.calls.push({ op: "restore" });
    // Like a real canvas, restoring past the bottom of the stack is a no-op.
    const snapshot = this.stack.pop();
    if (snapshot) {
      Object.assign(this, snapshot);
    }
  }

  getTransform() {
    const transform = {};
    MATRIX_PROPS.forEach((prop, i) => {
      transform[prop] = this.matrix[i];
    });
    return transform;
  }

  #multiply([a2, b2, c2, d2, e2, f2]) {
    const [a1, b1, c1, d1, e1, f1] = this.matrix;
    this.matrix = [
      a1 * a2 + c1 * b2,
      b1 * a2 + d1 * b2,
      a1 * c2 + c1 * d2,
      b1 * c2 + d1 * d2,
      a1 * e2 + c1 * f2 + e1,
      b1 * e2 + d1 * f2 + f1,
    ];
  }

  setTransform(...args) {
    this.calls.push({ op: "setTransform", args });
    if (args.length === 1 && args[0] && typeof args[0] === "object") {
      this.matrix = MATRIX_PROPS.map(prop => args[0][prop]);
      return;
    }
    this.matrix = args.slice(0, 6);
  }

  transform(...args) {
    this.calls.push({ op: "transform", args });
    this.#multiply(args);
  }

  translate(x, y) {
    this.calls.push({ op: "translate", args: [x, y] });
    this.#multiply([1, 0, 0, 1, x, y]);
  }

  scale(x, y) {
    this.calls.push({ op: "scale", args: [x, y] });
    this.#multiply([x, 0, 0, y, 0, 0]);
  }

  rotate(angle) {
    this.calls.push({ op: "rotate", args: [angle] });
  }

  setLineDash(dash) {
    this.lineDash = dash.slice();
  }

  getLineDash() {
    return this.lineDash.slice();
  }

  drawImage(image, ...args) {
    this.calls.push({ op: "drawImage", image, args });
  }

  clip(path) {
    this.calls.push({ op: "clip", path });
  }

  clearRect(...args) {
    this.calls.push({ op: "clearRect", args });
  }

  fillRect(...args) {
    this.calls.push({ op: "fillRect", args });
  }

  getImageData(x, y, width, height) {
    this.calls.push({ op: "getImageData", args: [x, y, width, height] });
    const data = this.pixels ?? new Uint8ClampedArray(width * height * 4);
    return { data, width, height };
  }

  putImageData(imageData, x, y) {
    this.calls.push({ op: "putImageData", imageData, args: [x, y] });
    this.pixels = imageData.data;
  }

  createImageData(width, height) {
    return {
      width,
      height,
      data: new Uint8ClampedArray(width * height * 4),
    };
  }

  fill() {}
  stroke() {}
  beginPath() {}
  closePath() {}
  moveTo() {}
  lineTo() {}
  rect() {}
  fillText() {}
}

function ctxCalls(ctx, op) {
  return ctx.calls.filter(call => call.op === op);
}

// ---------------------------------------------------------------------------
// Fake canvas factory / filter factory / dependency tracker.
// ---------------------------------------------------------------------------
class FakeCanvasFactory {
  constructor() {
    this.created = [];
    this.destroyed = [];
  }

  create(width, height) {
    const canvas = { width, height };
    const entry = { canvas, context: new FakeCtx(canvas) };
    this.created.push(entry);
    return entry;
  }

  destroy(entry) {
    this.destroyed.push(entry);
  }
}

class FakeDependencyTracker {
  constructor() {
    this.calls = [];
  }

  recordSimpleData(...args) {
    this.calls.push(["recordSimpleData", ...args]);
  }

  save(opIdx) {
    this.calls.push(["save", opIdx]);
  }

  restore(opIdx) {
    this.calls.push(["restore", opIdx]);
  }

  pushBaseTransform(ctx) {
    this.calls.push(["pushBaseTransform", ctx]);
  }

  popBaseTransform() {
    this.calls.push(["popBaseTransform"]);
  }

  inheritSimpleDataAsFutureForcedDependencies(values) {
    this.calls.push(["inheritSimpleDataAsFutureForcedDependencies", values]);
    return this;
  }
}

function createGraphics({ width = 120, height = 80, dependencyTracker = null } = {}) {
  const ctx = new FakeCtx({ width, height });
  const canvasFactory = new FakeCanvasFactory();
  const filterFactory = {
    addFilter: () => "none",
    addKnockoutFilter: () => "none",
  };
  const graphics = new CanvasGraphics(
    ctx,
    { get() {}, has: () => false },
    { get() {} },
    canvasFactory,
    filterFactory,
    { optionalContentConfig: null, markedContentStack: null, pixelRatio: 1 },
    null,
    null,
    dependencyTracker,
    null
  );
  return { graphics, ctx, canvasFactory, filterFactory };
}

