        needsIsolation: true,
        knockout: true,
        isolated: false,
      });
      const outerCtx = graphics.ctx;

      const innerGroup = {
        needsIsolation: true,
        knockout: true,
        isolated: true,
      };
      graphics.beginGroup(1, innerGroup);
      const innerCtx = graphics.ctx;
      const innerCanvas = innerCtx.canvas;
      const createdBeforeComposite = canvasFactory.created.length;

      outerCtx.calls.length = 0;
      graphics.endGroup(1, innerGroup);

