// The project is normally run with jasmine (globals) but the generated suite is
// also expected to work with a jest/vitest style runner, where the test API is
// not injected globally. Fall back to an explicit import when needed.
const __globals = globalThis;
if (typeof __globals.describe !== "function") {
  const vitest = await import("vitest");
  for (const name of [
    "describe",
    "it",
    "test",
    "expect",
    "beforeAll",
    "afterAll",
    "beforeEach",
    "afterEach",
  ]) {
