import { CanvasGraphics } from "../../../src/display/canvas.js";
import { FeatureTest } from "../../../src/shared/util.js";

// ---------------------------------------------------------------------------
// Minimal Path2D stand-in: `endGroup` builds a clip path for groups that
// replace their backdrop. The real DOM class is not available in Node.
// ---------------------------------------------------------------------------
class FakePath2D {
  constructor() {
    this.operations = [];
  }

  rect(x, y, width, height) {
    this.operations.push(["rect", x, y, width, height]);
  }

  addPath(path, matrix) {
    this.operations.push(["addPath", path, matrix]);
  }
}

const originalPath2D = globalThis.Path2D;
if (typeof originalPath2D === "undefined") {
  globalThis.Path2D = FakePath2D;
}

// ---------------------------------------------------------------------------
// Fake 2D context. It records every call and keeps a real save/restore stack
// together with a simple affine matrix, so that the effects of `endGroup` on
// the parent canvas can be asserted.
// ---------------------------------------------------------------------------
const MATRIX_PROPS = ["a", "b", "c", "d", "e", "f"];

class FakeCtx {
  constructor(canvas) {
    this.canvas = canvas ?? { width: 10, height: 10 };
    this.calls = [];
    this.stack = [];
    this.matrix = [1, 0, 0, 1, 0, 0];
    this.pixels = null;

    this.strokeStyle = "#000000";
    this.fillStyle = "#000000";
    this.fillRule = "nonzero";
    this.globalAlpha = 1;
    this.lineWidth = 1;
    this.lineCap = "butt";
    this.lineJoin = "miter";
    this.miterLimit = 10;
    this.globalCompositeOperation = "source-over";
    this.font = "10px sans-serif";
    this.filter = "none";
    this.lineDashOffset = 0;
    this.imageSmoothingEnabled = true;
    this.lineDash = [];
  }

  #snapshot() {
    return {
      matrix: this.matrix.slice(),
      strokeStyle: this.strokeStyle,
      fillStyle: this.fillStyle,
      fillRule: this.fillRule,
      globalAlpha: this.globalAlpha,
      lineWidth: this.lineWidth,
      lineCap: this.lineCap,
      lineJoin: this.lineJoin,
      miterLimit: this.miterLimit,
      globalCompositeOperation: this.globalCompositeOperation,
      font: this.font,
      filter: this.filter,
      lineDashOffset: this.lineDashOffset,
      imageSmoothingEnabled: this.imageSmoothingEnabled,
      lineDash: this.lineDash.slice(),
    };
  }

  save() {
    this.calls.push({ op: "save" });
    this.stack.push(this.#snapshot());
  }

  restore() {
    this.calls.push({ op: "restore" });
    // Like a real canvas, restoring past the bottom of the stack is a no-op.
    const snapshot = this.stack.pop();
    if (snapshot) {
      Object.assign(this, snapshot);
    }
  }

  getTransform() {
    const transform = {};
    MATRIX_PROPS.forEach((prop, i) => {
      transform[prop] = this.matrix[i];
    });
    return transform;
  }

  #multiply([a2, b2, c2, d2, e2, f2]) {
    const [a1, b1, c1, d1, e1, f1] = this.matrix;
    this.matrix = [
      a1 * a2 + c1 * b2,
      b1 * a2 + d1 * b2,
      a1 * c2 + c1 * d2,
      b1 * c2 + d1 * d2,
      a1 * e2 + c1 * f2 + e1,
      b1 * e2 + d1 * f2 + f1,
    ];
  }

  setTransform(...args) {
    this.calls.push({ op: "setTransform", args });
    if (args.length === 1 && args[0] && typeof args[0] === "object") {
      this.matrix = MATRIX_PROPS.map(prop => args[0][prop]);
      return;
    }
    this.matrix = args.slice(0, 6);
  }

  transform(...args) {
    this.calls.push({ op: "transform", args });
    this.#multiply(args);
  }

  translate(x, y) {
    this.calls.push({ op: "translate", args: [x, y] });
    this.#multiply([1, 0, 0, 1, x, y]);
  }

  scale(x, y) {
    this.calls.push({ op: "scale", args: [x, y] });
    this.#multiply([x, 0, 0, y, 0, 0]);
  }

  rotate(angle) {
    this.calls.push({ op: "rotate", args: [angle] });
  }

  setLineDash(dash) {
    this.lineDash = dash.slice();
  }

  getLineDash() {
    return this.lineDash.slice();
  }

  drawImage(image, ...args) {
    this.calls.push({ op: "drawImage", image, args });
  }

  clip(path) {
    this.calls.push({ op: "clip", path });
  }

  clearRect(...args) {
    this.calls.push({ op: "clearRect", args });
  }

  fillRect(...args) {
    this.calls.push({ op: "fillRect", args });
  }

  getImageData(x, y, width, height) {
    this.calls.push({ op: "getImageData", args: [x, y, width, height] });
    const data = this.pixels ?? new Uint8ClampedArray(width * height * 4);
    return { data, width, height };
  }

  putImageData(imageData, x, y) {
    this.calls.push({ op: "putImageData", imageData, args: [x, y] });
    this.pixels = imageData.data;
  }

  createImageData(width, height) {
    return {
      width,
      height,
      data: new Uint8ClampedArray(width * height * 4),
    };
  }

  fill() {}
  stroke() {}
  beginPath() {}
  closePath() {}
  moveTo() {}
  lineTo() {}
  rect() {}
  fillText() {}
}

function ctxCalls(ctx, op) {
  return ctx.calls.filter(call => call.op === op);
}

// ---------------------------------------------------------------------------
// Fake canvas factory / filter factory / dependency tracker.
// ---------------------------------------------------------------------------
class FakeCanvasFactory {
  constructor() {
    this.created = [];
    this.destroyed = [];
  }

  create(width, height) {
    const canvas = { width, height };
    const entry = { canvas, context: new FakeCtx(canvas) };
    this.created.push(entry);
    return entry;
  }

  destroy(entry) {
    this.destroyed.push(entry);
  }
}

class FakeDependencyTracker {
  constructor() {
    this.calls = [];
  }

  recordSimpleData(...args) {
    this.calls.push(["recordSimpleData", ...args]);
  }

  save(opIdx) {
    this.calls.push(["save", opIdx]);
  }

  restore(opIdx) {
    this.calls.push(["restore", opIdx]);
  }

  pushBaseTransform(ctx) {
    this.calls.push(["pushBaseTransform", ctx]);
  }

  popBaseTransform() {
    this.calls.push(["popBaseTransform"]);
  }

  inheritSimpleDataAsFutureForcedDependencies(values) {
    this.calls.push(["inheritSimpleDataAsFutureForcedDependencies", values]);
    return this;
  }
}

function createGraphics({ width = 120, height = 80, dependencyTracker = null } = {}) {
  const ctx = new FakeCtx({ width, height });
  const canvasFactory = new FakeCanvasFactory();
  const filterFactory = {
    addFilter: () => "none",
    addKnockoutFilter: () => "none",
  };
  const graphics = new CanvasGraphics(
    ctx,
    { get() {}, has: () => false },
    { get() {} },
    canvasFactory,
    filterFactory,
    { optionalContentConfig: null, markedContentStack: null, pixelRatio: 1 },
    null,
    null,
    dependencyTracker,
    null
  );
  return { graphics, ctx, canvasFactory, filterFactory };
}

const canvasFilterDescriptor = Object.getOwnPropertyDescriptor(
  FeatureTest,
  "isCanvasFilterSupported"
);

function setCanvasFilterSupport(value) {
  Object.defineProperty(FeatureTest, "isCanvasFilterSupported", {
    value,
    configurable: true,
    writable: true,
  });
}

describe("CanvasGraphics#endGroup", () => {
  afterEach(() => {
    if (canvasFilterDescriptor) {
      Object.defineProperty(
        FeatureTest,
        "isCanvasFilterSupported",
        canvasFilterDescriptor
      );
    }
  });

  it("does nothing when the content is not visible", () => {
    const { graphics, ctx, canvasFactory } = createGraphics();
    graphics.contentVisible = false;
    graphics.groupLevel = 3;
    const parentState = graphics.current;

    graphics.endGroup(0, {});

    expect(graphics.groupLevel).toBe(3);
    expect(graphics.groupStack.length).toBe(0);
    expect(graphics.current).toBe(parentState);
    expect(ctx.calls.length).toBe(0);
    expect(canvasFactory.destroyed.length).toBe(0);
  });

  it("closes a simple group by restoring the parent state only", () => {
    const { graphics, ctx, canvasFactory } = createGraphics();
    let composeCalls = 0;
    graphics.compose = () => {
      composeCalls++;
    };

    graphics.beginGroup(0, {});
    expect(graphics.groupLevel).toBe(1);
    expect(graphics.groupStack.length).toBe(1);
    expect(graphics.groupStack[0]).toBe(ctx);
    // The direct-drawing path must not allocate an intermediate canvas.
    expect(canvasFactory.created.length).toBe(0);

    graphics.endGroup(0, {});

    expect(graphics.groupLevel).toBe(0);
    expect(graphics.groupStack.length).toBe(0);
    expect(graphics.ctx).toBe(ctx);
    expect(graphics.stateStack.length).toBe(0);
    expect(ctx.stack.length).toBe(0);
    // Exactly one restore, no compositing and no canvas cleanup.
    expect(ctx.calls.map(call => call.op)).toEqual(["save", "restore"]);
    expect(canvasFactory.destroyed.length).toBe(0);
    expect(composeCalls).toBe(0);
  });

  describe("groups rendered on an intermediate canvas", () => {
    function beginIntermediateGroup(graphics, group) {
      graphics.beginGroup(0, group);
      const groupCtx = graphics.ctx;
      expect(groupCtx).not.toBeUndefined();
      return groupCtx;
    }

    it("draws the group canvas back onto the parent and frees it", () => {
      const { graphics, ctx, canvasFactory } = createGraphics();
      let composedBox = null;
      graphics.compose = box => {
        composedBox = box;
      };
      ctx.matrix = [2, 0, 0, 2, 10, 20];

      const groupCtx = beginIntermediateGroup(graphics, {
        needsIsolation: true,
        isolated: true,
      });
      expect(canvasFactory.created.length).toBe(1);
      const groupCanvas = groupCtx.canvas;
      expect(groupCanvas.width).toBe(120);
      expect(groupCanvas.height).toBe(80);
      expect(graphics.groupLevel).toBe(1);

      graphics.endGroup(0, { needsIsolation: true, isolated: true });

      // Graphics state of the page is fully restored.
      expect(graphics.groupLevel).toBe(0);
      expect(graphics.groupStack.length).toBe(0);
      expect(graphics.ctx).toBe(ctx);
      expect(graphics.stateStack.length).toBe(0);
      expect(ctx.stack.length).toBe(0);
      expect(ctx.globalCompositeOperation).toBe("source-over");
      // Smoothing is disabled before the group is composited.
      expect(ctx.imageSmoothingEnabled).toBe(false);
      expect(
        ctx.calls.some(
          call => call.op === "drawImage" && call.image === groupCanvas
        )
      ).toBe(true);
      // The group canvas must be released.
      expect(canvasFactory.destroyed.length).toBe(1);
      expect(canvasFactory.destroyed[0].canvas).toBe(groupCanvas);
      expect(canvasFactory.destroyed[0].context).toBe(groupCtx);
      // ... and the dirty box handed over to compose() covers the group.
      expect(composedBox).not.toBeNull();
      expect(Array.from(composedBox)).toEqual([0, 0, 120, 80]);
    });

    it("honours the recorded group transform when compositing", () => {
      const { graphics, ctx } = createGraphics();
      let composedBox = null;
      graphics.compose = box => {
        composedBox = box;
      };
      // Half-size page transform, as produced by the viewport.
      ctx.matrix = [0.5, 0, 0, 0.5, 0, 0];

      const groupCtx = beginIntermediateGroup(graphics, {
        needsIsolation: true,
        isolated: true,
      });
      expect(groupCtx.canvas.width).toBe(60);
      expect(groupCtx.canvas.height).toBe(40);

      graphics.endGroup(0, { needsIsolation: true, isolated: true });

      expect(Array.from(composedBox)).toEqual([0, 0, 120, 80]);
    });

    it("keeps the soft mask canvas for the later compose step", () => {
      const { graphics, ctx, canvasFactory } = createGraphics();
      let composeCalls = 0;
      graphics.compose = () => {
        composeCalls++;
      };
      const group = { needsIsolation: true, smask: { subtype: "Alpha" } };

      const groupCtx = beginIntermediateGroup(graphics, group);
      const groupCanvas = groupCtx.canvas;
      expect(graphics.smaskStack.length).toBe(1);

      graphics.endGroup(0, group);

      expect(graphics.groupLevel).toBe(0);
      expect(graphics.groupStack.length).toBe(0);
      expect(graphics.ctx).toBe(ctx);
      expect(graphics.smaskStack.length).toBe(0);
      // The mask is retained on tempSMask instead of being drawn/discarded.
      expect(graphics.tempSMask).not.toBeNull();
      expect(graphics.tempSMask.canvas).toBe(groupCanvas);
      expect(ctx.calls.some(call => call.op === "drawImage")).toBe(false);
      expect(canvasFactory.destroyed.length).toBe(0);
      expect(composeCalls).toBe(0);
      expect(graphics.stateStack.length).toBe(0);
    });

    it("pops the dependency tracker base transform", () => {
      const dependencyTracker = new FakeDependencyTracker();
      const { graphics } = createGraphics({ dependencyTracker });
      const group = { needsIsolation: true, isolated: true };

      beginIntermediateGroup(graphics, group);
      graphics.endGroup(0, group);

      const names = dependencyTracker.calls.map(call => call[0]);
      expect(names).toContain("pushBaseTransform");
      expect(names).toContain("popBaseTransform");
      expect(
        names.filter(name => name === "popBaseTransform").length
      ).toBe(1);
      // The extra mirrored restore is only issued with a tracker attached.
      expect(graphics.stateStack.length).toBe(0);
    });

    it("uses the copy operator for groups that replace their backdrop", () => {
      const { graphics, ctx } = createGraphics();
      const group = {
        needsIsolation: true,
        isolated: false,
        hasSoftMask: true,
      };

      const groupCtx = beginIntermediateGroup(graphics, group);
      const groupCanvas = groupCtx.canvas;
      ctx.calls.length = 0;

      graphics.endGroup(0, group);

      const clips = ctxCalls(ctx, "clip");
      expect(clips.length).toBe(1);
      expect(clips[0].path).toBeDefined();
      expect(clips[0].path.operations).toEqual([
        ["rect", 0, 0, groupCanvas.width, groupCanvas.height],
      ]);
      const drawIndex = ctx.calls.findIndex(
        call => call.op === "drawImage" && call.image === groupCanvas
      );
      expect(drawIndex).toBeGreaterThan(-1);
      const gcoCalls = ctx.calls.filter(call => call.op === "setTransform");
      expect(gcoCalls.length).toBeGreaterThan(0);
      // The "copy" composite operation is only in effect for the draw.
      expect(ctx.globalCompositeOperation).toBe("source-over");
    });

    it("converts gray groups pixel by pixel without canvas filters", () => {
      setCanvasFilterSupport(false);
      const { graphics, canvasFactory } = createGraphics();
      const group = { needsIsolation: true, isGray: true };

      const groupCtx = beginIntermediateGroup(graphics, group);
      groupCtx.pixels = new Uint8ClampedArray([
        255, 0, 0, 255, 255, 255, 255, 128,
      ]);

      graphics.endGroup(0, group);

      expect(ctxCalls(groupCtx, "getImageData").length).toBe(1);
      const puts = ctxCalls(groupCtx, "putImageData");
      expect(puts.length).toBe(1);
      const { data } = puts[0].imageData;
      expect([data[0], data[1], data[2], data[3]]).toEqual([54, 54, 54, 255]);
      expect([data[4], data[5], data[6], data[7]]).toEqual([
        255, 255, 255, 128,
      ]);
      // The converted canvas is still composited onto the parent page.
      expect(
        canvasFactory.destroyed[0].canvas === groupCtx.canvas
      ).toBe(true);
    });

    it("converts gray groups with the canvas grayscale filter when available", () => {
      setCanvasFilterSupport(true);
      const { graphics } = createGraphics();
      const group = { needsIsolation: true, isGray: true };

      const groupCtx = beginIntermediateGroup(graphics, group);
      groupCtx.calls.length = 0;

      graphics.endGroup(0, group);

      const filtered = groupCtx.calls.filter(
        call => call.op === "drawImage" && call.image === groupCtx.canvas
      );
      expect(filtered.length).toBe(1);
      // The filter is applied in-place and the state is restored afterwards.
      expect(groupCtx.filter).toBe("none");
      expect(groupCtx.globalCompositeOperation).toBe("source-over");
      expect(groupCtx.globalAlpha).toBe(1);
      expect(ctxCalls(groupCtx, "getImageData").length).toBe(0);
    });
  });

  describe("subgroups nested inside a knockout group", () => {
    it("masks a non-isolated subgroup with its element footprint", () => {
      setCanvasFilterSupport(false);
      const { graphics, ctx, canvasFactory } = createGraphics();
      let composedBox = null;
      graphics.compose = box => {
        composedBox = box;
      };

      // Outer knockout group; its backdrop is the page canvas.
      graphics.beginGroup(0, {
        needsIsolation: true,
        knockout: true,
        isolated: false,
      });
      const outerCtx = graphics.ctx;

      // Inner non-isolated subgroup, isolated because of its geometry.
      const innerGroup = {
        needsIsolation: true,
        isolated: false,
        hasSoftMask: true,
        bbox: [10, 20, 40, 60],
      };
      graphics.beginGroup(1, innerGroup);
      const innerCtx = graphics.ctx;
      expect(innerCtx).not.toBe(outerCtx);
      expect(innerCtx.canvas.width).toBe(30);
      expect(innerCtx.canvas.height).toBe(40);
      const createdBeforeComposite = canvasFactory.created.length;
      expect(createdBeforeComposite).toBe(3); // outer, outer mask, inner

      outerCtx.calls.length = 0;
      graphics.endGroup(1, innerGroup);

      // The subgroup is composited with knockout semantics on the parent KO
      // canvas: its footprint is erased and refilled with the blended colour.
      const ops = outerCtx.calls.map(call => call.op);
      expect(ops.indexOf("drawImage")).toBeGreaterThan(-1);
      const colorDraw = outerCtx.calls.filter(
        call => call.op === "drawImage" && call.args.length === 2
      );
      expect(colorDraw.length).toBe(1);
      // The colour buffer is cropped using the recorded group offsets.
      const colorEntry = canvasFactory.created[createdBeforeComposite];
      expect(colorEntry.canvas.width).toBe(30);
      expect(colorEntry.canvas.height).toBe(40);
      const colorCtx = colorEntry.context;
      const backdropDraw = ctxCalls(colorCtx, "drawImage")[0];
      expect(Array.from(backdropDraw.args)).toEqual([
        10, 20, 30, 40, 0, 0, 30, 40,
      ]);
      // Both scratch canvases created for this composite are released again.
      expect(canvasFactory.destroyed.length).toBe(2);
      expect(canvasFactory.destroyed).toContain(colorEntry);
      expect(composedBox).not.toBeNull();
    });

    it("composites an isolated KO subgroup against the parent backdrop", () => {
      setCanvasFilterSupport(false);
      const { graphics, ctx, canvasFactory } = createGraphics();

      graphics.beginGroup(0, {
        needsIsolation: true,
        knockout: true,
        isolated: false,
      });
      const outerCtx = graphics.ctx;

      const innerGroup = {
        needsIsolation: true,
        knockout: true,
        isolated: true,
      };
      graphics.beginGroup(1, innerGroup);
      const innerCtx = graphics.ctx;
      const innerCanvas = innerCtx.canvas;
      const createdBeforeComposite = canvasFactory.created.length;

      outerCtx.calls.length = 0;
      graphics.endGroup(1, innerGroup);

      // The subgroup surface is drawn onto the KO canvas...
      expect(
        outerCtx.calls.some(
          call => call.op === "drawImage" && call.image === innerCanvas
        )
      ).toBe(true);
      // ... through a destination-out/destination-over pair.
      const gcoDraws = outerCtx.calls.filter(
        call => call.op === "drawImage"
      );
      expect(gcoDraws.length).toBeGreaterThan(1);
      // A temporary backdrop canvas is allocated from the parent canvas and
      // released again.
      const created = canvasFactory.created.slice(createdBeforeComposite);
      expect(created.length).toBeGreaterThan(1);
      const destroyed = canvasFactory.destroyed;
      expect(destroyed.length).toBeGreaterThan(1);
      // The parent KO canvas is left in its normal blending state.
      expect(outerCtx.globalCompositeOperation).toBe("source-over");
      expect(outerCtx.globalAlpha).toBe(1);
    });
  });
});
