  test("redraws horizontally and copies overlapping columns in descending order", () => {
    const { pattern, owner, tile, created, canvasFactory, renderTileCanvas } =
      createPattern({
        bbox: [5, 7, 13, 15],
        xstep: 4,
        ystep: 8,
        tileWidth: 8,
        tileHeight: 8,
      });

    const result = pattern.createPatternCanvas(owner, 42);

    expect(renderTileCanvas).toHaveBeenCalledWith(
      owner,
      42,
      { scale: 1, size: 8 },
      { scale: 1, size: 8 }
    );
    expect(canvasFactory.create).toHaveBeenCalledTimes(1);
    expect(canvasFactory.create).toHaveBeenCalledWith(4, 8);
    expect(created).toHaveLength(1);

    const [newTile] = created;
    expect(newTile.context.drawImage.mock.calls).toEqual([
      [tile.canvas, 8, 0, 4, 8, 0, 0, 4, 8],
      [tile.canvas, 4, 0, 4, 8, 0, 0, 4, 8],
      [tile.canvas, 0, 0, 4, 8, 0, 0, 4, 8],
    ]);
    expect(canvasFactory.destroy).toHaveBeenCalledTimes(1);
    expect(canvasFactory.destroy).toHaveBeenCalledWith(tile);
    expect(result).toEqual({
      canvas: newTile.canvas,
      canvasEntry: newTile,
      scaleX: 1,
      scaleY: 1,
      offsetX: 5,
      offsetY: 7,
    });
  });

  test("redraws vertically by folding rows into a temporary band", () => {
    const { pattern, owner, tile, created, canvasFactory } = createPattern({
      bbox: [0, 0, 6, 10],
      xstep: 6,
      ystep: 4,
      tileWidth: 6,
      tileHeight: 10,
    });

    const result = pattern.createPatternCanvas(owner, 3);

    expect(canvasFactory.create).toHaveBeenCalledTimes(2);
    expect(canvasFactory.create).toHaveBeenNthCalledWith(1, 6, 4);
    expect(canvasFactory.create).toHaveBeenNthCalledWith(2, 6, 4);

    const [newTile, bandCanvas] = created;
    expect(bandCanvas.context.drawImage.mock.calls).toEqual([
      [tile.canvas, 0, 8, 6, 4, 0, 0, 6, 4],
      [tile.canvas, 0, 4, 6, 4, 0, 0, 6, 4],
      [tile.canvas, 0, 0, 6, 4, 0, 0, 6, 4],
    ]);
    expect(newTile.context.drawImage.mock.calls).toEqual([
      [bandCanvas.canvas, 0, 0, 6, 4, 0, 0, 6, 4],
    ]);
    expect(canvasFactory.destroy).toHaveBeenNthCalledWith(1, bandCanvas);
    expect(canvasFactory.destroy).toHaveBeenNthCalledWith(2, tile);
    expect(result.canvasEntry).toBe(newTile);
    expect(result.scaleX).toBe(1);
    expect(result.scaleY).toBe(1);
    expect(result.offsetX).toBe(0);
    expect(result.offsetY).toBe(0);
  });

  test("folds both dimensions without drawing every offset pair", () => {
    const { pattern, owner, tile, created, canvasFactory } = createPattern({
      bbox: [0, 0, 8, 10],
      xstep: 4,
      ystep: 5,
      tileWidth: 8,
      tileHeight: 10,
    });

    const result = pattern.createPatternCanvas(owner, 99);

    expect(canvasFactory.create).toHaveBeenCalledTimes(2);
    expect(canvasFactory.create).toHaveBeenNthCalledWith(1, 4, 5);
    expect(canvasFactory.create).toHaveBeenNthCalledWith(2, 8, 5);

    const [newTile, bandCanvas] = created;
    expect(bandCanvas.context.drawImage).toHaveBeenCalledTimes(3);
    expect(newTile.context.drawImage).toHaveBeenCalledTimes(3);
    expect(bandCanvas.context.drawImage.mock.calls).toEqual([
      [tile.canvas, 0, 10, 8, 5, 0, 0, 8, 5],
      [tile.canvas, 0, 5, 8, 5, 0, 0, 8, 5],
      [tile.canvas, 0, 0, 8, 5, 0, 0, 8, 5],
    ]);
    expect(newTile.context.drawImage.mock.calls).toEqual([
      [bandCanvas.canvas, 8, 0, 4, 5, 0, 0, 4, 5],
      [bandCanvas.canvas, 4, 0, 4, 5, 0, 0, 4, 5],
      [bandCanvas.canvas, 0, 0, 4, 5, 0, 0, 4, 5],
    ]);
    expect(canvasFactory.destroy).toHaveBeenNthCalledWith(1, bandCanvas);
    expect(canvasFactory.destroy).toHaveBeenNthCalledWith(2, tile);
    expect(result.canvasEntry).toBe(newTile);
    expect(result.offsetX).toBe(0);
    expect(result.offsetY).toBe(0);
  });

  test("combines matrix and base-transform scales when sizing tiles", () => {
    const { pattern, owner, tile, created, canvasFactory, renderTileCanvas } =
      createPattern({
        bbox: [1, 2, 21, 12],
        xstep: 10,
        ystep: 5,
        matrix: [2, 0, 0, 3, 0, 0],
        tileWidth: 40,
        tileHeight: 30,
      });

    const result = pattern.createPatternCanvas(owner, 11);

    expect(renderTileCanvas).toHaveBeenCalledWith(
      owner,
      11,
      { scale: 3, size: 60 },
      { scale: 2, size: 20 }
    );
    expect(canvasFactory.create).toHaveBeenCalledTimes(2);
    expect(canvasFactory.create).toHaveBeenNthCalledWith(1, 30, 10);
    expect(canvasFactory.create).toHaveBeenNthCalledWith(2, 40, 10);

    const [newTile] = created;
    expect(newTile.context.drawImage).toHaveBeenCalledTimes(3);
    expect(result.canvasEntry).toBe(newTile);
    expect(result.scaleX).toBe(3);
    expect(result.scaleY).toBe(2);
    expect(result.offsetX).toBe(1);
    expect(result.offsetY).toBe(2);
    expect(canvasFactory.destroy).toHaveBeenCalledWith(tile);
  });

  test("clamps tile dimensions to TilingPattern.MAX_PATTERN_SIZE", () => {
    const { pattern, owner, tile, canvasFactory, renderTileCanvas } =
      createPattern({
        bbox: [0, 0, 20, 10],
        xstep: 20,
        ystep: 10,
        matrix: [200, 0, 0, 200, 0, 0],
        outputWidth: 100,
        outputHeight: 100,
        tileWidth: 3000,
        tileHeight: 2000,
      });

    const result = pattern.createPatternCanvas(owner, 1);

    expect(renderTileCanvas).toHaveBeenCalledWith(
      owner,
      1,
      { scale: 200, size: 3000 },
      { scale: 200, size: 2000 }
    );
    expect(result.canvasEntry).toBe(tile);
    expect(result.scaleX).toBe(200);
    expect(result.scaleY).toBe(200);
    expect(result.offsetX).toBe(0);
    expect(result.offsetY).toBe(0);
    expect(canvasFactory.create).not.toHaveBeenCalled();
    expect(canvasFactory.destroy).not.toHaveBeenCalled();
  });
});

