        const data = { id: obj._id };
        data[prop] = prop === "value" ? obj._getValue() : obj[prop];

        // send the updated value to the other side
        if (!obj._siblings) {
          obj._send(data);
        } else {
          data.siblings = obj._siblings;
          obj._send(data);
        }
