const sentData = () => calls.filter(c => c[0] === "send").map(c => c[1][0]);
const clearCalls = () => {
  calls.length = 0;
};

describe("initSandbox", () => {
  beforeAll(() => {
    globalThis.callExternalFunction = (...args) => {
      calls.push(args);
    };
    globalThis.pdfjsScripting = { initSandbox };

    // Jest's "node" test environment exposes `globalThis` through a Proxy
    // whose target is a plain object: adding a non configurable accessor to
    // such a proxy violates the proxy invariants, which can never happen in
    // the QuickJS sandbox used in production. Make the document properties
    // configurable while initializing the sandbox so that the initialization
    // can complete (the `writable` flags are left untouched).
    const originalDefineProperties = Object.defineProperties;
    Object.defineProperties = (target, descriptors) => {
      for (const key of Reflect.ownKeys(descriptors)) {
        Reflect.defineProperty(target, key, {
          ...descriptors[key],
          configurable: true,
        });
      }
      return target;
    };
    try {
      runSandboxCallback = initSandbox(buildParams());
    } finally {
      Object.defineProperties = originalDefineProperties;
    }
  });

  afterAll(() => {
    globalThis.console = realConsole;
  });

  beforeEach(() => {
    clearCalls();
  });

  describe("sandbox bootstrap", () => {
    it("removes the bootstrap globals used to set up the sandbox", () => {
      expect(globalThis.pdfjsScripting).toBeUndefined();
      expect(Object.hasOwn(globalThis, "callExternalFunction")).toBe(false);
      expect(typeof runSandboxCallback).toBe("function");
    });

    it("resets the event global and creates an empty global object", () => {
      expect(globalThis.event).toBeNull();
      expect(globalThis.global).not.toBeNull();
      expect(Object.getPrototypeOf(globalThis.global)).toBeNull();
      expect(Reflect.ownKeys(globalThis.global)).toEqual([]);
    });

    it("exposes the Acrobat constants", () => {
      expect(globalThis.border).toBe(Border);
      expect(globalThis.border.s).toBe("solid");
      expect(globalThis.cursor).toBe(Cursor);
      expect(globalThis.display).toBe(Display);
      expect(globalThis.font).toBe(Font);
      expect(globalThis.highlight).toBe(Highlight);
      expect(globalThis.position).toBe(Position);
      expect(globalThis.scaleHow).toBe(ScaleHow);
      expect(globalThis.scaleWhen).toBe(ScaleWhen);
      expect(globalThis.style).toBe(Style);
      expect(globalThis.trans).toBe(Trans);
      expect(globalThis.zoomtype).toBe(ZoomType);
      expect(Object.isFrozen(globalThis.border)).toBe(true);
    });

    it("exposes the global constants as non writable properties", () => {
      for (const [name, value] of Object.entries(GlobalConstants)) {
        const descriptor = Object.getOwnPropertyDescriptor(globalThis, name);
        expect(descriptor).toBeDefined();
        expect(descriptor.value).toBe(value);
        expect(descriptor.writable).toBe(false);
      }
      expect(globalThis.IDS_GREATER_THAN).toBe(
        "Invalid value: must be greater than or equal to % s."
      );
    });

    it("does not let a script overwrite a global constant", () => {
      expect(() => {
        globalThis.IDS_LESS_THAN = "changed";
      }).toThrow(TypeError);
      expect(globalThis.IDS_LESS_THAN).toBe(GlobalConstants.IDS_LESS_THAN);
    });

    it("exposes the color helpers as writable properties", () => {
      const convertDescriptor = Object.getOwnPropertyDescriptor(
        globalThis,
        "ColorConvert"
      );
      const equalDescriptor = Object.getOwnPropertyDescriptor(
        globalThis,
        "ColorEqual"
      );
      expect(convertDescriptor.writable).toBe(true);
      expect(equalDescriptor.writable).toBe(true);

      expect(globalThis.ColorConvert(["G", 0.5], "RGB")).toEqual([
        "RGB",
        0.5,
        0.5,
        0.5,
      ]);
      expect(globalThis.ColorConvert(["T"], "G")).toEqual(["G", 0]);
      expect(globalThis.ColorConvert(["G", 0], "not-a-space")).toEqual([
        "G",
        0,
      ]);
      expect(globalThis.ColorEqual(["G", 0], ["G", 0])).toBe(true);
      expect(globalThis.ColorEqual(["RGB", 1, 1, 1], ["G", 0])).toBe(false);
      expect(globalThis.ColorEqual(["T"], ["T"])).toBe(true);
    });

    it("avoids the Acrobat update popup", () => {
      expect(globalThis.ADBE).toEqual({
        Reader_Value_Asked: true,
        Viewer_Value_Asked: true,
      });
    });

    it("exposes the AF functions but not the private AForm helpers", () => {
      const publicNames = Object.getOwnPropertyNames(AForm.prototype).filter(
        name => name !== "constructor" && !name.startsWith("_")
      );
      expect(publicNames.length).toBeGreaterThan(0);
      for (const name of publicNames) {
        expect(typeof globalThis[name]).toBe("function");
      }
      expect(globalThis._parseDate).toBeUndefined();
      expect(globalThis._mkTargetName).toBeUndefined();

      // The functions must be already bound to the AForm instance.
      const makeNumber = globalThis.AFMakeNumber;
      expect(makeNumber("1,5")).toBe(1.5);
      expect(makeNumber("not a number")).toBeNull();
      expect(globalThis.AFMakeArrayFromList("a, b,c")).toEqual(["a", "b", "c"]);
    });

    it("exposes the document properties and methods on the global scope", () => {
      expect(globalThis.title).toBe("Sandbox Document");
      expect(globalThis.author).toBe("PDF.js");
      expect(globalThis.numPages).toBe(3);
      expect(globalThis.URL).toBe("https://example.com/test.pdf");
      expect(globalThis.numFields).toBe(6);
      expect(typeof globalThis.getField).toBe("function");
      expect(typeof globalThis.getNthFieldName).toBe("function");
      expect(typeof globalThis.print).toBe("function");
      // Private document properties must not be leaked.
      expect(globalThis._fields).toBeUndefined();
      expect(globalThis._addField).toBeUndefined();
    });

    it("exposes app, color, console and util through proxies", () => {
      expect(globalThis.app.viewerType).toBe("PDF.js");
      expect(globalThis.app.language).toBe("ENU");
      expect(globalThis.app.platform).toBe("UNIX");

      expect(globalThis.color.red).toEqual(["RGB", 1, 0, 0]);
      expect(globalThis.color.transparent).toEqual(["T"]);
      expect(typeof globalThis.util.printd).toBe("function");
      expect(typeof globalThis.console.println).toBe("function");

      // The proxy only exposes public properties.
      expect(globalThis.app._objects).toBeUndefined();
    });
  });

  describe("document fields", () => {
    it("registers the fields in the document", () => {
      expect(globalThis.getNthFieldName(0)).toBe("firstName");
      expect(globalThis.getNthFieldName(1)).toBe("nickname");
      expect(globalThis.getField("nope")).toBeNull();
      expect(() => globalThis.getField(42)).toThrow(TypeError);
    });

    it("creates a text field with its value and document", () => {
      const field = globalThis.getField("firstName");
      expect(field).not.toBeNull();
      expect(field.name).toBe("firstName");
      expect(field.type).toBe("text");
      expect(field.value).toBe("Alice");
      expect(field.doc.numPages).toBe(3);
    });

    it("creates a checkbox field", () => {
      const field = globalThis.getField("agree");
      expect(field.type).toBe("checkbox");
      expect(field.value).toBe("Yes");
      expect(field.exportValues).toEqual(["Yes"]);
    });

    it("creates a radio button field with all its widgets", () => {
      const field = globalThis.getField("shade");
      expect(field.type).toBe("radiobutton");
      expect(field.exportValues).toEqual(["Red", "Blue"]);
      expect(field.isBoxChecked(0)).toBe(true);
      expect(field.isBoxChecked(1)).toBe(false);

      field.checkThisBox(1);
      expect(field.isBoxChecked(1)).toBe(true);
      expect(field.isBoxChecked(0)).toBe(false);
      expect(sentData()).toEqual([{ id: "31R", value: "Blue" }]);
    });

    it("creates a field for a container without annotations", () => {
      const field = globalThis.getField("parent");
      expect(field).not.toBeNull();
      expect(field.type).toBe("");
      expect(field.value).toBe("");
    });

    it("sends the value with the ids of the sibling widgets", () => {
      const field = globalThis.getField("group");
      field.value = "updated";
      expect(field.value).toBe("updated");
      expect(sentData()).toEqual([
        { id: "50R", siblings: ["51R"], value: "updated" },
      ]);
    });

    it("sends the new value of a text field", () => {
      const field = globalThis.getField("nickname");
      field.value = "42";
      expect(field.value).toBe(42);
      expect(sentData()).toEqual([{ id: "11R", value: "42" }]);
    });

    it("sends the new value of a checkbox field", () => {
      const field = globalThis.getField("agree");
      field.value = "Off";
      expect(field.value).toBe("Off");
      expect(sentData().length).toBe(1);
      expect(sentData()[0].id).toBe("20R");
      expect(sentData()[0].value).toBe("Off");
    });

    it("forwards console output to the embedder", () => {
      globalThis.console.println("hello");
      expect(sentData()).toEqual([
        { command: "println", value: "PDF.js Console:: hello" },
      ]);
    });
  });

  describe("sandbox callback", () => {
    it("dispatches a document event", () => {
      runSandboxCallback("dispatchEvent", { id: "doc", name: "Open" });

      // The "Open" event enables the user activation and runs the format
      // actions of every field.
      expect(globalThis.event).not.toBeNull();
      expect(globalThis.__firstNameFormat).toBe(true);
      const activationCalls = calls.filter(
        c => c[0] === "setTimeout" && c[1][0] === 0
      );
      expect(activationCalls.length).toBeGreaterThan(0);
      expect(sentData()).toEqual([]);
    });

    it("dispatches an event on an annotation", () => {
      runSandboxCallback("dispatchEvent", { id: "10R", name: "MouseUp" });

      expect(globalThis.__firstNameMouseUp).toBe(true);
      expect(globalThis.event.name).toBe("MouseUp");
      expect(sentData()).toEqual([]);
    });

    it("reports an error thrown by an action", () => {
      runSandboxCallback("dispatchEvent", { id: "11R", name: "MouseUp" });

      const data = sentData();
      expect(data.length).toBe(1);
      expect(data[0].command).toBe("error");
      expect(data[0].value).toContain('Error when executing "MouseUp"');
      expect(data[0].value).toContain('for field "11R"');
      expect(data[0].value).toContain("action boom");
    });

    it("dispatches an event on a container field", () => {
      runSandboxCallback("dispatchEvent", { id: "40R", name: "MouseUp" });

      expect(globalThis.event.name).toBe("MouseUp");
      expect(calls.some(c => c[0] === "setTimeout")).toBe(true);
    });

    it("ignores events sent to unknown objects", () => {
      runSandboxCallback("dispatchEvent", { id: "unknown", name: "MouseUp" });

      expect(calls).toEqual([]);
    });

    it("reports an error thrown while dispatching an event", () => {
      // The container field has no send callback, hence dispatching a
      // keystroke event on it fails.
      expect(() =>
        runSandboxCallback("dispatchEvent", { id: "40R", name: "Keystroke" })
      ).not.toThrow();

      const data = sentData();
      expect(data.length).toBe(1);
      expect(data[0].command).toBe("error");
      expect(data[0].value).toContain("TypeError");
    });

    it("runs a registered timeout callback", () => {
      globalThis.app.setTimeOut("globalThis.__timeoutRan = true", 100);
      const timeoutCall = calls.find(c => c[0] === "setTimeout");
      expect(timeoutCall).toBeDefined();
      const [callbackId, delay] = timeoutCall[1];
      expect(delay).toBe(100);

      runSandboxCallback("timeoutCb", { callbackId, interval: false });
      expect(globalThis.__timeoutRan).toBe(true);
      expect(sentData()).toEqual([]);
    });

    it("accepts the user activation callback id", () => {
      runSandboxCallback("timeoutCb", { callbackId: 0, interval: false });

      expect(calls).toEqual([]);
    });

    it("serializes an error when an unknown function is called", () => {
      expect(() => runSandboxCallback("unknownFunction", {})).not.toThrow();

      const data = sentData();
      expect(data.length).toBe(1);
      expect(data[0].command).toBe("error");
      expect(data[0].value).toContain("TypeError");
    });
  });
});

